def _mod_srcversion(name):
    """A stable per-module srcversion. modinfo prints one and /sys/module
    keeps a copy; they have to be the same 32 hex digits."""
    import hashlib
    return hashlib.md5(("srcver:" + name).encode()).hexdigest().upper()


