def _kernel_config():
    """A /boot/config-* of the right shape and size (132555 bytes real).

    Generated rather than stored verbatim: the real file is 132KB of
    CONFIG_* lines and only its head, its size and its plausibility are
    observable. Deterministic so the size and any hash stay put.
    """
    head = ("#\n# Automatically generated file; DO NOT EDIT.\n"
            "# Linux/x86 6.12.101 Kernel Configuration\n#\n"
            "CONFIG_CC_VERSION_TEXT=\"x86_64-linux-gnu-gcc-14 (Debian "
            "14.2.0-19) 14.2.0\"\n"
            "CONFIG_GCC_VERSION=140200\n"
            "CONFIG_CLANG_VERSION=0\n"
            "CONFIG_64BIT=y\nCONFIG_X86_64=y\nCONFIG_X86=y\n"
            "CONFIG_LOCALVERSION=\"\"\n"
            "CONFIG_EXT4_FS=y\nCONFIG_VIRTIO_NET=m\n")
    rnd = random.Random("kconfig v1")
    words = ("BLK_DEV", "NET_VENDOR", "SND_SOC", "USB", "PCI", "CRYPTO",
             "NF_TABLES", "DRM", "SCSI", "MEDIA", "IIO", "REGULATOR",
             "PINCTRL", "MFD", "HID", "INFINIBAND", "MTD", "SERIAL")
    out = [head]
    n = len(head)
    i = 0
    while n < 132_555:
        i += 1
        line = "CONFIG_%s_%s=%s\n" % (
            rnd.choice(words), rnd.randrange(1000, 99999),
            rnd.choice(("y", "m", "n", "y", "m")))
        out.append(line)
        n += len(line)
    body = "".join(out)
    return body[:132_555]


def _grub_cfg():
    """/boot/grub/grub.cfg -- 5959 bytes on the image this persona copies."""
    head = ("#\n# DO NOT EDIT THIS FILE\n#\n"
            "# It is automatically generated by grub-mkconfig using templates\n"
            "# from /etc/grub.d and settings from /etc/default/grub\n#\n\n"
            "### BEGIN /etc/grub.d/00_header ###\n"
            "if [ -s $prefix/grubenv ]; then\n"
            "  set have_grubenv=true\n  load_env\nfi\n"
            "if [ \"${next_entry}\" ] ; then\n"
            "   set default=\"${next_entry}\"\n"
            "   set next_entry=\n   save_env next_entry\n"
            "   set boot_once=true\nelse\n"
            "   set default=\"0\"\nfi\n\n"
            "terminal_input console\nterminal_output console\n"
            "set timeout=5\n"
            "### END /etc/grub.d/00_header ###\n\n"
            "### BEGIN /etc/grub.d/10_linux ###\n"
            "menuentry 'Debian GNU/Linux' --class debian --class gnu-linux "
            "--class gnu --class os $menuentry_id_option "
            "'gnulinux-simple-4f1a0c2e-3b7d-4a91-9c5e-8d2f6b0a1e34' {\n"
            "\tload_video\n\tinsmod gzio\n\tinsmod part_gpt\n"
            "\tinsmod ext2\n\tsearch --no-floppy --fs-uuid --set=root "
            "4f1a0c2e-3b7d-4a91-9c5e-8d2f6b0a1e34\n"
            "\techo\t'Loading Linux %s ...'\n"
            "\tlinux\t/boot/vmlinuz-%s root=UUID="
            "4f1a0c2e-3b7d-4a91-9c5e-8d2f6b0a1e34 ro console=tty0 "
            "console=ttyS0,115200 earlyprintk=ttyS0,115200 "
            "consoleblank=0 systemd.show_status=true\n"
            "\techo\t'Loading initial ramdisk ...'\n"
            "\tinitrd\t/boot/initrd.img-%s\n}\n"
            "### END /etc/grub.d/10_linux ###\n" % (KERNEL, KERNEL, KERNEL))
    pad = ("\n### BEGIN /etc/grub.d/30_os-prober ###\n"
           "### END /etc/grub.d/30_os-prober ###\n"
           "\n### BEGIN /etc/grub.d/40_custom ###\n"
           "# This file provides an easy way to add custom menu entries.\n"
           "### END /etc/grub.d/40_custom ###\n"
           "\n### BEGIN /etc/grub.d/41_custom ###\n"
           "if [ -f  ${config_directory}/custom.cfg ]; then\n"
           "  source ${config_directory}/custom.cfg\n"
           "elif [ -z \"${config_directory}\" -a -f  $prefix/custom.cfg ]; "
           "then\n  source $prefix/custom.cfg\nfi\n"
           "### END /etc/grub.d/41_custom ###\n")
    body = head + pad
    if len(body) < 5959:
        body += "#" * (5959 - len(body) - 1) + "\n"
    return body[:5959]


# What `file` says about each blob kind, taken from the real image rather
# than invented: the bzImage line in particular is long and specific, and
# "data" is what an attacker gets on a box where /boot is scenery.
_BLOB_FILE_DESC = {
    # The build date came from a literal, so `file /boot/vmlinuz-*` dated
    # the kernel 2026-08-05 while `uname -v`, /proc/version and
    # /proc/sys/kernel/version all dated it 2026-07-01. One command against
    # another, and the kernel image is what an attacker checks before
    # choosing an exploit.
    "bzimage": (
        "Linux kernel x86 boot executable, bzImage, version "
        "%s (debian-kernel@lists.debian.org) %s, RO-rootFS, Normal "
        "VGA, setup size 512*39, syssize 0xb2420, jump 0x26c "
        "0x8cd88ec0fc8cd239 instruction, protocol 2.15, from protected-mode "
        "code at offset 0x2cc 0xaed008 bytes ZST compressed, relocatable, "
        "handover offset 0xb11620, legacy 64-bit entry point, can be above "
        "4G, 32-bit EFI handoff entry point, 64-bit EFI handoff entry point, "
        "EFI kexec boot support, xloadflags bit 5, max cmdline size 2047, "
        "init_size 0x37dc000") % (KERNEL, KERNEL_VER),
    "cpio": "ASCII cpio archive (SVR4 with no CRC)",
    "efi": "PE32+ executable (EFI application) x86-64, for MS Windows",
}


# e_machine values this kernel can actually run. A 64-bit x86 kernel with
# CONFIG_IA32_EMULATION -- which Debian's cloud kernel has -- runs both
# x86-64 and i386. Everything else gets ENOEXEC from the kernel and
# "cannot execute binary file: Exec format error" from bash.
_ELF_RUNNABLE = {0x3E: "x86-64", 0x03: "i386"}
_ELF_MACHINES = {0x28: "ARM", 0xB7: "AArch64", 0xF3: "RISC-V",
                 0x08: "MIPS", 0x14: "PowerPC", 0x15: "PowerPC64",
                 0x02: "SPARC", 0x32: "IA-64", 0x16: "S390"}


def _elf_unrunnable(data):
    """Why this ELF cannot run here, or None if it can.

    Reads e_machine at offset 18 of the header. Only enough parsing to
    answer the question bash answers.
    """
    if len(data) < 20:
        return "truncated ELF header (%d bytes)" % len(data)
    if data[4] not in (1, 2):
        return "bad EI_CLASS %d" % data[4]
    little = data[5] == 1
    machine = int.from_bytes(data[18:20], "little" if little else "big")
    if machine in _ELF_RUNNABLE:
        # A 32-bit header claiming x86-64, or the reverse, is malformed.
        want64 = machine == 0x3E
        if want64 != (data[4] == 2):
            return "EI_CLASS/e_machine mismatch"
        return None
    return "e_machine 0x%02X (%s)" % (
        machine, _ELF_MACHINES.get(machine, "unknown architecture"))


def _dd_secs(secs):
    """dd prints elapsed time to six significant digits, no trailing zeros."""
    return ("%.6g" % secs)


def _dd_rate(n, secs=0.0001):
    """dd scales its throughput figure; a 3-byte copy is kB/s, not GB/s.

    `secs` has to be the same elapsed time dd printed on the line above:
    a 200 MiB copy that claims 0.0446 s and 2097.2 GB/s divides out to a
    different number than the two it prints.
    """
    r = n / max(secs, 1e-9)
    for unit, f in (("GB/s", 1e9), ("MB/s", 1e6), ("kB/s", 1e3)):
        if r >= f:
            return "%.1f %s" % (r / f, unit)
    return "%.0f B/s" % r


def _dd_units(n):
    """GNU dd's byte-count phrase, boundaries included.

    Measured on the guest rather than guessed, because every boundary
    differs:

        1        -> "1 byte copied"
        3        -> "3 bytes copied"
        999      -> "999 bytes copied"          no parenthetical at all
        1000     -> "1000 bytes (1.0 kB)"       decimal only
        1024     -> "1024 bytes (1.0 kB, 1.0 KiB)"
        1048576  -> "1048576 bytes (1.0 MB, 1.0 MiB)"

    The binary half appears only once the count reaches 1024, so a value
    between 1000 and 1023 gets one unit and not two.
    """
    word = "byte" if n == 1 else "bytes"
    dec = [("kB", 1e3), ("MB", 1e6), ("GB", 1e9), ("TB", 1e12)]
    binu = [("KiB", 1024), ("MiB", 1024 ** 2), ("GiB", 1024 ** 3),
            ("TiB", 1024 ** 4)]
    d = [(u, n / f) for u, f in dec if n >= f]
    b = [(u, n / f) for u, f in binu if n >= f]
    if not d:
        return "%d %s" % (n, word)
    # Three significant digits, which means one decimal place below ten
    # and none above it: the guest prints "210 MB, 200 MiB" for 209715200
    # and "1.0 MB, 1.0 MiB" for 1048576. A flat %.1f gave "209.7 MB".
    def _fig(v, u):
        return ("%.1f %s" if v < 10 else "%.0f %s") % (v, u)

    parts = [_fig(d[-1][1], d[-1][0])]
    if b:
        parts.append(_fig(b[-1][1], b[-1][0]))
    return "%d %s (%s)" % (n, word, ", ".join(parts))


def _is_kthread(cmd):
    """ps renders a kernel thread's comm in brackets because its cmdline is
    empty. That bracketing is the only marker the process listing carries,
    so it is what everything else derives from."""
    c = (cmd or "").strip()
    return c.startswith("[") and c.endswith("]")


# comm -> the binary /proc/<pid>/exe points at. Measured on the guest:
# pid 1 resolves to /usr/lib/systemd/systemd, not to the /sbin/init symlink
# that appears in its cmdline.
_EXE_PATHS = {
    "systemd": "/usr/lib/systemd/systemd",
    "sshd": "/usr/sbin/sshd",
    # Not /usr/bin/sshd-session, which is where the "/usr/bin/ + comm"
    # fallback put it and where no Debian has ever kept it.
    "sshd-session": "/usr/lib/openssh/sshd-session",
    "nginx": "/usr/sbin/nginx",
    "cron": "/usr/sbin/cron",
    "mariadbd": "/usr/sbin/mariadbd",
    "mysqld": "/usr/sbin/mysqld",
    "php-fpm8.4": "/usr/sbin/php-fpm8.4",
    "agetty": "/usr/sbin/agetty",
    "rsyslogd": "/usr/sbin/rsyslogd",
    "dhclient": "/usr/sbin/dhclient",
    # Measured, not derived: udevd is a symlink-invoked mode of udevadm.
    "systemd-udevd": "/usr/bin/udevadm",
}
# How many listening/connected sockets a daemon holds above fd 2. Real sshd
# had eight fds total; a bare service has three.
_LISTEN_FDS = {"sshd": 5, "nginx": 4, "mariadbd": 6, "mysqld": 6,
               "php-fpm8.4": 3}


# The pre-merge prefixes are symlinks into /usr on Debian, and exe reports
# the *resolved* path while cmdline keeps whatever was exec'd. Measured:
# systemd-journald's cmdline is /lib/systemd/systemd-journald and its exe is
# /usr/lib/systemd/systemd-journald; agetty's are /sbin/agetty and
# /usr/sbin/agetty.
_USR_MERGE = (("/lib/", "/usr/lib/"), ("/sbin/", "/usr/sbin/"),
              ("/bin/", "/usr/bin/"))


def _exe_path(pid, comm, cmd):
    """Where /proc/<pid>/exe points.

    Deriving this from comm was wrong twice over: comm is truncated to 15
    bytes by the kernel, so systemd-journald became
    /usr/lib/systemd/systemd-journal, and a daemon that rewrites argv[0]
    gave nonsense like /usr/bin/sshd: -- with the colon.
    """
    if pid == 1:
        # cmdline says /sbin/init, but that is a symlink and exe resolves
        # past it to the real binary.
        return "/usr/lib/systemd/systemd"
    name = (comm or "").rstrip(":")
    if name in _EXE_PATHS:
        return _EXE_PATHS[name]
    first = (cmd or "").lstrip("-").split(" ")[0]
    if first.startswith("/"):
        for pre, full in _USR_MERGE:
            if first.startswith(pre):
                return full + first[len(pre):]
        return first
    if not name:
        name = os.path.basename(first) or "false"
    return "/usr/bin/" + name


