def _ca_subject(name):
    """Debian derives the filename from the subject by replacing runs of
    non-alphanumerics with underscores; go back the other way so
    `openssl x509 -subject` and the filename cannot disagree."""
    cn = name.replace("_", " ").strip()
    org = cn.split()[0]
    # openssl 3 prints RDNs in the certificate's own order, which for these
    # roots is country, organisation, common name -- least specific first.
    # Emitting CN first was backwards against every real root cert.
    return "C = US, O = %s, CN = %s" % (org, cn)


def _ca_hash(name):
    """The 8-hex subject hash openssl uses for the <hash>.0 link name."""
    import hashlib
    return hashlib.md5(("subject:" + name).encode()).hexdigest()[:8]


def _ca_pem(name):
    """A deterministic PEM body for one CA. Generated rather than stored:
    one VFS per source IP, and 85 certificates is a quarter of a megabyte
    that would otherwise be paid per attacker."""
    rnd = random.Random("ca v1 " + name)
    der = bytes(rnd.getrandbits(8) for _ in range(1180))
    b = base64.b64encode(der).decode()
    return ("-----BEGIN CERTIFICATE-----\n"
            + "\n".join(b[i:i + 64] for i in range(0, len(b), 64))
            + "\n-----END CERTIFICATE-----\n")


_OPENSSL_CNF = """\
openssl_conf = default_conf

[ default_conf ]
ssl_conf = ssl_sect

[ ssl_sect ]
system_default = system_default_sect

[ system_default_sect ]
CipherString = DEFAULT:@SECLEVEL=2

[ ca ]
default_ca\t= CA_default

[ CA_default ]
dir\t\t= ./demoCA
certs\t\t= $dir/certs
crl_dir\t\t= $dir/crl
database\t= $dir/index.txt
new_certs_dir\t= $dir/newcerts
certificate\t= $dir/cacert.pem
serial\t\t= $dir/serial
private_key\t= $dir/private/cakey.pem
default_days\t= 365
default_md\t= default
policy\t\t= policy_match

[ policy_match ]
countryName\t\t= match
organizationName\t= match
commonName\t\t= supplied

[ req ]
default_bits\t\t= 2048
distinguished_name\t= req_distinguished_name
string_mask\t\t= utf8only

[ req_distinguished_name ]
countryName\t\t\t= Country Name (2 letter code)
countryName_default\t\t= AU
commonName\t\t\t= Common Name (e.g. server FQDN or YOUR name)
commonName_max\t\t\t= 64
"""


# The most any single synthesised file will ever put in memory when read.
# The seeded blobs (vmlinuz, initrd) are well under this; a sparse file an
# attacker asked for may be far larger, and must not be materialised.
BLOB_READ_CAP = 32 << 20


def node_size(node, path=None):
    """How big the inode says it is -- the one answer every reader uses.

    There were two: this rule, used by ls, stat and du, and a separate
    len(content) in the VFS block accounting used by df. They agree for a
    file whose bytes are stored and disagree for every file whose bytes are
    synthesised on read, which is every ELF and anything truncate,
    fallocate or dd produced.
    """
    if node is None:
        return 4096
    if path is not None and (path == "/proc" or path.startswith("/proc/")):
        # Every file under /proc reports size 0, links included: procfs
        # does not know how long its answers are until it generates them.
        # `ls -l /proc/1/cwd` showed 1 -- the length of "/" -- next to a
        # /proc/1/cmdline of 0, so the same directory was half real and
        # half invented.
        #
        # The one exception, measured on the guest: a descriptor link under
        # /proc/<pid>/fd is 64, where cwd, exe and root beside it are 0.
        if re.match(r"^/proc/(?:\d+|self|thread-self)/fd/\d+$", path):
            return 64
        return 0
    if path is not None and (path == "/sys" or path.startswith("/sys/")):
        # sysfs is the other way round: a directory is 0 and every
        # attribute file is one page, whatever it holds. We printed the
        # length of the string, so `ls -l /sys/class/net/eth0/address` said
        # 18 where every Linux says 4096.
        return 0 if node.is_dir else 4096
    if node.elf:
        return node.elf[1]
    if node.blob:
        return node.blob[1]
    if node.is_dir:
        return 4096
    if node.link is not None:
        return len(node.link)
    if node.chardev is not None:
        return 0
    if node.blockdev is not None:
        return 0
    return len(node.content)


#: root's PATH, from /etc/profile's uid==0 branch on the guest.
#: "this expression is not one we model" -- distinct from a legitimate NULL.
_SQL_NOPE = object()

PATH_ROOT = "/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin"
#: What sshd hands a non-root non-login session -- which is what these
#: sessions are. Measured: `ssh host 'echo $PATH'` as a normal user.
PATH_USER = "/usr/local/bin:/usr/bin:/bin:/usr/games"
#: What /etc/profile's else-branch sets, which a *login* shell picks up on
#: top. It differs from PATH_USER by /usr/local/games, and that difference is
#: the guest's, not ours: `bash -lc` and a plain exec really do disagree here.
PATH_USER_LOGIN = "/usr/local/bin:/usr/bin:/bin:/usr/local/games:/usr/games"


def path_for(uid):
    """The PATH a session of this uid gets.

    Every user was given PATH_ROOT, so `which useradd`, `which iptables` and
    `which getcap` all succeeded from a www-data webshell -- and the box's own
    /etc/profile, which the attacker can cat in the same session, says they
    should not.
    """
    return PATH_ROOT if uid == 0 else PATH_USER


#: Every capability the kernel knows, in bit order, as cap_to_text names
#: them. Taken from `capsh --print`'s bounding set on the guest -- 41 of them,
#: ending at cap_checkpoint_restore, which is what makes CapBnd
#: 000001ffffffffff rather than a rounder number.
CAP_NAMES = (
    "cap_chown", "cap_dac_override", "cap_dac_read_search", "cap_fowner",
    "cap_fsetid", "cap_kill", "cap_setgid", "cap_setuid", "cap_setpcap",
    "cap_linux_immutable", "cap_net_bind_service", "cap_net_broadcast",
    "cap_net_admin", "cap_net_raw", "cap_ipc_lock", "cap_ipc_owner",
    "cap_sys_module", "cap_sys_rawio", "cap_sys_chroot", "cap_sys_ptrace",
    "cap_sys_pacct", "cap_sys_admin", "cap_sys_boot", "cap_sys_nice",
    "cap_sys_resource", "cap_sys_time", "cap_sys_tty_config", "cap_mknod",
    "cap_lease", "cap_audit_write", "cap_audit_control", "cap_setfcap",
    "cap_mac_override", "cap_mac_admin", "cap_syslog", "cap_wake_alarm",
    "cap_block_suspend", "cap_audit_read", "cap_perfmon", "cap_bpf",
    "cap_checkpoint_restore",
)
#: The bounding set, which is every bit up to the last name above.
CAP_BOUND_MASK = (1 << len(CAP_NAMES)) - 1


def cap_hex(mask):
    """A capability set as /proc/<pid>/status writes it."""
    return "%016x" % mask


def cap_mask_for(uid):
    """The effective and permitted set a process of this uid carries.

    /proc/<pid>/status, capsh --print and getpcaps all report this, and they
    were three separate literals before -- which is three chances for the box
    to disagree with itself about whether the caller is privileged.
    """
    return CAP_BOUND_MASK if uid == 0 else 0


def cap_to_text(mask):
    """cap_to_text(3), as capsh and getpcaps print it.

    Only the two forms that occur here: the full set is "=ep" and the empty
    set is "=". A partial set would render as "=ep cap_x-ep", which nothing
    on this box produces.
    """
    if mask == 0:
        return "="
    if mask == CAP_BOUND_MASK:
        return "=ep"
    have = [n for i, n in enumerate(CAP_NAMES) if mask & (1 << i)]
    return "=ep " + ",".join(n + "-ep" for n in CAP_NAMES
                             if n not in have) if have else "="


#: st_mode file-type bits, keyed by the same letter ls -l prints. One table,
#: because stat's %A and %f each carried their own idea of the type and
#: disagreed: /dev/sda came out "brw-rw----" under %A and 0o100660 -- a
#: regular file -- under %f, and a fifo did the same.
IFMT_BITS = {"l": 0o120000, "c": 0o020000, "b": 0o060000, "s": 0o140000,
             "p": 0o010000, "d": 0o040000, "-": 0o100000}


def node_ifmt(node):
    """The file-type bits of st_mode for this node."""
    return IFMT_BITS.get(node.type_char, 0o100000)


def node_mode(node):
    """st_mode as stat(2) reports it: type bits and permission bits."""
    return node_ifmt(node) | (node.mode & 0o7777)


def node_alloc(node, path=None):
    """Bytes the file occupies, which is not always its size."""
    if node is None:
        return 4096
    got = getattr(node, "alloc", None)
    if got is not None:
        return got
    return node_size(node, path)


def alloc_kb(size):
    """Kilobytes ext4 allocates for a file of this many bytes."""
    return ((size + 4095) // 4096) * 4


def written_kb(vfs, under=None):
    """Kilobytes the tree has grown since boot, in 4K blocks.

    Module level because the SFTP subsystem answers statvfs@openssh.com and
    has no Shell to ask -- and if it kept its own arithmetic, `sftp> df` and
    `df` over the shell would drift apart the first time an attacker wrote
    a file. Shell._written_kb() delegates here.
    """
    try:
        base = vfs._base_blocks
    except AttributeError:
        return 0
    if under is not None:
        pre = under.rstrip("/") + "/"
        return sum(alloc_kb(node_alloc(n, k))
                   for k, n in vfs.nodes.items()
                   if k.startswith(pre) and not n.is_dir)
    return (vfs._alloc_blocks() - base) * 4


def root_space(vfs):
    """(total, used, free, avail) for / in 1K blocks."""
    grown = written_kb(vfs) - written_kb(vfs, "/tmp")
    used = ROOT_USED + grown
    return (ROOT_BLOCKS, used, ROOT_BLOCKS - used,
            max(0, ROOT_AVAIL - grown))


def root_inodes_used(vfs):
    """IUsed on /, tracking files created and removed since boot."""
    try:
        delta = vfs._root_inodes() - vfs._base_inodes
    except AttributeError:
        delta = 0
    return max(0, ROOT_IUSED + delta)


def root_fsid(mnt="/"):
    """The filesystem id, as stat -f's %i renders it."""
    return "%08x%08x" % (_stable_hash("fsid" + mnt),
                         _stable_hash("fsid2" + mnt))


def root_statvfs(vfs):
    """statvfs(2) for /, in the field names the SFTP extension sends.

    Same source as df, stat -f and tune2fs. f_bfree is total minus used and
    f_bavail excludes the root reserve, which is what makes an sftp client's
    %Capacity land a point below df's: the client computes it from f_bfree
    over f_blocks while df computes it from used over used-plus-avail. The
    real server has the same gap, so reproducing it matters more than making
    the two agree.
    """
    frsize = 4096
    total, _used, free, avail = root_space(vfs)
    inodes, iused = ROOT_INODES, root_inodes_used(vfs)
    return {
        "f_bsize": frsize, "f_frsize": frsize,
        "f_blocks": total // 4,
        "f_bfree": max(0, free) // 4,
        "f_bavail": max(0, avail) // 4,
        "f_files": inodes,
        "f_ffree": max(0, inodes - iused),
        "f_favail": max(0, inodes - iused),
        # The same id stat -f prints, so the two cannot name different
        # filesystems.
        "f_fsid": int(root_fsid(), 16),
        "f_flag": 0, "f_namemax": 255,
    }


def _iperr_row(*vals):
    """The value line under `ip -s -s`'s error headers.

    Five columns ending at 23, 30, 38, 46 and 54, and a trailing space --
    measured off the guest, because getting it wrong is visible next to
    the header directly above it.
    """
    return ("               "
            + "".join("%*d" % (w, v) for w, v in zip([8, 7, 8, 8, 8], vals))
            + " \n")


def gzip_bytes(text, name, mtime):
    """A real gzip stream, with the original name and mtime in the header.

    The rotated logs carried gzip's four magic bytes followed by noise, so
    every reader disagreed: ls showed the file, `file` called it gzip data
    (with a last-modified in 2046 and a nonsense original size, read
    straight out of the fake header), and gunzip said "not in gzip
    format". zgrep across /var/log/*.gz is how anyone checks whether the
    lines they care about survived rotation.
    """
    raw = text.encode("latin-1", "replace")
    co = zlib.compressobj(9, zlib.DEFLATED, -zlib.MAX_WBITS)
    body = co.compress(raw) + co.flush()
    head = (b"\x1f\x8b\x08\x08" + struct.pack("<I", int(mtime))
            + b"\x00\x03" + name.encode("latin-1") + b"\x00")
    return (head + body + struct.pack("<I", zlib.crc32(raw) & 0xFFFFFFFF)
            + struct.pack("<I", len(raw) & 0xFFFFFFFF))


def alternatives_admin(row):
    """One /var/lib/dpkg/alternatives/<name> file.

    Format read off the guest: the mode, the master link, then a
    name/path pair per slave, a blank line, and then for each alternative
    its path, its priority, and one line per slave in the same order as
    the header -- an empty line where that alternative has no slave of
    that name. A blank line ends the file.
    """
    name, link, alts, slaves = row
    order = sorted(slaves)
    out = ["auto", link]
    for sl in order:
        out.append(sl)
        out.append(slaves[sl])
    out.append("")
    for path, prio, own in sorted(alts, key=lambda x: x[0]):
        out.append(path)
        out.append(str(prio))
        for sl in order:
            out.append(own.get(sl, ""))
    out.append("")
    return "\n".join(out) + "\n"


def dpkg_status_body():
    """/var/lib/dpkg/status, one stanza per installed package.

    Rendered from Shell.PACKAGES -- the same table `dpkg -l` walks -- so
    the file and the command cannot report different sets. Stanza shape
    measured on the guest: Package, Status, Priority, Section,
    Installed-Size, Maintainer, Architecture, Version, Description.
    """
    out = []
    for pkg, ver, arch in Shell.PACKAGES:
        desc = Shell._PKG_DESC.get(pkg) or Shell._BOOT_PKG_DESC.get(
            pkg, "Debian %s package" % pkg)
        size = 40 + (_stable_hash("size:" + pkg) % 9000)
        out.append(
            "Package: %s\n"
            "Status: install ok installed\n"
            "Priority: optional\n"
            "Section: %s\n"
            "Installed-Size: %d\n"
            "Maintainer: Debian QA Group <packages@qa.debian.org>\n"
            "Architecture: %s\n"
            "Version: %s\n"
            "Description: %s\n"
            % (pkg, "admin" if arch == "all" else "utils", size, arch, ver,
               desc))
    return "\n".join(out) + "\n"


def blob_body(kind, size):
    """`size` bytes of a plausible non-ELF binary, generated on read.

    Same reasoning as elf_body: one filesystem per source IP, so a stored
    30MB of kernel plus initramfs would be paid per attacker. The magic
    bytes are the real ones -- Debian's vmlinuz is an EFI-stub PE image
    starting "MZ", and its initrd.img begins with an *uncompressed* cpio
    newc archive ("070701") holding early microcode, not with gzip magic.
    We claimed gzip, which `file` would have called out.
    """
    if kind.startswith("capem:"):
        return _ca_pem(kind[6:]).encode()
    if kind == "cabundle":
        return "".join(_ca_pem(n) for n in CA_CERTS).encode()
    if kind.startswith("hostfile:"):
        # The bytes we really fetched, read from the capture store rather
        # than copied into every per-source filesystem. This is what makes
        # `sha256sum` inside the guest agree with the artifact we archived.
        try:
            with open(kind[9:], "rb") as fh:
                return fh.read(min(size, BLOB_READ_CAP))
        except OSError:
            return b"\0" * min(size, BLOB_READ_CAP)
    if kind == "zero":
        # A sparse allocation -- fallocate/truncate reserve space without
        # writing anything. The logical size is whatever was asked for; the
        # bytes are only ever produced up to the cap, because a shell that
        # can be made to allocate 100GB by typing one command is a shell an
        # attacker can switch off.
        return b"\0" * min(size, BLOB_READ_CAP)
    size = min(size, BLOB_READ_CAP)
    head = {"bzimage": b"\x4d\x5a\x00\x00" + b"\x00" * 12,
            "cpio": b"070701",
            # Every file under /usr/share/zoneinfo starts this way.
            "tzif": b"TZif2\x00\x00\x00",
            # A compiled locale category, and a charmap source file.
            "locdata": b"\x03\x00\x00\x00",
            "locsrc": b"<charmap>\n"}.get(kind, b"")
    rnd = random.Random("blob v1 " + kind)
    body = bytearray(head)
    chunk = bytes(rnd.getrandbits(8) for _ in range(4096))
    while len(body) < size:
        body += chunk
    return bytes(body[:size])


def elf_body(name, size):
    """A plausible ELF64 executable of the requested size.

    Generated on read rather than stored: there is one filesystem per source IP,
    so materialising ~60 binaries totalling tens of MB each would balloon memory.
    Deterministic per name so repeated reads and hashes stay stable.
    """
    hdr = bytearray(64)
    hdr[0:4] = b"\x7fELF"
    hdr[4] = 2          # ELFCLASS64
    hdr[5] = 1          # little endian
    hdr[6] = 1          # EV_CURRENT
    hdr[7] = 0          # System V ABI
    hdr[16:18] = (3).to_bytes(2, "little")    # ET_DYN (PIE), as Debian ships
    hdr[18:20] = (62).to_bytes(2, "little")   # EM_X86_64
    hdr[20:24] = (1).to_bytes(4, "little")
    hdr[24:32] = (0x3000).to_bytes(8, "little")   # e_entry
    hdr[32:40] = (64).to_bytes(8, "little")       # e_phoff
    hdr[54:56] = (64).to_bytes(2, "little")       # e_ehsize
    hdr[56:58] = (56).to_bytes(2, "little")       # e_phentsize
    hdr[58:60] = (13).to_bytes(2, "little")       # e_phnum
    hdr[60:62] = (64).to_bytes(2, "little")       # e_shentsize

    # Strings a real binary carries, so `strings` output is not empty.
    tail = ("/lib64/ld-linux-x86-64.so.2\0libc.so.6\0GLIBC_2.34\0"
            "GCC: (Debian 14.2.0-19) 14.2.0\0"
            "%s (GNU coreutils) 9.1\0Usage: %s [OPTION]...\0"
            "Report bugs to <bug-coreutils@gnu.org>\0" % (name, name)).encode()

    body = bytearray(bytes(hdr) + tail)
    if len(body) < size:
        # deterministic filler that looks like packed code, not zero padding
        seed = hashlib.sha256(name.encode()).digest()
        need = size - len(body)
        chunk = bytearray()
        while len(chunk) < need:
            seed = hashlib.sha256(seed).digest()
            chunk += seed
        body += chunk[:need]
    return bytes(body[:size])


# uid/gid -> name, for `ls -l` and `stat`. Everything printed a hardcoded
# "root root", so `chown www-data f && ls -l f` denied its own effect.
# One uid map, and it has to be the same one /etc/passwd states. There were
# two: this table said sshd=101 and mysql=103 while passwd said 104 and 106,
# so `ps -eo user,uid` and `getent passwd` disagreed about the same daemon.
# The accounts ps runs things as -- messagebus, systemd-network,
# systemd-resolve -- were in neither passwd nor group, so `id messagebus`
# failed on a box whose own `ps` showed it running dbus.
UID_NAMES = {0: "root", 1: "daemon", 2: "bin", 3: "sys", 4: "sync",
             5: "games", 6: "man", 7: "lp", 8: "mail", 9: "news",
             10: "uucp", 13: "proxy", 33: "www-data", 34: "backup",
             38: "list", 39: "irc", 42: "_apt",
             100: "messagebus", 101: "systemd-network",
             102: "systemd-resolve", 103: "systemd-timesync",
             104: "sshd", 106: "mysql", 1000: "deploy", 65534: "nobody"}
GID_NAMES = {0: "root", 1: "daemon", 2: "bin", 3: "sys", 4: "adm", 5: "tty",
             6: "disk", 7: "lp", 8: "mail", 9: "news", 10: "uucp",
             12: "man", 13: "proxy", 15: "kmem", 20: "dialout", 21: "fax",
             22: "voice", 24: "cdrom", 25: "floppy", 26: "tape", 27: "sudo",
             29: "audio", 30: "dip", 33: "www-data", 34: "backup",
             37: "operator", 38: "list", 39: "irc", 40: "src", 42: "shadow",
             43: "utmp", 44: "video", 45: "sasl", 46: "plugdev", 50: "staff",
             60: "games", 100: "users", 101: "systemd-journal",
             996: "systemd-timesync", 997: "systemd-resolve",
             998: "systemd-network",
             102: "crontab", 103: "_ssh", 107: "messagebus", 110: "mysql",
             114: "ssh", 1000: "deploy", 65534: "nogroup"}


# Filled in by ssh_honeypot.publish_host_pubkeys() at startup with the public
# halves of the host keys actually served on the wire, so `ssh-keygen -lf
# /etc/ssh/ssh_host_*.pub` on the box matches what the client recorded.
HOST_KEY_PUBS = {}


def _ssh_string(b):
    return len(b).to_bytes(4, "big") + b


def _ssh_mpint(n):
    raw = n.to_bytes((n.bit_length() + 7) // 8 or 1, "big")
    if raw[0] & 0x80:                      # mpints are signed
        raw = b"\x00" + raw
    return _ssh_string(raw)


def _synth_pubkeys():
    """Structurally valid host public keys, for when no transport published any.

    These are used by the standalone shell (tests, and the HTTP-only path).
    They cannot sign anything -- nothing here signs -- but they have to *parse*:
    the previous placeholders were hand-typed base64 that was not even a valid
    key blob, so `ssh-keygen -lf` on them could not agree with itself about the
    key size. Derived from a fixed seed so they are stable across restarts.
    """
    rnd = random.Random("web01 host keys v1")
    raw = lambda n: bytes(rnd.getrandbits(8) for _ in range(n))
    out = {}
    blob = _ssh_string(b"ssh-ed25519") + _ssh_string(raw(32))
    out["ssh_host_ed25519_key"] = "ssh-ed25519 %s root@%s\n" % (
        base64.b64encode(blob).decode(), HOST)
    point = b"\x04" + raw(64)
    blob = (_ssh_string(b"ecdsa-sha2-nistp256") + _ssh_string(b"nistp256")
            + _ssh_string(point))
    out["ssh_host_ecdsa_key"] = "ecdsa-sha2-nistp256 %s root@%s\n" % (
        base64.b64encode(blob).decode(), HOST)
    # A 2048-bit modulus: top bit set so the length is unambiguous, odd so it
    # is at least plausible as a product of two primes.
    n = int.from_bytes(raw(256), "big") | (1 << 2047) | 1
    blob = _ssh_string(b"ssh-rsa") + _ssh_mpint(65537) + _ssh_mpint(n)
    out["ssh_host_rsa_key"] = "ssh-rsa %s root@%s\n" % (
        base64.b64encode(blob).decode(), HOST)
    return out


def _nginx_time(iso):
    """nginx's access-log stamp: 20/Aug/2026:19:35:05 +0000."""
    m = re.match(r"(\d{4})-(\d\d)-(\d\d)[T ](\d\d):(\d\d):(\d\d)", iso)
    if not m:
        return time.strftime("%d/%b/%Y:%H:%M:%S +0000", time.gmtime())
    months = ("Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep",
              "Oct", "Nov", "Dec")
    y, mo, d, hh, mm, ss = m.groups()
    return "%s/%s/%s:%s:%s:%s +0000" % (d, months[int(mo) - 1], y, hh, mm, ss)


def _nginx_err_time(iso):
    """nginx's error-log stamp: 2026/08/20 19:35:05."""
    m = re.match(r"(\d{4})-(\d\d)-(\d\d)[T ](\d\d):(\d\d):(\d\d)", iso)
    if not m:
        return time.strftime("%Y/%m/%d %H:%M:%S", time.gmtime())
    y, mo, d, hh, mm, ss = m.groups()
    return "%s/%s/%s %s:%s:%s" % (y, mo, d, hh, mm, ss)


def _to_int(value):
    try:
        return int(str(value).strip() or 0)
    except ValueError:
        return 0


def _collate(name):
    """Sort weight under the box's locale, which is C.UTF-8.

    This used to fold case and drop punctuation, which is glibc's en_US
    collation -- chosen because the dev host runs en_US.UTF-8. The box does
    not: it advertised LANG=en_US.UTF-8 while having no locales package, no
    /etc/default/locale, and a `locale -a` that printed nothing, so it was
    claiming a locale it had no support for. A stock Debian image is
    C.UTF-8, where collation is byte order and X.TXT sorts before a.txt --
    which is also what the guest itself does.
    """
    return name


# These two are the boot-time defaults. They are NOT the box's answer once
# anything has changed: useradd writes /etc/passwd and these dicts know
# nothing about it, so `ls -l` printed a bare 1001 for a home directory that
# `id` was happily calling 1001(bd). Shell._uname_of/_gname_of read the files
# and are what every user-visible path uses; these remain only as the
# fallback for a uid no file names.
def uname_of(uid):
    return UID_NAMES.get(uid, str(uid))


def gname_of(gid):
    return GID_NAMES.get(gid, str(gid))


def _name_from_db(vfs, path, wanted, fallback):
    """The name column of the first row in `path` whose id is `wanted`."""
    for line in (vfs.read(path) or b"").decode("latin-1").splitlines():
        f = line.split(":")
        if len(f) > 2 and f[2].isdigit() and int(f[2]) == wanted:
            return f[0]
    return fallback(wanted)


def ids_for(vfs, username):
    """(uid, gid) for a name, from this filesystem's passwd and group.

    scp and sftp write as the authenticated user, and every upload path here
    wrote as root -- so `deploy` scp'd a payload and then could not chmod +x
    their own file, while `echo x > f` in the same session produced a file
    they owned. Diicot hit it on 2026-08-24: "chmod: /var/tmp/smDvczUH:
    Permission denied" on the binary they had just uploaded.
    """
    for line in (vfs.read("/etc/passwd") or b"").decode(
            "latin-1").splitlines():
        f = line.split(":")
        if len(f) > 3 and f[0] == username and f[2].isdigit() \
                and f[3].isdigit():
            return int(f[2]), int(f[3])
    return 0, 0


def id_map(vfs, path):
    """{id: name} for a passwd- or group-shaped file, read once.

    The per-id form below scans the file for every lookup, which is fine for
    one `ls -l` line and not fine for users-groups-by-id@openssh.com: the
    request carries an array, a 256KB packet holds 65536 ids, and a client
    that sends a full one would have had us re-read /etc/passwd 65536 times.
    """
    out = {}
    for line in (vfs.read(path) or b"").decode("latin-1").splitlines():
        f = line.split(":")
        if len(f) > 2 and f[2].isdigit():
            out.setdefault(int(f[2]), f[0])
    return out


def uname_in(vfs, uid):
    """uid to name, from this filesystem's /etc/passwd.

    Module level so the SFTP subsystem can answer
    users-groups-by-id@openssh.com from the same table `ls -l` reads.
    """
    return _name_from_db(vfs, "/etc/passwd", uid,
                         lambda u: "root" if u == 0 else str(u))


def gname_in(vfs, gid):
    """gid to name, from this filesystem's /etc/group."""
    return _name_from_db(vfs, "/etc/group", gid,
                         lambda g: "root" if g == 0 else str(g))


# --- the kernel ring buffer ------------------------------------------------
# `dmesg` was eight hand-written lines, /var/log/kern.log held one of them,
# and `journalctl -k` was not kernel-filtered at all -- it printed CRON and
# sshd sessions, which no kernel ever logs. So three commands that read the
# same messages on a real box each told a different story here, and the one
# an attacker actually runs -- `dmesg | grep -i virt`, to find out what it
# is running on -- found two virtio lines in dmesg and none in either of the
# others. One source now, rendered three ways.
#
# Modelled on the boot of the real Debian 13 cloud guest this box imitates
# (util-linux 2.41 dmesg, 732 lines), cut to the parts that carry meaning
# and with every value replaced by this persona's: four CPUs, 2 GB, sda1,
# this MAC, this kernel build.
KMSG_FAC_KERN, KMSG_FAC_DAEMON = "kern", "daemon"


