        # ../vendor/autoload.php and ../bootstrap/app.php, neither of which
        # existed -- in a docroot holding wp-admin, wp-content and
        # wp-includes, on a box whose HTTP surface serves WordPress 6.4.3.
        # Three stories at once, and the entry point referenced files that
        # would have fatalled.
        w("/var/www/html/index.php",
          "<?php\n/**\n * Front to the WordPress application. This file "
          "doesn't do anything, but loads\n * wp-blog-header.php which does "
          "and tells WordPress to load the theme.\n *\n * @package "
          "WordPress\n */\n\n/**\n * Tells WordPress to load the WordPress "
          "theme and output it.\n *\n * @var bool\n */\n"
          "define( 'WP_USE_THEMES', true );\n\n"
          "/** Loads the WordPress Environment and Template */\n"
          "require __DIR__ . '/wp-blog-header.php';\n")
        self._seed_wordpress(w)
