        # A datadir with no ibdata1 is not a database that has ever started.
        # Ownership is mysql:mysql 0700, which is what the postinst leaves.
        _dd = "/var/lib/mysql"
        # One directory per database, and the list has to be the list
        # `show databases` prints -- sys was missing from the datadir once
        # the server started admitting it exists.
        for _sub in (_dd, _dd + "/mysql", _dd + "/performance_schema",
                     _dd + "/sys",
                     _dd + "/" + (getattr(wordpress, "DB_NAME", "p2p_dist"))):
            self.nodes[_sub] = FileNode(mode=0o700, is_dir=True, uid=106,
                                        gid=110, mtime=BOOT_TS - 3600)
        for _f, _sz in (("ibdata1", 12582912), ("ib_logfile0", 100663296),
                        ("ibtmp1", 12582912), ("aria_log.00000001", 32768),
                        ("aria_log_control", 52), ("ib_buffer_pool", 2894),
                        ("multi-master.info", 0), ("ddl_recovery.log", 0)):
            self.nodes["%s/%s" % (_dd, _f)] = FileNode(
                mode=0o660, uid=106, gid=110, blob=("cpio", _sz),
                mtime=BOOT_TS - 1800)
        w(_dd + "/mysql_upgrade_info", "11.8.3-MariaDB\n")
        self.nodes[_dd + "/mysql_upgrade_info"].uid = 106
        self.nodes[_dd + "/mysql_upgrade_info"].gid = 110
        # The InnoDB tablespace for each WordPress table.
        for _t in ("commentmeta", "comments", "links", "options", "postmeta",
                   "posts", "term_relationships", "term_taxonomy", "termmeta",
                   "terms", "usermeta", "users"):
            self.nodes["%s/%s/%s%s.ibd"
                       % (_dd, getattr(wordpress, "DB_NAME", "p2p_dist"),
                          getattr(wordpress, "TABLE_PREFIX", "wp_"), _t)] = \
                FileNode(mode=0o660, uid=106, gid=110,
                         blob=("cpio", 114688), mtime=BOOT_TS - 1800)
        w("/etc/mysql/my.cnf",
          "[mysqld]\nuser = mysql\nbind-address = 127.0.0.1\n"
          "datadir = /var/lib/mysql\nlog_error = /var/log/mysql/error.log\n")
        # These four predated the elf= mechanism and were literal eight-byte
        # files: `ls -l /usr/sbin/nginx` said 8 while `file` called it a
        # 1.3MB stripped ELF, on the box's own main daemon. nginx is a real
        # binary; php, mysql and mysqldump are update-alternatives symlinks
        # on Debian, which is also why `php -v` reports the 8.4 build.
        binary("/usr/sbin/nginx", "nginx")
