# need.


# One shell function level costs several Python frames, so this has to sit
# well under sys.getrecursionlimit() or RecursionError escapes before the
# cap fires. Nothing legitimate nests anywhere near this deep.
FUNCNEST_MAX = 48
# Brace expansion is bounded so a nest of groups cannot blow up the line.
# Nesting has to be bounded for the same reason function recursion is: each
# level costs several Python frames, and a RecursionError escaping the
# session drops the connection. bash handles arbitrary nesting, so this is a
# divergence -- but only past a depth nothing legitimate reaches.
NEST_MAX = 32
BRACE_MAX_ROUNDS = 8
BRACE_MAX_LEN = 64 * 1024
ARITH_MAX_POW = 4096          # bash wraps at 64 bits; we just refuse
ARITH_MAX_SHIFT = 256


class ArithError(Exception):
    """A division by zero inside $(( )), which bash reports and exits 1 on."""

    def __init__(self, expr):
        Exception.__init__(self, expr)
        self.expr = expr


def arith_eval(expr, getvar, setvar=None):
    """Evaluate a $(( )) expression without ever calling eval() on input.

    This used to hand the expression to Python's ast and evaluate that,
    which meant every form bash has and Python does not silently became 0:
    0x1f, 017, 2#1010, `||`, the ternary, `++`, `--`, and assignment. So
    `echo $((0x1f))` printed 0, `$((1 ? 42 : 7))` printed 0, and
    `n=5; echo $((n++)) $n` printed "0 5" -- a counter that never counts is
    an infinite loop in whatever script owns it. A precedence-climbing
    evaluator handles the whole operator set and can write back, which the
    assignment forms need.
    """
    src = expr
    pos = [0]
    dirty = {}

    def _peek():
        while pos[0] < len(src) and src[pos[0]] in " \t\n":
            pos[0] += 1
        return src[pos[0]] if pos[0] < len(src) else ""

    def _eat(tok):
        _peek()
        if src.startswith(tok, pos[0]):
            pos[0] += len(tok)
            return True
        return False

    def _num(name):
        raw = dirty.get(name)
        if raw is None:
            raw = getvar(name)
        try:
            return _parse_int(str(raw).strip() or "0")
        except ValueError:
            return 0

    def _store(name, val):
        dirty[name] = str(val)
        if setvar is not None:
            setvar(name, str(val))
        return val

    def _primary():
        c = _peek()
        if c == "":
            return 0
        if c == "(":
            pos[0] += 1
            v = _ternary()
            _eat(")")
            return v
        for op, delta in (("++", 1), ("--", -1)):
            if src.startswith(op, pos[0]):
                pos[0] += 2
                nm = _name()
                if nm is None:
                    return 0
                return _store(nm, _num(nm) + delta)
        if c in "+-!~":
            pos[0] += 1
            v = _primary()
            return {"+": v, "-": -v, "!": 0 if v else 1, "~": ~v}[c]
        if c == "$":
            pos[0] += 1
            return _primary()
        if c.isdigit():
            j = pos[0]
            while j < len(src) and (src[j].isalnum() or src[j] == "#"):
                j += 1
            tok = src[pos[0]:j]
            pos[0] = j
            try:
                return _parse_int(tok)
            except ValueError:
                return 0
        nm = _name()
        if nm is None:
            pos[0] += 1
            return 0
        # Post-increment reads the old value and stores the new one.
        for op, delta in (("++", 1), ("--", -1)):
            if _eat(op):
                old = _num(nm)
                _store(nm, old + delta)
                return old
        for op in ("<<=", ">>=", "+=", "-=", "*=", "/=", "%=", "&=", "|=",
                   "^="):
            _peek()
            if src.startswith(op, pos[0]):
                pos[0] += len(op)
                rhs = _ternary()
                cur = _num(nm)
                try:
                    val = _apply(op[:-1], cur, rhs)
                except ZeroDivisionError:
                    raise ArithError(expr)
                return _store(nm, val)
        _peek()
        if (src.startswith("=", pos[0])
                and not src.startswith("==", pos[0])):
            pos[0] += 1
            return _store(nm, _ternary())
        return _num(nm)

    def _name():
        _peek()
        j = pos[0]
        if j < len(src) and (src[j].isalpha() or src[j] == "_"):
            while j < len(src) and (src[j].isalnum() or src[j] == "_"):
                j += 1
            nm = src[pos[0]:j]
            pos[0] = j
            return nm
        return None

    # (operators, left-associative) weakest first
    LEVELS = (("||",), ("&&",), ("|",), ("^",), ("&",), ("==", "!="),
              ("<=", ">=", "<", ">"), ("<<", ">>"), ("+", "-"),
              ("*", "/", "%"))

    def _binary(level):
        if level >= len(LEVELS):
            return _power()
        left = _binary(level + 1)
        while True:
            _peek()
            for op in LEVELS[level]:
                if not src.startswith(op, pos[0]):
                    continue
                # "|" must not swallow the "|" of "||", and "&" likewise.
                if op in ("|", "&", "<", ">") and src.startswith(op * 2,
                                                                 pos[0]):
                    continue
                if op in ("<", ">") and src.startswith(op + "=", pos[0]):
                    continue
                if op == "=" or src.startswith(op + "=", pos[0]) and \
                        op in ("+", "-", "*", "/", "%", "&", "|", "^"):
                    continue
                pos[0] += len(op)
                if op == "&&":
                    right = _binary(level + 1)
                    left = 1 if (left and right) else 0
                elif op == "||":
                    right = _binary(level + 1)
                    left = 1 if (left or right) else 0
                else:
                    right = _binary(level + 1)
                    try:
                        left = _apply(op, left, right)
                    except ZeroDivisionError:
                        raise ArithError(expr)
                break
            else:
                return left

    def _power():
        base = _primary()
        _peek()
        if src.startswith("**", pos[0]):
            pos[0] += 2
            exp = _power()            # right-associative
            if exp < 0:
                return 0
            if exp > ARITH_MAX_SHIFT:
                return 0
            return base ** exp
        return base

    def _ternary():
        cond = _binary(0)
        _peek()
        if src.startswith("?", pos[0]):
            pos[0] += 1
            a = _ternary()
            _eat(":")
            b = _ternary()
            return a if cond else b
        return cond

    try:
        val = _ternary()
        # A comma sequence yields its last value.
        while _eat(","):
            val = _ternary()
    except ArithError:
        raise
    except Exception:
        return 0
    if isinstance(val, bool):
        val = 1 if val else 0
    try:
        val = int(val)
    except Exception:
        return 0
    # bash arithmetic is 64-bit and wraps; an unbounded Python int here is
    # both a tell and a memory risk if it is then printed or multiplied.
    return ((val + (1 << 63)) % (1 << 64)) - (1 << 63)


def _parse_int(tok):
    """bash integer literals: decimal, 0x hex, leading-0 octal, base#digits."""
    tok = tok.strip()
    if not tok:
        return 0
    neg = tok.startswith("-")
    if neg:
        tok = tok[1:]
    if "#" in tok:
        base_s, _, digits = tok.partition("#")
        base = int(base_s)
        if not 2 <= base <= 64:
            raise ValueError(tok)
        val = int(digits, base)
    elif tok[:2].lower() == "0x":
        val = int(tok, 16)
    elif len(tok) > 1 and tok[0] == "0" and tok[1:].isdigit():
        val = int(tok, 8)
    else:
        val = int(tok, 10)
    return -val if neg else val


def _apply(op, a, b):
    if op == "+":
        return a + b
    if op == "-":
        return a - b
    if op == "*":
        return a * b
    if op == "/":
        if b == 0:
            raise ZeroDivisionError
        # bash truncates toward zero; Python floors.
        return abs(a) // abs(b) * (1 if (a < 0) == (b < 0) else -1)
    if op == "%":
        if b == 0:
            raise ZeroDivisionError
        return abs(a) % abs(b) * (1 if a >= 0 else -1)
    if op == "<<":
        return a << b if 0 <= b <= ARITH_MAX_SHIFT else 0
    if op == ">>":
        return a >> b if 0 <= b <= ARITH_MAX_SHIFT else 0
    if op == "<":
        return 1 if a < b else 0
    if op == ">":
        return 1 if a > b else 0
    if op == "<=":
        return 1 if a <= b else 0
    if op == ">=":
        return 1 if a >= b else 0
    if op == "==":
        return 1 if a == b else 0
    if op == "!=":
        return 1 if a != b else 0
    if op == "&":
        return a & b
    if op == "|":
        return a | b
    if op == "^":
        return a ^ b
    return 0



# Marks a metacharacter that was backslash-escaped, so globbing skips it.
GLOB_LIT = "\x01"


def _glob_unmark(word):
    return word.replace(GLOB_LIT, "")


def _glob_strip_marked(word):
    """The word with every marked character removed, for asking whether any
    *unescaped* metacharacter is left."""
    out, i, n = [], 0, len(word)
    while i < n:
        if word[i] == GLOB_LIT:
            i += 2
            continue
        out.append(word[i])
        i += 1
    return "".join(out)


def find_subst_end(text, start):
    """Index of the ")" that closes the "$(" beginning at `start`.

    A plain depth counter is not enough: it must skip quoted regions and it
    must not let a case *pattern's* ")" -- as in `case $x in *y*) ...` --
    close the substitution. Getting this wrong truncates the captured command
    and is exactly the kind of tell that bots fingerprint on.
    """
    i, n = start + 2, len(text)
    depth, case_depth = 1, 0
    expect_pattern = False
    quote = None
    while i < n:
        c = text[i]
        if quote:
            if c == "\\" and quote == '"' and i + 1 < n:
                i += 2; continue
            if c == quote:
                quote = None
            i += 1; continue
        if c in "'\"":
            quote = c; i += 1; continue
        if c == "\\" and i + 1 < n:
            i += 2; continue
        if c == "`":
            j = text.find("`", i + 1)
            i = n if j < 0 else j + 1
            continue
        if i == start + 2 or text[i - 1] in " \t\n;(":
            if text.startswith("case", i) and (i + 4 >= n or text[i + 4] in " \t"):
                case_depth += 1; i += 4; continue
            if text.startswith("esac", i) and (i + 4 >= n or text[i + 4] in " \t\n;)"):
                if case_depth:
                    case_depth -= 1
                expect_pattern = False
                i += 4; continue
            if case_depth and text.startswith("in", i) and (i + 2 >= n or text[i + 2] in " \t\n"):
                expect_pattern = True; i += 2; continue
        if case_depth and text.startswith(";;", i):
            expect_pattern = True; i += 2; continue
        if text.startswith("$(", i):
            depth += 1; i += 2; continue
        if c == "(":
            if not expect_pattern:
                depth += 1
            i += 1; continue
        if c == ")":
            if expect_pattern:
                expect_pattern = False; i += 1; continue
            depth -= 1
            if depth == 0:
                return i
            i += 1; continue
        i += 1
    return n


def find_unquoted(text, needle, start=0):
    """Index of the first UNQUOTED occurrence of `needle`, or -1.

    Three places tested for an operator with a plain substring search and so
    fired on text that merely contained the characters:

        if "$'" in word          swallowed the $ in `echo 'a$'`, so
                                 `grep -o 'b$'` matched twice and
                                 `tr -d '$'` deleted nothing
        if "|&" in text          rewrote `echo 'a|&b'` into a pipeline with
                                 stderr merged -- a different command, not a
                                 mangled word
        text.find("<(")          expanded `echo 'x<(y)'` to x/dev/fd/63

    The first was found because a real /etc/profile exercised it. The other
    two were found by grepping for the shape rather than waiting for the
    symptom, which took two minutes and turned up twice as many.
    """
    i, n = start, len(text)
    q = None
    while i < n:
        c = text[i]
        if q:
            if c == "\\" and q == '"' and i + 1 < n:
                i += 2
                continue
            if c == q:
                q = None
            i += 1
            continue
        if c == "\\" and i + 1 < n:
            i += 2
            continue
        if c in "'\"":
            q = c
            i += 1
            continue
        if text.startswith(needle, i):
            return i
        i += 1
    return -1


def split_top(text, seps):
    return _scan(text, seps=seps, words=False)


def split_words(text):
    return [w for w in _scan(text, words=True) if w]


