# The filesystem types df leaves out unless you ask for -a: everything that
# holds no blocks. tmpfs and devtmpfs are not on it, which is why df lists
# /dev, /run and /tmp.
DUMMY_FS = frozenset((
    "sysfs", "proc", "devpts", "securityfs", "cgroup2", "pstore", "bpf",
    "hugetlbfs", "mqueue", "debugfs", "tracefs", "fusectl", "configfs",
    "binfmt_misc", "autofs", "nsfs", "ramfs", "rpc_pipefs",
))


def mounts_text():
    """/proc/mounts, which /etc/mtab is a symlink to."""
    return "".join("%s %s %s %s 0 0\n" % (m[0], m[1], m[2], m[3])
                   for m in MOUNTS)


# device -> (UUID, FSTYPE, FSVER, LABEL). blkid had this inline and findmnt
# had nothing, so `findmnt -no UUID /` came back empty while `blkid` and
# `lsblk -no UUID /dev/sda1` both answered for the same filesystem. One
# table, and every reader of "what is this device" agrees by construction.
BLOCK_DEVICES = (
    ("/dev/sda1", ROOT_UUID, "ext4", "1.0", None),
    # The BIOS boot partition has no filesystem, so it has only a PARTUUID.
    ("/dev/sda14", None, None, None, None),
    ("/dev/sda15", BOOT_UUID, "vfat", "FAT32", "UEFI"),
)


def partuuid_of(dev):
    """The GPT entry's UUID, which exists whether or not there is a
    filesystem on the partition."""
    m = re.search(r"(\d+)$", dev or "")
    if not m:
        return ""
    return "%s-%02d" % (ROOT_UUID[:8], int(m.group(1)))


def device_info(dev):
    """(UUID, FSTYPE, FSVER, LABEL, PARTUUID) for a block device."""
    for name, uuid, fstype, ver, label in BLOCK_DEVICES:
        if name == dev:
            return uuid or "", fstype or "", ver or "", label or "", \
                partuuid_of(dev)
    return "", "", "", "", ""


# The mount flags the VFS owns. Everything else in a mount's option string
# belongs to the filesystem, and mountinfo keeps the two apart.
VFS_MOUNT_FLAGS = frozenset((
    "rw", "ro", "nosuid", "nodev", "noexec", "sync", "dirsync", "mand",
    "nomand", "atime", "noatime", "diratime", "nodiratime", "relatime",
    "norelatime", "strictatime", "nostrictatime", "lazytime", "nolazytime",
    "silent", "iversion", "noiversion", "symfollow", "nosymfollow",
))


def vfs_options(opts):
    """The VFS half of a mount option string, in the order it appears."""
    return ",".join(o for o in (opts or "").split(",")
                    if o.split("=")[0] in VFS_MOUNT_FLAGS)


def mountinfo_text():
    """/proc/<pid>/mountinfo -- the same mounts, in the kernel's other
    format. It used to be a byte-for-byte copy of /proc/mounts, which has
    six fields where this has eleven, so anything parsing it (every
    container-detection script, and findmnt itself) read nonsense."""
    ids, out = {}, []
    for i, (src, tgt, fstype, opts, sup, dev) in enumerate(MOUNTS):
        mid = 23 + i
        ids[tgt] = mid
        parent = 1
        best = ""
        for other in ids:
            if other != tgt and (tgt == other or tgt.startswith(
                    other.rstrip("/") + "/")) and len(other) > len(best):
                best, parent = other, ids[other]
        # Field 6 is the *VFS* options and nothing else; the filesystem's own
        # options come after the "-". We printed the whole /proc/mounts
        # string in both places, so `findmnt -o VFS-OPTIONS /` answered
        # "rw,relatime,discard,errors=remount-ro" where the kernel says
        # "rw,relatime" -- and the two halves overlapped, which no mountinfo
        # line does. Measured on the guest for /, /tmp, /run, /sys and
        # /dev/pts: the union of the two halves is exactly the /proc/mounts
        # string, and their intersection is only rw or ro.
        out.append("%d %d %s / %s %s shared:%d - %s %s %s\n"
                   % (mid, parent, dev, tgt, vfs_options(opts), i + 1,
                      fstype, src, sup))
    return "".join(out)


