def session_scope_path(uid, pid):
    """The cgroup path a login session's process sits in.

    One function, because /proc/<pid>/cgroup and the tree under
    /sys/fs/cgroup have to name the same scope.
    """
    return "user.slice/user-%d.slice/session-%d.scope" % (uid, pid % 40 + 1)


def cgroup_dir_files(path, memory=None, tasks=None, procs=(), cpu_usec=None):
    """The files every non-root cgroup directory has.

    A leaf carries the same interface files as a slice; what differs is
    the numbers in them, and those come from the caller so that
    memory.current and `systemctl show -p MemoryCurrent` cannot drift.
    """
    depth = path.count("/")
    mem = 0 if memory is None else memory
    out = [
        ("cgroup.controllers", "cpuset cpu io memory pids\n"
         if depth < 2 else "\n"),
        ("cgroup.events", "populated %d\nfrozen 0\n" % (1 if procs else 0)),
        ("cgroup.freeze", "0\n"),
        ("cgroup.kill", ""),
        ("cgroup.max.depth", "max\n"),
        ("cgroup.max.descendants", "max\n"),
        ("cgroup.pressure", "1\n"),
        ("cgroup.procs", "".join("%d\n" % p for p in procs)),
        ("cgroup.stat", "nr_descendants 0\nnr_dying_descendants 0\n"),
        ("cgroup.subtree_control",
         "cpu memory pids\n" if depth < 2 else "\n"),
        ("cgroup.threads", "".join("%d\n" % p for p in procs)),
        ("cgroup.type", "domain\n"),
        ("cpu.pressure",
         "some avg10=0.00 avg60=0.00 avg300=0.00 total=0\n"
         "full avg10=0.00 avg60=0.00 avg300=0.00 total=0\n"),
        ("cpu.stat", "usage_usec %d\nuser_usec %d\nsystem_usec %d\n"
         % (cpu_usec or 0, int((cpu_usec or 0) * 0.63),
            (cpu_usec or 0) - int((cpu_usec or 0) * 0.63))),
        ("cpu.stat.local", "throttled_usec 0\n"),
        ("io.pressure",
         "some avg10=0.00 avg60=0.00 avg300=0.00 total=0\n"
         "full avg10=0.00 avg60=0.00 avg300=0.00 total=0\n"),
        ("memory.current", "%d\n" % mem),
        ("memory.events", "low 0\nhigh 0\nmax 0\noom 0\noom_kill 0\n"
                          "oom_group_kill 0\n"),
        ("memory.events.local",
         "low 0\nhigh 0\nmax 0\noom 0\noom_kill 0\noom_group_kill 0\n"),
        ("memory.high", "max\n"),
        ("memory.low", "0\n"),
        ("memory.max", "max\n"),
        ("memory.min", "0\n"),
        ("memory.numa_stat", "anon N0=%d\nfile N0=0\n" % mem),
        ("memory.oom.group", "0\n"),
        ("memory.peak", "%d\n" % int(mem * 1.4)),
        ("memory.pressure",
         "some avg10=0.00 avg60=0.00 avg300=0.00 total=0\n"
         "full avg10=0.00 avg60=0.00 avg300=0.00 total=0\n"),
        ("memory.reclaim", ""),
        ("memory.stat", "anon %d\nfile 0\nkernel %d\nslab 0\n"
         % (mem, int(mem * 0.08))),
        ("memory.swap.current", "0\n"),
        ("memory.swap.events", "high 0\nmax 0\nfail 0\n"),
        ("memory.swap.high", "max\n"),
        ("memory.swap.max", "max\n"),
        ("memory.swap.peak", "0\n"),
        ("pids.current", "%d\n" % (len(procs) if tasks is None else tasks)),
        ("pids.events", "max 0\n"),
        ("pids.max", "max\n"),
        ("pids.peak", "%d\n" % max(1, len(procs))),
    ]
    return out


